	}
}

package com.codex.plunder.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Where the clock goes. Each room the player crosses on the way to their deepest is timed over
 * their recent runs without its searches (the trap, the walk and finding the door), so a run
 * that searched more is not counted slow. The usual crossing against the quickest ever is time a
 * run could have spent searching deeper, and that is turned into experience an hour at what the next unplanned
 * search would pay. It also says when the player's own urn times room by room change the plan.
 */
public final class Leaks
{
	/** Recent runs the usual crossing is read from. */
	public static final int RECENT = 20;
	/** Runs a room needs timed before its usual crossing is told. */
	public static final int MIN_RUNS = 3;
	/** A gap under two seconds is the ordinary spread of a room's crossings, not time to find. */
	public static final int NOISE = 3;

	/** One room's crossing: usual against quickest. */
	public static final class Leak
	{
		private final Room room;
		private final int typical;
		private final int quickest;
		private final int xpPerHour;

		Leak(Room room, int typical, int quickest, int xpPerHour)
		{
			this.room = room;
			this.typical = typical;
			this.quickest = quickest;
			this.xpPerHour = xpPerHour;
		}

		public Room getRoom()
		{
			return room;
		}

		/** The median crossing over recent runs, in ticks. */
		public int getTypical()
		{
			return typical;
		}

		/** The quickest crossing ever, in ticks. */
		public int getQuickest()
		{
			return quickest;
		}

		/** Ticks the usual crossing gives away to the quickest. */
		public int getGap()
		{
			return Math.max(0, typical - quickest);
		}

		/** Experience an hour the gap costs; nothing for a gap within the ordinary spread. */
		public int getXpPerHour()
		{
			return xpPerHour;
		}
	}

	private final Room top;
	private final List<Leak> rooms;
	private final int runs;
	private final Room fasterUrnsFrom;
	private final Room fasterUrnsTo;
	private final int movedUrns;
	private final int urnGain;

	private Leaks(Room top, List<Leak> rooms, int runs, Room fasterUrnsFrom, Room fasterUrnsTo, int movedUrns, int urnGain)
	{
		this.top = top;
		this.rooms = rooms;
		this.runs = runs;
		this.fasterUrnsFrom = fasterUrnsFrom;
		this.fasterUrnsTo = fasterUrnsTo;
		this.movedUrns = movedUrns;
		this.urnGain = urnGain;
	}

	/**
	 * @param runs every run kept, oldest first
	 * @param level the player's real Thieving level
	 */
	public static Leaks of(List<Run> runs, Goal goal, int level, Pace pace)
	{
		Room top = Room.highest(level);
		if (top == null || pace == null)
		{
			return new Leaks(top, Collections.emptyList(), 0, null, null, 0, 0);
		}
		Plan fresh = Planner.fresh(level, goal, pace);

		List<Run> recent = new ArrayList<>();
		int[] quickest = new int[Room.values().length];
		Arrays.fill(quickest, -1);
		if (runs != null)
		{
			for (Run run : runs)
			{
				if (!Splits.comparable(run, goal, top))
				{
					continue;
				}
				recent.add(run);
				for (int i = 0; i < top.ordinal(); i++)
				{
					int seg = run.passAt(Room.values()[i]);
					if (seg >= 0 && (quickest[i] < 0 || seg < quickest[i]))
					{
						quickest[i] = seg;
					}
				}
			}
		}
		if (recent.size() > RECENT)
		{
			recent = recent.subList(recent.size() - RECENT, recent.size());
		}

		double perTick = valuePerTick(fresh, pace);
		double runsPerHour = Planner.TICKS_PER_HOUR / Math.max(1, Math.min(fresh.getTicksLeft(), fresh.getTicksNeeded()) + Planner.RESTART_TICKS);
		List<Leak> leaks = new ArrayList<>();
		for (int i = 0; i < top.ordinal(); i++)
		{
			Room room = Room.values()[i];
			List<Integer> segs = new ArrayList<>();
			for (Run run : recent)
			{
				int seg = run.passAt(room);
				if (seg >= 0)
				{
					segs.add(seg);
				}
			}
			if (segs.size() < MIN_RUNS || quickest[i] < 0)
			{
				continue;
			}
			Collections.sort(segs);
			int typical = segs.get(segs.size() / 2);
			int gap = Math.max(0, typical - quickest[i]);
			int cost = gap < NOISE ? 0 : (int) Math.round(gap * perTick * runsPerHour);
			leaks.add(new Leak(room, typical, quickest[i], cost));
		}

		// The plan the one pace across rooms would make, against the one the player's own times make.
		Room from = null;
		Room to = null;
		int moved = 0;
		int gain = 0;
		Plan flat = Planner.fresh(level, goal, pace.flat());
		if (flat != null && goal == Goal.EXPERIENCE)
		{
			int most = 0;
			int least = 0;
			for (Plan.Stop own : fresh.getStops())
			{
				Plan.Stop other = flat.stop(own.getRoom());
				int d = own.getUrns() - (other == null ? 0 : other.getUrns());
				if (d < least)
				{
					least = d;
					from = own.getRoom();
				}
				if (d > most)
				{
					most = d;
					to = own.getRoom();
				}
			}
			if (from != null && to != null)
			{
				moved = Math.min(most, -least);
				// What the flat plan would really earn, timed at the player's own pace room by room.
				gain = fresh.getThievingXp() - timedAtOwnPace(flat, fresh, pace);
			}
			if (moved <= 0 || gain <= 0)
			{
				from = null;
				to = null;
				moved = 0;
				gain = 0;
			}
		}
		return new Leaks(top, Collections.unmodifiableList(leaks), recent.size(), from, to, moved, gain);
	}

	/**
	 * Experience the flat plan's searches would earn within the clock when each urn takes the
	 * player's own time in its room: urns that no longer fit are dropped from the deepest room up
	 * the cheapest way, by what they pay per tick.
	 */
	private static int timedAtOwnPace(Plan flat, Plan own, Pace pace)
	{
		double over = 0;
		List<double[]> urns = new ArrayList<>();
		for (Plan.Stop s : flat.getStops())
		{
			Room r = s.getRoom();
			over += s.getUrns() * (pace.urn(r) - pace.urn());
			for (int u = 0; u < s.getUrns(); u++)
			{
				urns.add(new double[]{r.getUrnXp() / pace.urn(r), pace.urn(r), r.getUrnXp()});
			}
		}
		int xp = flat.getThievingXp();
		// The flat plan believed it fitted; the time it is over by now comes off its worst urns.
		urns.sort((a, b) -> Double.compare(a[0], b[0]));
		for (double[] u : urns)
		{
			if (over <= 0)
			{
				break;
			}
			over -= u[1];
			xp -= (int) u[2];
		}
		return xp;
	}

	/** What one more tick of clock is worth: the best urn the plan leaves closed, or a run's own rate when it leaves none. */
	static double valuePerTick(Plan fresh, Pace pace)
	{
		double best = 0;
		for (Plan.Stop s : fresh.getStops())
		{
			Room r = s.getRoom();
			if (r.getUrns() - s.getUrns() > 0)
			{
				best = Math.max(best, r.getUrnXp() / pace.urn(r));
			}
		}
		if (best > 0)
		{
			return best;
		}
		return fresh.getThievingXp() / (double) Math.max(1, Math.min(fresh.getTicksLeft(), fresh.getTicksNeeded()) + Planner.RESTART_TICKS);
	}

	public Room getTop()
	{
		return top;
	}

	/** Every room with enough recent crossings, shallowest first. */
	public List<Leak> getRooms()
	{
		return rooms;
	}

	/** Comparable runs the usual crossings come from. */
	public int getRuns()
	{
		return runs;
	}

	/** The room whose usual crossing gives the most away, or null when none is past the ordinary spread. */
	public Leak biggest()
	{
		Leak best = null;
		for (Leak l : rooms)
		{
			if (l.getGap() >= NOISE && (best == null || l.getXpPerHour() > best.getXpPerHour()))
			{
				best = l;
			}
		}
		return best;
	}

	/** Experience an hour every room's gap costs together. */
	public int total()
	{
		int sum = 0;
		for (Leak l : rooms)
		{
			sum += l.getXpPerHour();
		}
		return sum;
	}

	/** The room the player's own urn times move urns away from, or null when they change nothing. */
	public Room getFasterUrnsFrom()
	{
		return fasterUrnsFrom;
	}

	/** The room those urns move to. */
	public Room getFasterUrnsTo()
	{
		return fasterUrnsTo;
	}

	public int getMovedUrns()
	{
		return movedUrns;
	}

	/** Experience a run the move is worth. */
	public int getUrnGain()
	{
		return urnGain;
	}
}

package com.codex.plunder.core;

/** The experience table, for how far a goal level is. */
public final class Levels
{
	private static final int[] XP = new int[127];
	/** The highest level a skill shows. */
	public static final int MAX = 99;
	/** The most experience a skill can hold. */
	public static final long MAX_XP = 200_000_000;

	static
	{
		double points = 0;
		for (int level = 1; level < XP.length; level++)
		{
			XP[level] = (int) Math.floor(points / 4);
			points += Math.floor(level + 300 * Math.pow(2, level / 7.0));
		}
	}

	private Levels()
	{
	}

	/** Experience at the start of a level, 1 to 126. */
	public static int xpFor(int level)
	{
		return XP[Math.max(1, Math.min(XP.length - 1, level))];
	}

	public static int levelFor(long xp)
	{
		int level = 1;
		while (level < 99 && XP[level + 1] <= xp)
		{
			level++;
		}
		return level;
	}
}

package com.codex.plunder.core;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/**
 * Everything kept per account: the learned pace, the chosen goal, every run, and every chest
 * and sarcophagus ever opened per room, which is what the sceptre odds are counted from.
 */
public final class Logbook
{
	/** Runs kept in full; older runs still count in the totals. */
	static final int KEEP = 300;
	/**
	 * A save at least this long is read off the client thread. 300 runs come to about 80,000
	 * characters and take about 5 ms to read and check; a hand-edited save can be far longer.
	 */
	public static final int LARGE = 40_000;

	private Pace pace = new Pace();
	private Goal goal = Goal.EXPERIENCE;
	private int level;
	private long xp;
	private List<Run> runs = new ArrayList<>();
	private long[] opened = new long[Room.values().length];
	private int sceptres;
	private long totalRuns;
	private long totalXp;
	private long totalArtefacts;
	private long totalTicks;
	private Sceptre sceptre = new Sceptre();
	/** Artefacts in the bank as last seen here, by item id. */
	private Map<Integer, Long> banked = new TreeMap<>();
	private long bankedAt;

	public Pace getPace()
	{
		return pace;
	}

	public Goal getGoal()
	{
		return goal;
	}

	public void setGoal(Goal goal)
	{
		this.goal = goal == null ? Goal.EXPERIENCE : goal;
	}

	/** The Thieving level as last seen, so the panel plans while logged out. */
	public int getLevel()
	{
		return level;
	}

	public long getXp()
	{
		return xp;
	}

	public void seen(int level, long xp)
	{
		this.level = level;
		this.xp = xp;
	}

	/** The sceptre's charges and where it was last seen. */
	public Sceptre getSceptre()
	{
		if (sceptre == null)
		{
			sceptre = new Sceptre();
		}
		return sceptre;
	}

	/** Artefacts in the bank as last seen here. */
	public Map<Integer, Long> getBanked()
	{
		return Collections.unmodifiableMap(banked);
	}

	/** When the bank was last seen here, 0 for never. */
	public long getBankedAt()
	{
		return bankedAt;
	}

	/**
	 * The artefacts the bank holds, seen now. The time of the look matters as much as what it
	 * found: an unchanged bank seen again is still this plugin's newer look, and a save holding
	 * only the older time would let Bank Steward's snapshot of the same visit look newer.
	 *
	 * @return whether the save no longer matches, which is whenever the bank is seen at a new time
	 */
	public boolean setBanked(Map<Integer, Long> artefacts, long at)
	{
		Map<Integer, Long> next = new TreeMap<>(artefacts);
		boolean changed = !next.equals(banked) || at != bankedAt;
		banked = next;
		bankedAt = at;
		return changed;
	}

	public List<Run> getRuns()
	{
		return Collections.unmodifiableList(runs);
	}

	public long[] getOpened()
	{
		return opened.clone();
	}

	public long openedTotal()
	{
		long n = 0;
		for (long o : opened)
		{
			n += o;
		}
		return n;
	}

	public int getSceptres()
	{
		return sceptres;
	}

	public long getTotalRuns()
	{
		return totalRuns;
	}

	public long getTotalXp()
	{
		return totalXp;
	}

	public long getTotalArtefacts()
	{
		return totalArtefacts;
	}

	public long getTotalTicks()
	{
		return totalTicks;
	}

	public void record(Run run, long[] openedThisRun)
	{
		runs.add(run);
		while (runs.size() > KEEP)
		{
			runs.remove(0);
		}
		for (int i = 0; i < opened.length && i < openedThisRun.length; i++)
		{
			opened[i] += openedThisRun[i];
		}
		if (run.isSceptre())
		{
			sceptres++;
		}
		totalRuns++;
		totalXp += run.getThievingXp();
		totalArtefacts += run.getArtefacts();
		totalTicks += run.getTicks();
	}

	/**
	 * The sceptre turned up just after the last run was closed, since finding it throws the player
	 * out of the pyramid at once.
	 */
	public void sceptreAfter()
	{
		if (runs.isEmpty())
		{
			return;
		}
		Run last = runs.get(runs.size() - 1);
		if (!last.isSceptre())
		{
			last.markSceptre();
			sceptres++;
		}
	}

	/**
	 * Free slots a run like this one needs for its artefacts: the most picked up in any of the
	 * last few runs, or a guess from the plan before there are three runs to go on.
	 */
	public int slotsNeeded(Plan plan, int last)
	{
		int n = 0;
		int most = 0;
		for (int i = runs.size() - 1; i >= 0 && n < last; i--, n++)
		{
			most = Math.max(most, runs.get(i).getArtefactCount());
		}
		if (n >= 3)
		{
			return most;
		}
		int guess = 0;
		for (Plan.Stop s : plan.getStops())
		{
			guess += s.getUrns() + (s.isChest() ? 3 : 0) + (s.isSarcophagus() ? 3 : 0);
		}
		// Roughly one urn in three holds an artefact; chests and sarcophagi nearly always do.
		return (int) Math.ceil(guess / 3.0);
	}

	/**
	 * Thieving experience an hour over the last few runs, each counted with the usual walk back in
	 * between runs, or 0 before there are two runs to go on.
	 */
	public int recentRate(int last)
	{
		int n = 0;
		long xp = 0;
		long ticks = 0;
		for (int i = runs.size() - 1; i >= 0 && n < last; i--)
		{
			Run r = runs.get(i);
			xp += r.getThievingXp();
			ticks += r.getTicks() + Planner.RESTART_TICKS;
			n++;
		}
		return n < 2 || ticks <= 0 ? 0 : (int) Math.round(xp * Planner.TICKS_PER_HOUR / ticks);
	}

	/**
	 * Reads the logbook saved for an account, or a fresh one when there is none. A damaged save
	 * keeps all it can: a field or run that cannot be read is lost alone.
	 */
	public static Logbook read(Gson gson, String saved)
	{
		Logbook read = Salvage.read(gson, saved, Logbook.class);
		return read == null ? new Logbook() : read.repair();
	}

	/** Puts back what an older or damaged save left out. */
	public Logbook repair()
	{
		if (pace == null)
		{
			pace = new Pace();
		}
		pace.repair();
		if (goal == null)
		{
			goal = Goal.EXPERIENCE;
		}
		if (runs == null)
		{
			runs = new ArrayList<>();
		}
		runs.removeIf(r -> r == null);
		runs.forEach(Run::repair);
		while (runs.size() > KEEP)
		{
			runs.remove(0);
		}
		// A level or count out of what the game allows is damage, brought back into range.
		level = Math.max(0, Math.min(Levels.MAX, level));
		xp = Math.max(0, Math.min(Levels.MAX_XP, xp));
		sceptres = Math.max(0, sceptres);
		totalRuns = Math.max(Math.max(0, totalRuns), runs.size());
		totalXp = Math.max(0, totalXp);
		totalArtefacts = Math.max(0, totalArtefacts);
		totalTicks = Math.max(0, totalTicks);
		bankedAt = Math.max(0, bankedAt);
		if (sceptre == null)
		{
			sceptre = new Sceptre();
		}
		banked = banked == null ? new TreeMap<>() : new TreeMap<>(banked);
		banked.entrySet().removeIf(e -> e.getKey() == null || e.getValue() == null || e.getValue() <= 0);
		if (opened == null || opened.length != Room.values().length)
		{
			long[] fixed = new long[Room.values().length];
			if (opened != null)
			{
				System.arraycopy(opened, 0, fixed, 0, Math.min(opened.length, fixed.length));
			}
			opened = fixed;
		}
		for (int i = 0; i < opened.length; i++)
		{
			opened[i] = Math.max(0, opened[i]);
		}
		return this;
	}
}

package com.codex.plunder.core;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The Thieving levels Codex Navigator's pinned goals still need. Navigator saves its goal board
 * for companion plugins under the RS profile key {@code codexnavigator.goalBoard} (fields are
 * only ever added); this keeps each unfinished goal's title and levels. Read only, and with
 * Navigator not installed there is no board and nothing is shown.
 */
public final class NavigatorGoals
{
	public static final String GROUP = "codexnavigator";
	public static final String KEY = "goalBoard";

	/** One pinned goal, as saved. Field names are Navigator's. */
	static final class Entry
	{
		String key;
		String title;
		boolean complete;
		Map<String, Integer> skills;
	}

	/** Navigator's saved board, as far as it is read here. */
	static final class Board
	{
		String focus;
		List<Entry> goals;
	}

	/** A level one goal needs. */
	public static final class Need
	{
		private final String goal;
		private final int level;
		private final boolean focus;

		Need(String goal, int level, boolean focus)
		{
			this.goal = goal;
			this.level = level;
			this.focus = focus;
		}

		/** The goal's title, such as "Desert Treasure II". */
		public String getGoal()
		{
			return goal;
		}

		public int getLevel()
		{
			return level;
		}

		/** The goal Navigator has in focus. */
		public boolean isFocus()
		{
			return focus;
		}
	}

	private NavigatorGoals()
	{
	}

	/**
	 * @param json the board as Navigator saved it, or null
	 * @param skill the skill's name, such as "Thieving"
	 * @param level the level now
	 * @return every unfinished goal that needs the skill above that level, the focus goal first, then lowest level first
	 */
	public static List<Need> needs(Gson gson, String json, String skill, int level)
	{
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		Board board;
		try
		{
			board = gson.fromJson(json, Board.class);
		}
		catch (JsonParseException | IllegalStateException e)
		{
			return Collections.emptyList();
		}
		if (board == null || board.goals == null)
		{
			return Collections.emptyList();
		}
		List<Need> out = new ArrayList<>();
		for (Entry e : board.goals)
		{
			if (e == null || e.complete || e.skills == null)
			{
				continue;
			}
			for (Map.Entry<String, Integer> s : e.skills.entrySet())
			{
				Integer need = s.getValue();
				if (s.getKey() != null && s.getKey().equalsIgnoreCase(skill) && need != null && need > level && need <= 99)
				{
					String title = e.title == null || e.title.isEmpty() ? "A Navigator goal" : e.title;
					out.add(new Need(title, need, e.key != null && e.key.equals(board.focus)));
				}
			}
		}
		out.sort((a, b) -> a.focus != b.focus ? (a.focus ? -1 : 1) : Integer.compare(a.level, b.level));
		return out;
	}
}

package com.codex.plunder.core;

/** Sceptre arithmetic: what a number of chests and sarcophagi should have turned up. */
public final class Odds
{
	private Odds()
	{
	}

	/** The chance of at least one sceptre from these openings, per room. */
	public static double atLeastOne(long[] opened)
	{
		double logMiss = 0;
		for (Room r : Room.values())
		{
			long n = at(opened, r);
			logMiss += n * Math.log1p(-r.sceptreChance());
		}
		return 1 - Math.exp(logMiss);
	}

	/** Sceptres these openings should have turned up on average. */
	public static double expected(long[] opened)
	{
		double sum = 0;
		for (Room r : Room.values())
		{
			sum += at(opened, r) * r.sceptreChance();
		}
		return sum;
	}

	/**
	 * How lucky the player has been, from 0 (as dry as it gets) to 1 (as lucky as it gets): the
	 * share of players opening the same chests who would have found fewer sceptres, counting half
	 * of those who found exactly as many.
	 */
	public static double luck(long[] opened, int found)
	{
		double lambda = expected(opened);
		if (lambda <= 0)
		{
			return 0.5;
		}
		double below = 0;
		double term = Math.exp(-lambda);
		for (int k = 0; k < found; k++)
		{
			below += term;
			term *= lambda / (k + 1);
		}
		return Math.min(1, below + term / 2);
	}

	/** Runs at this per-run chance before the odds of a sceptre reach the given share. */
	public static int runsFor(double perRun, double share)
	{
		if (perRun <= 0)
		{
			return Integer.MAX_VALUE;
		}
		if (perRun >= 1)
		{
			return 1;
		}
		return (int) Math.ceil(Math.log1p(-share) / Math.log1p(-perRun));
	}

	private static long at(long[] opened, Room r)
	{
		return opened == null || opened.length <= r.ordinal() ? 0 : opened[r.ordinal()];
	}
}

package com.codex.plunder.core;

import java.util.List;

/**
 * How much the player plays, read from their own sessions over the last four weeks, so a number
 * of runs or hours can be turned into a date: "even odds of a sceptre by 12 Nov". Only sessions
 * that started inside the window count, and a window younger than a week is stretched to a week,
 * so one long first evening does not read as playing every day.
 */
public final class Outlook
{
	static final long DAY_MS = 24 * 3_600_000L;
	/** How far back the pace is read. */
	static final long WINDOW_MS = 28 * DAY_MS;
	/** The least history a pace is read from. */
	static final long MIN_SPAN_MS = 7 * DAY_MS;
	/** Fewer sessions than this say nothing about how often the player comes back. */
	static final int MIN_SESSIONS = 2;
	/** Past this a date says nothing useful. */
	static final long MAX_DAYS = 3 * 365;

	private final int sessions;
	private final int runs;
	private final long playedMs;
	private final long spanMs;

	private Outlook(int sessions, int runs, long playedMs, long spanMs)
	{
		this.sessions = sessions;
		this.runs = runs;
		this.playedMs = playedMs;
		this.spanMs = spanMs;
	}

	/**
	 * @param history every session kept, newest first, as {@link Session#history} gives them
	 * @param now the time now
	 */
	public static Outlook of(List<Session> history, long now)
	{
		int n = 0;
		int runs = 0;
		long played = 0;
		long first = now;
		for (Session s : history)
		{
			if (s.isEmpty() || s.getStartedAt() < now - WINDOW_MS)
			{
				continue;
			}
			n++;
			runs += s.getRuns().size();
			played += s.spanMs();
			first = Math.min(first, s.getStartedAt());
		}
		return new Outlook(n, runs, played, Math.max(MIN_SPAN_MS, now - first));
	}

	/** Enough sessions to tell a pace from. */
	public boolean isKnown()
	{
		return sessions >= MIN_SESSIONS && playedMs > 0 && runs > 0;
	}

	/** Hours played a week. */
	public double hoursPerWeek()
	{
		return playedMs / 3_600_000.0 * (7.0 * DAY_MS / spanMs);
	}

	/** Runs played an hour, the walk back included. */
	public double runsPerHour()
	{
		return playedMs <= 0 ? 0 : runs * 3_600_000.0 / playedMs;
	}

	/**
	 * @return when that many more hours of play are done at this pace, or -1 when it cannot be told or is years away
	 */
	public long afterHours(double hours, long now)
	{
		if (!isKnown() || hours < 0)
		{
			return -1;
		}
		double days = hours / hoursPerWeek() * 7;
		return days > MAX_DAYS ? -1 : now + Math.round(days * DAY_MS);
	}

	/** @return when that many more runs are played at this pace, or -1 when it cannot be told or is years away */
	public long afterRuns(long runs, long now)
	{
		double perHour = runsPerHour();
		return perHour <= 0 ? -1 : afterHours(runs / perHour, now);
	}
}

package com.codex.plunder.core;

/**
 * How long things take, in game ticks. It starts from typical times and learns the player's own
 * from their runs, so the plan fits the hands that play it.
 */
public final class Pace
{
	/** A search, with the odd failure and the walk to the next urn. */
	static final double URN = 10;
	static final double CHEST = 6;
	static final double SARCOPHAGUS = 12;
	/** Disarming the spear trap, finding the true door among four and walking through. */
	static final double PASS = 25;
	/** Only the spear trap, for the room the run ends in. */
	static final double TRAP = 6;
	/** Weight of each new measurement once a pace is settled. */
	private static final double LEARN = 1 / 8.0;
	/** Measurements before the learned pace is used. */
	public static final int TRUSTED = 6;

	private double urn = URN;
	private double chest = CHEST;
	private double sarcophagus = SARCOPHAGUS;
	private double pass = PASS;
	private int urnSamples;
	private int passSamples;
	/** The urn pace in each room, which differs as a room's urns fail more often near its entry level. Older saves have none. */
	private double[] urnByRoom;
	private int[] urnSamplesByRoom;

	public double urn()
	{
		return urnSamples >= TRUSTED ? urn : URN;
	}

	/**
	 * The urn pace in one room: the player's own there once it is settled, otherwise the pace
	 * across every room.
	 */
	public double urn(Room room)
	{
		int i = room == null ? -1 : room.ordinal();
		if (i >= 0 && urnByRoom != null && urnSamplesByRoom != null && i < urnByRoom.length && i < urnSamplesByRoom.length
			&& urnSamplesByRoom[i] >= TRUSTED)
		{
			return urnByRoom[i];
		}
		return urn();
	}

	/** Urn searches timed in one room. */
	public int getUrnSamples(Room room)
	{
		int i = room == null ? -1 : room.ordinal();
		return i < 0 || urnSamplesByRoom == null || i >= urnSamplesByRoom.length ? 0 : urnSamplesByRoom[i];
	}

	/** Whether the room's own urn pace is settled and used. */
	public boolean knowsUrns(Room room)
	{
		return getUrnSamples(room) >= TRUSTED;
	}

	public double chest()
	{
		return chest;
	}

	public double sarcophagus()
	{
		return sarcophagus;
	}

	public double pass()
	{
		return passSamples >= TRUSTED ? pass : PASS;
	}

	public double trap()
	{
		return TRAP;
	}

	public int getUrnSamples()
	{
		return urnSamples;
	}

	public int getPassSamples()
	{
		return passSamples;
	}

	/** One urn took this many ticks, from the last search to this one. */
	public void urnTook(int ticks)
	{
		urnTook(null, ticks);
	}

	/** One urn in this room took this many ticks, from the last search to this one. */
	public void urnTook(Room room, int ticks)
	{
		if (ticks < 3 || ticks > 40)
		{
			return;
		}
		urn = blend(urn, ticks, urnSamples++);
		if (room != null)
		{
			int n = Room.values().length;
			if (urnByRoom == null || urnByRoom.length != n || urnSamplesByRoom == null || urnSamplesByRoom.length != n)
			{
				urnByRoom = new double[n];
				urnSamplesByRoom = new int[n];
			}
			int i = room.ordinal();
			urnByRoom[i] = blend(urnByRoom[i], ticks, urnSamplesByRoom[i]++);
		}
	}

	/** Getting through one room, from its last search to the next room, took this many ticks. */
	public void passTook(int ticks)
	{
		if (ticks < 8 || ticks > 120)
		{
			return;
		}
		pass = blend(pass, ticks, passSamples++);
	}

	/** A plain mean over the first few measurements, then a slow moving average. */
	private static double blend(double current, double sample, int seen)
	{
		if (seen == 0)
		{
			return sample;
		}
		double weight = seen < 8 ? 1.0 / (seen + 1) : LEARN;
		return current + (sample - current) * weight;
	}

	/** This pace with every room's urns at the one pace across rooms, as before rooms were told apart. */
	public Pace flat()
	{
		Pace p = new Pace();
		p.urn = urn;
		p.chest = chest;
		p.sarcophagus = sarcophagus;
		p.pass = pass;
		p.urnSamples = urnSamples;
		p.passSamples = passSamples;
		return p;
	}

	/** Puts back defaults that an older or damaged save left out. */
	Pace repair()
	{
		if (!(urn > 0 && urn < Planner.RUN_TICKS))
		{
			urn = URN;
		}
		if (!(chest > 0 && chest < Planner.RUN_TICKS))
		{
			chest = CHEST;
		}
		if (!(sarcophagus > 0 && sarcophagus < Planner.RUN_TICKS))
		{
			sarcophagus = SARCOPHAGUS;
		}
		if (!(pass > 0 && pass < Planner.RUN_TICKS))
		{
			pass = PASS;
		}
		urnSamples = Math.max(0, urnSamples);
		passSamples = Math.max(0, passSamples);
		int n = Room.values().length;
		if (urnByRoom != null || urnSamplesByRoom != null)
		{
			double[] rates = new double[n];
			int[] samples = new int[n];
			for (int i = 0; i < n; i++)
			{
				double r = urnByRoom != null && i < urnByRoom.length ? urnByRoom[i] : 0;
				int c = urnSamplesByRoom != null && i < urnSamplesByRoom.length ? urnSamplesByRoom[i] : 0;
				// A room's pace that is out of range, or has no count beside it, starts again.
				boolean ok = r >= 3 && r <= 40 && c > 0;
				rates[i] = ok ? r : 0;
				samples[i] = ok ? c : 0;
			}
			urnByRoom = rates;
			urnSamplesByRoom = samples;
		}
		return this;
	}
}

package com.codex.plunder.core;

import java.util.Collections;
import java.util.List;

/** What to do in each room still ahead this run, and what that is expected to earn. */
public final class Plan
{
	/** One room's share of the plan. */
	public static final class Stop
	{
		private final Room room;
		private final int urns;
		private final int urnsLeft;
		private final boolean chest;
		private final boolean sarcophagus;
		private final boolean chestOpen;
		private final boolean sarcophagusOpen;

		Stop(Room room, int urns, int urnsLeft, boolean chest, boolean sarcophagus, boolean chestOpen, boolean sarcophagusOpen)
		{
			this.room = room;
			this.urns = urns;
			this.urnsLeft = urnsLeft;
			this.chest = chest;
			this.sarcophagus = sarcophagus;
			this.chestOpen = chestOpen;
			this.sarcophagusOpen = sarcophagusOpen;
		}

		public Room getRoom()
		{
			return room;
		}

		/** Urns worth searching here, not counting those already searched. */
		public int getUrns()
		{
			return urns;
		}

		/** Urns still closed here. */
		public int getUrnsLeft()
		{
			return urnsLeft;
		}

		/** The grand gold chest is worth opening. */
		public boolean isChest()
		{
			return chest;
		}

		public boolean isSarcophagus()
		{
			return sarcophagus;
		}

		public boolean isChestOpen()
		{
			return chestOpen;
		}

		public boolean isSarcophagusOpen()
		{
			return sarcophagusOpen;
		}

		/** Nothing here is worth the time: pass straight through. */
		public boolean isPassThrough()
		{
			return urns == 0 && !chest && !sarcophagus;
		}
	}

	private final Goal goal;
	private final Room top;
	private final List<Stop> stops;
	private final int thievingXp;
	private final int strengthXp;
	private final double sceptreChance;
	private final int ticksNeeded;
	private final int ticksLeft;

	Plan(Goal goal, Room top, List<Stop> stops, int thievingXp, int strengthXp, double sceptreChance, int ticksNeeded, int ticksLeft)
	{
		this.goal = goal;
		this.top = top;
		this.stops = Collections.unmodifiableList(stops);
		this.thievingXp = thievingXp;
		this.strengthXp = strengthXp;
		this.sceptreChance = sceptreChance;
		this.ticksNeeded = ticksNeeded;
		this.ticksLeft = ticksLeft;
	}

	public Goal getGoal()
	{
		return goal;
	}

	/** The deepest room this level opens, where the run ends. */
	public Room getTop()
	{
		return top;
	}

	public List<Stop> getStops()
	{
		return stops;
	}

	/** The stop for the room the player is in, or the first ahead. */
	public Stop current()
	{
		return stops.isEmpty() ? null : stops.get(0);
	}

	public Stop stop(Room room)
	{
		for (Stop s : stops)
		{
			if (s.room == room)
			{
				return s;
			}
		}
		return null;
	}

	/** Thieving experience the rest of the plan is expected to earn. */
	public int getThievingXp()
	{
		return thievingXp;
	}

	public int getStrengthXp()
	{
		return strengthXp;
	}

	/** The chance the rest of the plan turns up a sceptre. */
	public double getSceptreChance()
	{
		return sceptreChance;
	}

	public int getTicksNeeded()
	{
		return ticksNeeded;
	}

	public int getTicksLeft()
	{
		return ticksLeft;
	}

	/** Ticks the plan leaves unused; with plenty spare it is quicker to leave and start afresh. */
	public int spare()
	{
		return Math.max(0, ticksLeft - ticksNeeded);
	}

	/** Thieving experience an hour if every run went like this one, counting the walk back in. */
	public int xpPerHour(int restartTicks)
	{
		int used = Math.max(1, Math.min(ticksLeft, ticksNeeded) + restartTicks);
		return (int) Math.round(thievingXp * (Planner.TICKS_PER_HOUR / used));
	}

	/** A whole run's worth of sceptre chances in an hour, as the chance of at least one. */
	public double sceptrePerHour(int restartTicks)
	{
		int used = Math.max(1, Math.min(ticksLeft, ticksNeeded) + restartTicks);
		double runs = Planner.TICKS_PER_HOUR / used;
		return 1 - Math.pow(1 - sceptreChance, runs);
	}
}

package com.codex.plunder.core;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;

/**
 * Plans the rest of a run against the clock. Getting through each room costs a fixed time;
 * what is left is shared out among the urns, chests and sarcophagi by what the goal values most
 * per tick, so the deepest rooms' urns win and the shallow rooms are walked straight through.
 * It is planned again every tick, so a slow room simply shortens what follows.
 */
public final class Planner
{
	/** A run lasts five minutes. */
	public static final int RUN_TICKS = 500;
	/** Leaving, talking to the mummy and getting back in, between runs. */
	public static final int RESTART_TICKS = 60;
	static final double TICKS_PER_HOUR = 6000;
	/** Ticks held back so the last search is not cut off by the clock. */
	static final int MARGIN = 10;

	private Planner()
	{
	}

	private enum Kind
	{
		URN,
		CHEST,
		SARCOPHAGUS
	}

	private static final class Option
	{
		final Room room;
		final Kind kind;
		final int tier;
		final double ticks;
		final double density;

		Option(Room room, Kind kind, int tier, double ticks, double value)
		{
			this.room = room;
			this.kind = kind;
			this.tier = tier;
			this.ticks = ticks;
			this.density = value / ticks;
		}
	}

	/**
	 * @param level the player's real Thieving level
	 * @param here where the run stands, or null for a run not yet begun
	 * @param ticksLeft ticks on the clock
	 * @return the plan, or null below the pyramid's entry level
	 */
	public static Plan plan(int level, Goal goal, Pace pace, Here here, int ticksLeft)
	{
		Room top = Room.highest(level);
		if (top == null)
		{
			return null;
		}
		if (here == null)
		{
			here = Here.start();
		}
		Room start = here.getRoom().ordinal() > top.ordinal() ? top : here.getRoom();

		double fixed = 0;
		int xp = 0;
		List<Option> options = new ArrayList<>();
		for (int i = start.ordinal(); i <= top.ordinal(); i++)
		{
			Room room = Room.values()[i];
			boolean first = room == start;
			boolean trapDone = first && here.isTrapDone();
			if (!trapDone)
			{
				xp += Room.TRAP_XP;
			}
			if (room == top)
			{
				fixed += trapDone ? 0 : pace.trap();
			}
			else
			{
				fixed += trapDone ? pace.pass() - pace.trap() : pace.pass();
				xp += room.getDoorXp();
			}

			int urns = first ? here.getUrnsLeft() : room.getUrns();
			for (int u = 0; u < urns; u++)
			{
				options.add(new Option(room, Kind.URN, 1, pace.urn(room), room.getUrnXp()));
			}
			if (!(first && here.isChestOpen()))
			{
				if (goal == Goal.SCEPTRE)
				{
					options.add(new Option(room, Kind.CHEST, 0, pace.chest(), room.sceptreChance()));
				}
				else
				{
					options.add(new Option(room, Kind.CHEST, room.getNumber() >= 4 ? 0 : 1, pace.chest(), room.getChestXp()));
				}
			}
			// Sarcophagi are slow; only a sceptre hunter wants them, and only where the odds are good.
			if (goal == Goal.SCEPTRE && room.getNumber() >= 4 && !(first && here.isSarcophagusOpen()))
			{
				options.add(new Option(room, Kind.SARCOPHAGUS, 0, pace.sarcophagus(), room.sceptreChance()));
			}
		}

		options.sort(Comparator.<Option>comparingInt(o -> o.tier).thenComparing(o -> -o.density));
		double budget = ticksLeft - fixed - MARGIN;
		double used = fixed;
		int[] urns = new int[Room.values().length];
		boolean[] chest = new boolean[urns.length];
		boolean[] sarcophagus = new boolean[urns.length];
		int strength = 0;
		double miss = 1;
		for (Option o : options)
		{
			if (o.ticks > budget)
			{
				continue;
			}
			budget -= o.ticks;
			used += o.ticks;
			int r = o.room.ordinal();
			switch (o.kind)
			{
				case URN:
					urns[r]++;
					xp += o.room.getUrnXp();
					break;
				case CHEST:
					chest[r] = true;
					xp += o.room.getChestXp();
					miss *= 1 - o.room.sceptreChance();
					break;
				case SARCOPHAGUS:
					sarcophagus[r] = true;
					strength += o.room.getSarcophagusXp();
					miss *= 1 - o.room.sceptreChance();
					break;
			}
		}

		List<Plan.Stop> stops = new ArrayList<>();
		for (int i = start.ordinal(); i <= top.ordinal(); i++)
		{
			Room room = Room.values()[i];
			boolean first = room == start;
			stops.add(new Plan.Stop(room, urns[i], first ? here.getUrnsLeft() : room.getUrns(), chest[i], sarcophagus[i],
				first && here.isChestOpen(), first && here.isSarcophagusOpen()));
		}
		return new Plan(goal, top, stops, xp, strength, 1 - miss, (int) Math.ceil(used), ticksLeft);
	}

	/** A whole fresh run at this level, for the ladder and the forecasts. */
	public static Plan fresh(int level, Goal goal, Pace pace)
	{
		return plan(level, goal, pace, null, RUN_TICKS);
	}
}

package com.codex.plunder.core;

/**
 * The eight rooms of the Jalsavrah pyramid, with what each one pays. Every figure is the
 * game's own as recorded by the Old School wiki: urn, chest and door experience are Thieving,
 * the sarcophagus pays Strength, and the sceptre rate is per chest or sarcophagus opened.
 */
public enum Room
{
	ONE(1, 21, 13, 60, 40, 40, 20, 4200),
	TWO(2, 31, 13, 90, 60, 60, 30, 2800),
	THREE(3, 41, 12, 150, 100, 100, 50, 1600),
	FOUR(4, 51, 13, 215, 140, 140, 70, 950),
	FIVE(5, 61, 13, 300, 200, 200, 100, 800),
	SIX(6, 71, 13, 450, 300, 300, 150, 750),
	SEVEN(7, 81, 13, 675, 450, 450, 225, 650),
	EIGHT(8, 91, 13, 825, 550, 0, 275, 650);

	/** Experience for disarming a room's spear trap. */
	public static final int TRAP_XP = 10;
	/** Lowest Thieving level the pyramid lets in. */
	public static final int ENTRY_LEVEL = 21;

	private final int number;
	private final int level;
	private final int urns;
	private final int urnXp;
	private final int chestXp;
	private final int doorXp;
	private final int sarcophagusXp;
	private final int sceptreOneIn;

	Room(int number, int level, int urns, int urnXp, int chestXp, int doorXp, int sarcophagusXp, int sceptreOneIn)
	{
		this.number = number;
		this.level = level;
		this.urns = urns;
		this.urnXp = urnXp;
		this.chestXp = chestXp;
		this.doorXp = doorXp;
		this.sarcophagusXp = sarcophagusXp;
		this.sceptreOneIn = sceptreOneIn;
	}

	public int getNumber()
	{
		return number;
	}

	public int getLevel()
	{
		return level;
	}

	public int getUrns()
	{
		return urns;
	}

	public int getUrnXp()
	{
		return urnXp;
	}

	public int getChestXp()
	{
		return chestXp;
	}

	/** Thieving experience for the true tomb door; the last room has none. */
	public int getDoorXp()
	{
		return doorXp;
	}

	public int getSarcophagusXp()
	{
		return sarcophagusXp;
	}

	public int getSceptreOneIn()
	{
		return sceptreOneIn;
	}

	/** The chance one chest or sarcophagus here holds the sceptre. */
	public double sceptreChance()
	{
		return 1.0 / sceptreOneIn;
	}

	public boolean isLast()
	{
		return this == EIGHT;
	}

	/** @return the room with this number, or null */
	public static Room of(int number)
	{
		return number < 1 || number > 8 ? null : values()[number - 1];
	}

	/** @return the deepest room a Thieving level opens, or null below 21 */
	public static Room highest(int thievingLevel)
	{
		Room best = null;
		for (Room r : values())
		{
			if (thievingLevel >= r.level)
			{
				best = r;
			}
		}
		return best;
	}

	/** @return the next room's entry level, or 0 when every room is open */
	public static int nextUnlock(int thievingLevel)
	{
		for (Room r : values())
		{
			if (thievingLevel < r.level)
			{
				return r.level;
			}
		}
		return 0;
	}
}

package com.codex.plunder.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * The shortest walk through a room's urns. It starts from where the player stands, visits the
 * urns worth searching once each and ends at the last of them. When the plan wants fewer than
 * the room holds, it takes whichever of them make the shortest walk. A room has at most fifteen
 * urns, so the walk is found exactly rather than guessed.
 */
public final class Route
{
	private Route()
	{
	}

	/**
	 * @param fromX the player's tile
	 * @param xs the urns' tiles, x
	 * @param ys the urns' tiles, y
	 * @param count how many urns to visit
	 * @return indexes into the urns, in walking order
	 */
	public static List<Integer> order(int fromX, int fromY, int[] xs, int[] ys, int count)
	{
		int n = Math.min(xs.length, ys.length);
		count = Math.max(0, Math.min(count, n));
		if (count == 0)
		{
			return Collections.emptyList();
		}
		if (n <= EXACT)
		{
			return exact(fromX, fromY, xs, ys, n, count);
		}
		// Nearest first gives a sound walk; then untangle it by reversing any stretch that shortens it.
		List<Integer> path = new ArrayList<>();
		boolean[] used = new boolean[n];
		int cx = fromX;
		int cy = fromY;
		for (int k = 0; k < count; k++)
		{
			int best = -1;
			int bestD = Integer.MAX_VALUE;
			for (int i = 0; i < n; i++)
			{
				int d = steps(cx, cy, xs[i], ys[i]);
				if (!used[i] && d < bestD)
				{
					best = i;
					bestD = d;
				}
			}
			used[best] = true;
			path.add(best);
			cx = xs[best];
			cy = ys[best];
		}
		boolean better = true;
		while (better)
		{
			better = false;
			for (int i = 0; i < path.size() - 1; i++)
			{
				for (int j = i + 1; j < path.size(); j++)
				{
					if (gain(path, i, j, fromX, fromY, xs, ys) > 0)
					{
						Collections.reverse(path.subList(i, j + 1));
						better = true;
					}
				}
			}
		}
		return path;
	}

	/** Up to this many urns the walk is found exactly: 2^15 subsets is quick. */
	static final int EXACT = 15;

	/** Held-Karp over subsets: the shortest open walk from the start through exactly count urns. */
	private static List<Integer> exact(int fromX, int fromY, int[] xs, int[] ys, int n, int count)
	{
		int full = 1 << n;
		int[] best = new int[full * n];
		byte[] prev = new byte[full * n];
		java.util.Arrays.fill(best, Integer.MAX_VALUE);
		for (int i = 0; i < n; i++)
		{
			best[(1 << i) * n + i] = steps(fromX, fromY, xs[i], ys[i]);
			prev[(1 << i) * n + i] = -1;
		}
		int bestLen = Integer.MAX_VALUE;
		int bestMask = 0;
		int bestEnd = 0;
		for (int mask = 1; mask < full; mask++)
		{
			int size = Integer.bitCount(mask);
			if (size > count)
			{
				continue;
			}
			for (int end = 0; end < n; end++)
			{
				int here = best[mask * n + end];
				if (here == Integer.MAX_VALUE)
				{
					continue;
				}
				if (size == count)
				{
					if (here < bestLen)
					{
						bestLen = here;
						bestMask = mask;
						bestEnd = end;
					}
					continue;
				}
				for (int next = 0; next < n; next++)
				{
					if ((mask & (1 << next)) != 0)
					{
						continue;
					}
					int to = (mask | (1 << next)) * n + next;
					int len = here + steps(xs[end], ys[end], xs[next], ys[next]);
					if (len < best[to])
					{
						best[to] = len;
						prev[to] = (byte) end;
					}
				}
			}
		}
		List<Integer> path = new ArrayList<>();
		int mask = bestMask;
		int end = bestEnd;
		while (end >= 0)
		{
			path.add(end);
			int p = prev[mask * n + end];
			mask &= ~(1 << end);
			end = p;
		}
		Collections.reverse(path);
		return path;
	}

	/** Tiles walked along a path, from the start. */
	public static int length(int fromX, int fromY, int[] xs, int[] ys, List<Integer> path)
	{
		int total = 0;
		int cx = fromX;
		int cy = fromY;
		for (int i : path)
		{
			total += steps(cx, cy, xs[i], ys[i]);
			cx = xs[i];
			cy = ys[i];
		}
		return total;
	}

	/** How much shorter the walk gets by reversing path[i..j]. The path is open at its end. */
	private static int gain(List<Integer> path, int i, int j, int fromX, int fromY, int[] xs, int[] ys)
	{
		int ax = i == 0 ? fromX : xs[path.get(i - 1)];
		int ay = i == 0 ? fromY : ys[path.get(i - 1)];
		int b = path.get(i);
		int c = path.get(j);
		int before = steps(ax, ay, xs[b], ys[b]);
		int after = steps(ax, ay, xs[c], ys[c]);
		if (j + 1 < path.size())
		{
			int d = path.get(j + 1);
			before += steps(xs[c], ys[c], xs[d], ys[d]);
			after += steps(xs[b], ys[b], xs[d], ys[d]);
		}
		return before - after;
	}

	/** Steps between two tiles; the game walks diagonally as cheaply as straight. */
	static int steps(int x1, int y1, int x2, int y2)
	{
		return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
	}
}

package com.codex.plunder.core;

/** One finished trip into the pyramid. */
public final class Run
{
	private long at;
	private int ticks;
	private int deepest;
	private int thievingXp;
	private int strengthXp;
	private int urns;
	private int chests;
	private int sarcophagi;
	private long artefacts;
	private int artefactCount;
	private double sceptreChance;
	private boolean sceptre;
	private Goal goal;
	/** Ticks from the start of the run to entering each room, by room; -1 where not seen. Older saves have none. */
	private int[] splits;
	/** Ticks each room took to cross without its searches: the trap, the walk and the door; -1 where not seen. Older saves have none. */
	private int[] passes;

	Run()
	{
	}

	Run(long at, int ticks, int deepest, int thievingXp, int strengthXp, int urns, int chests, int sarcophagi,
		long artefacts, int artefactCount, double sceptreChance, boolean sceptre, Goal goal)
	{
		this(at, ticks, deepest, thievingXp, strengthXp, urns, chests, sarcophagi, artefacts, artefactCount, sceptreChance, sceptre, goal, null);
	}

	Run(long at, int ticks, int deepest, int thievingXp, int strengthXp, int urns, int chests, int sarcophagi,
		long artefacts, int artefactCount, double sceptreChance, boolean sceptre, Goal goal, int[] splits)
	{
		this(at, ticks, deepest, thievingXp, strengthXp, urns, chests, sarcophagi, artefacts, artefactCount, sceptreChance, sceptre, goal, splits, null);
	}

	Run(long at, int ticks, int deepest, int thievingXp, int strengthXp, int urns, int chests, int sarcophagi,
		long artefacts, int artefactCount, double sceptreChance, boolean sceptre, Goal goal, int[] splits, int[] passes)
	{
		this.splits = splits == null ? null : splits.clone();
		this.passes = passes == null ? null : passes.clone();
		this.artefactCount = artefactCount;
		this.at = at;
		this.ticks = ticks;
		this.deepest = deepest;
		this.thievingXp = thievingXp;
		this.strengthXp = strengthXp;
		this.urns = urns;
		this.chests = chests;
		this.sarcophagi = sarcophagi;
		this.artefacts = artefacts;
		this.sceptreChance = sceptreChance;
		this.sceptre = sceptre;
		this.goal = goal;
	}

	/** When the run began, in epoch milliseconds. */
	public long getAt()
	{
		return at;
	}

	public int getTicks()
	{
		return ticks;
	}

	/** The deepest room reached. */
	public int getDeepest()
	{
		return deepest;
	}

	public int getThievingXp()
	{
		return thievingXp;
	}

	public int getStrengthXp()
	{
		return strengthXp;
	}

	public int getUrns()
	{
		return urns;
	}

	public int getChests()
	{
		return chests;
	}

	public int getSarcophagi()
	{
		return sarcophagi;
	}

	/** What the artefacts picked up were worth at Grand Exchange prices. */
	public long getArtefacts()
	{
		return artefacts;
	}

	/** How many artefacts were picked up, each taking a slot. */
	public int getArtefactCount()
	{
		return artefactCount;
	}

	/** The chance this run's openings had of a sceptre. */
	public double getSceptreChance()
	{
		return sceptreChance;
	}

	public boolean isSceptre()
	{
		return sceptre;
	}

	void markSceptre()
	{
		sceptre = true;
	}

	public Goal getGoal()
	{
		return goal == null ? Goal.EXPERIENCE : goal;
	}

	/**
	 * Ticks from the start of the run to entering the room, or -1 when the run never got there,
	 * entered it before the plugin was watching, or was saved before splits were kept.
	 */
	public int splitAt(Room room)
	{
		return splits == null || room == null || room.ordinal() >= splits.length ? -1 : splits[room.ordinal()];
	}

	/**
	 * Ticks crossing the room took without its searches, or -1 when the run did not cross it,
	 * or was saved before crossings were kept.
	 */
	public int passAt(Room room)
	{
		return passes == null || room == null || room.ordinal() >= passes.length ? -1 : passes[room.ordinal()];
	}

	/** Brings back into range what a damaged save left out of it. */
	void repair()
	{
		ticks = Math.max(0, ticks);
		deepest = Math.max(0, Math.min(Room.values().length, deepest));
		thievingXp = Math.max(0, thievingXp);
		strengthXp = Math.max(0, strengthXp);
		urns = Math.max(0, urns);
		chests = Math.max(0, chests);
		sarcophagi = Math.max(0, sarcophagi);
		artefacts = Math.max(0, artefacts);
		artefactCount = Math.max(0, artefactCount);
		sceptreChance = sceptreChance >= 0 && sceptreChance <= 1 ? sceptreChance : 0;
		if (splits != null)
		{
			for (int k = 0; k < splits.length; k++)
			{
				splits[k] = Math.max(-1, splits[k]);
			}
		}
		if (passes != null)
		{
			for (int k = 0; k < passes.length; k++)
			{
				passes[k] = Math.max(-1, passes[k]);
			}
		}
	}
}

package com.codex.plunder.core;

/**
 * Follows one run from the first spear trap to the way out: what was searched in which room,
 * what it paid, and how long each part took, which teaches the pace.
 */
public final class RunTracker
{
	private boolean active;
	private long startedAt;
	private int startTick;
	private Goal goal;
	private Room room;
	private int deepest;
	private int roomTick;
	private int lastActionTick;
	private int firstActionTick;
	private boolean actedHere;
	private int lastUrnTick;
	private int thievingXp;
	private int strengthXp;
	private int urns;
	private int chests;
	private int sarcophagi;
	private long artefacts;
	private int artefactCount;
	private boolean sceptre;
	private final long[] opened = new long[Room.values().length];
	private final int[] entered = new int[Room.values().length];
	private final int[] passes = new int[Room.values().length];

	public boolean isActive()
	{
		return active;
	}

	public void begin(long now, int tick, Goal goal)
	{
		active = true;
		startedAt = now;
		startTick = tick;
		this.goal = goal;
		room = null;
		deepest = 0;
		roomTick = tick;
		lastActionTick = tick;
		actedHere = false;
		lastUrnTick = -1;
		thievingXp = 0;
		strengthXp = 0;
		urns = 0;
		chests = 0;
		sarcophagi = 0;
		artefacts = 0;
		artefactCount = 0;
		sceptre = false;
		java.util.Arrays.fill(opened, 0);
		java.util.Arrays.fill(entered, -1);
		java.util.Arrays.fill(passes, -1);
	}

	/** The player is in this room now. Moving one room deeper times the room just left. */
	public void room(Room now, int tick, Pace pace)
	{
		if (!active || now == null || now == room)
		{
			return;
		}
		if (room != null && now.ordinal() == room.ordinal() + 1 && pace != null)
		{
			// The time from the last search to the next room is the door and the walk; the trap
			// came before the searches, so it is added back from the pace when there were any.
			int took = tick - (actedHere ? lastActionTick : roomTick);
			pace.passTook(actedHere ? took + (int) Math.round(pace.trap()) : took);
		}
		if (room != null && now.ordinal() == room.ordinal() + 1)
		{
			// The room's crossing without its searches: up to the first search, and from the last one out.
			passes[room.ordinal()] = actedHere ? (firstActionTick - roomTick) + (tick - lastActionTick) : tick - roomTick;
		}
		if (entered[now.ordinal()] < 0)
		{
			// Seen late (the plugin started mid-run) only ever makes a split slower, never a false best.
			entered[now.ordinal()] = Math.max(0, tick - startTick);
		}
		room = now;
		deepest = Math.max(deepest, now.getNumber());
		roomTick = tick;
		lastActionTick = tick;
		actedHere = false;
		lastUrnTick = -1;
	}

	public void thieving(int xp)
	{
		if (active && xp > 0)
		{
			thievingXp += xp;
		}
	}

	public void strength(int xp)
	{
		if (active && xp > 0)
		{
			strengthXp += xp;
		}
	}

	public void urnSearched(int tick, Pace pace)
	{
		if (!active)
		{
			return;
		}
		urns++;
		if (lastUrnTick >= 0 && pace != null)
		{
			pace.urnTook(room, tick - lastUrnTick);
		}
		lastUrnTick = tick;
		acted(tick);
	}

	public void chestOpened(int tick)
	{
		if (!active || room == null)
		{
			return;
		}
		chests++;
		opened[room.ordinal()]++;
		acted(tick);
	}

	public void sarcophagusOpened(int tick)
	{
		if (!active || room == null)
		{
			return;
		}
		sarcophagi++;
		opened[room.ordinal()]++;
		acted(tick);
	}

	private void acted(int tick)
	{
		if (!actedHere)
		{
			firstActionTick = tick;
		}
		lastActionTick = tick;
		actedHere = true;
	}

	public void artefacts(int count, long value)
	{
		if (active && count > 0)
		{
			artefactCount += count;
			artefacts += Math.max(0, value);
		}
	}

	public void sceptre()
	{
		if (active)
		{
			sceptre = true;
		}
	}

	/** Chests and sarcophagi opened this run, per room. */
	public long[] getOpened()
	{
		return opened.clone();
	}

	public Room getRoom()
	{
		return room;
	}

	/** The goal the run began with, which it is recorded and compared under even if the goal changes mid-run. */
	public Goal getGoal()
	{
		return goal;
	}

	/** Ticks from the start of the run to entering the room, or -1 when it has not been entered. */
	public int enteredAt(Room r)
	{
		return active && r != null ? entered[r.ordinal()] : -1;
	}

	public int getThievingXp()
	{
		return thievingXp;
	}

	public int getStrengthXp()
	{
		return strengthXp;
	}

	public long getArtefacts()
	{
		return artefacts;
	}

	public int getUrns()
	{
		return urns;
	}

	public int getChests()
	{
		return chests;
	}

	public int getSarcophagi()
	{
		return sarcophagi;
	}

	/** Ticks since the run began. */
	public int elapsed(int tick)
	{
		return active ? tick - startTick : 0;
	}

	/**
	 * Ends the run.
	 *
	 * @return the run, or null when nothing at all was done in it
	 */
	public Run finish(int tick)
	{
		if (!active)
		{
			return null;
		}
		active = false;
		if (thievingXp == 0 && strengthXp == 0 && urns == 0 && chests == 0 && sarcophagi == 0 && !sceptre)
		{
			return null;
		}
		return new Run(startedAt, Math.max(0, tick - startTick), deepest, thievingXp, strengthXp, urns, chests,
			sarcophagi, artefacts, artefactCount, Odds.atLeastOne(opened), sceptre, goal, entered, passes);
	}
}

package com.codex.plunder.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Map;

/**
 * Reads a saved value that may be damaged, keeping as much of it as can be read. A field of the
 * wrong type, or a number too big for its field, costs only that field; a damaged entry of a list
 * or map costs only that entry. A value that is not an object at all, or cannot be parsed, reads
 * as null.
 */
public final class Salvage
{
	private Salvage()
	{
	}

	/** @return what could be read, or null when nothing could */
	public static <T> T read(Gson gson, String json, Class<T> type)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Cut short, not JSON, or nested past what can be read: nothing is kept.
			return null;
		}
		if (root == null || !root.isJsonObject())
		{
			return null;
		}
		T whole = parse(gson, root, type);
		if (whole != null)
		{
			return whole;
		}
		JsonObject kept = new JsonObject();
		for (Map.Entry<String, JsonElement> field : root.getAsJsonObject().entrySet())
		{
			JsonElement value = field.getValue();
			if (fits(gson, field.getKey(), value, type))
			{
				kept.add(field.getKey(), value);
				continue;
			}
			JsonElement trimmed = trim(gson, field.getKey(), value, type);
			// A list where a map belongs trims to an empty list that still does not fit; then the
			// field is lost alone, not with everything else.
			if (trimmed != null && fits(gson, field.getKey(), trimmed, type))
			{
				kept.add(field.getKey(), trimmed);
			}
		}
		return parse(gson, kept, type);
	}

	/** A list or map field with only the entries that can be read, or null for any other field. */
	private static <T> JsonElement trim(Gson gson, String name, JsonElement value, Class<T> type)
	{
		if (value.isJsonArray())
		{
			JsonArray out = new JsonArray();
			for (JsonElement e : value.getAsJsonArray())
			{
				JsonArray one = new JsonArray();
				one.add(e);
				if (fits(gson, name, one, type))
				{
					out.add(e);
				}
			}
			return out;
		}
		if (value.isJsonObject())
		{
			JsonObject out = new JsonObject();
			for (Map.Entry<String, JsonElement> e : value.getAsJsonObject().entrySet())
			{
				JsonObject one = new JsonObject();
				one.add(e.getKey(), e.getValue());
				if (fits(gson, name, one, type))
				{
					out.add(e.getKey(), e.getValue());
				}
			}
			return out;
		}
		return null;
	}

	/**
	 * True when saving {@code kept}, read from {@code json}, in place of {@code json} would lose
	 * something {@code json} holds: a field or value this version does not know (one a newer
	 * version wrote), or one it had to mend or leave out. A field {@code json} lacks, as an older
	 * save does, loses nothing. A value that cannot be parsed at all loses everything.
	 */
	public static boolean wouldLose(Gson gson, String json, Object kept)
	{
		if (json == null || json.trim().isEmpty())
		{
			return false;
		}
		JsonElement was;
		try
		{
			was = gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return true;
		}
		if (was == null || was.isJsonNull())
		{
			return false;
		}
		try
		{
			return kept == null || !covers(was, gson.toJsonTree(kept));
		}
		catch (StackOverflowError e)
		{
			return true;
		}
	}

	/** True when {@code now} holds everything {@code was} does: every field, list entry and value. */
	private static boolean covers(JsonElement was, JsonElement now)
	{
		if (was.isJsonNull())
		{
			// Gson leaves an empty field out.
			return true;
		}
		if (was.isJsonObject())
		{
			if (!now.isJsonObject())
			{
				return false;
			}
			JsonObject have = now.getAsJsonObject();
			for (Map.Entry<String, JsonElement> e : was.getAsJsonObject().entrySet())
			{
				JsonElement value = have.get(e.getKey());
				if (!e.getValue().isJsonNull() && (value == null || !covers(e.getValue(), value)))
				{
					return false;
				}
			}
			return true;
		}
		if (was.isJsonArray())
		{
			JsonArray a = was.getAsJsonArray();
			if (!now.isJsonArray() || now.getAsJsonArray().size() != a.size())
			{
				return false;
			}
			JsonArray b = now.getAsJsonArray();
			for (int i = 0; i < a.size(); i++)
			{
				if (!covers(a.get(i), b.get(i)))
				{
					return false;
				}
			}
			return true;
		}
		return was.equals(now);
	}

	private static <T> boolean fits(Gson gson, String name, JsonElement value, Class<T> type)
	{
		JsonObject one = new JsonObject();
		one.add(name, value);
		return parse(gson, one, type) != null;
	}

	private static <T> T parse(Gson gson, JsonElement json, Class<T> type)
	{
		try
		{
			return gson.fromJson(json, type);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return null;
		}
	}
}

package com.codex.plunder.core;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The Pharaoh's sceptre's charges and where the sceptre is, kept in the logbook. Its Jalsavrah
 * teleport lands at the pyramid, so a charged sceptre saves the walk back after banking.
 *
 * <p>Where the count comes from is the one guess in here: the game keeps a player variable
 * named for the sceptre, which looks like the charge count but has not been checked in game.
 * It is only believed once a game message naming the charges has agreed with it; until then
 * the count is the one the last such message gave, and a message that disagrees stops it
 * being believed for good. So a wrong guess can never put a made-up number on screen.
 */
public final class Sceptre
{
	/** "Your sceptre has 23 charges left", "...has 1 charge left". Lenient on purpose: the exact wording is unverified. */
	private static final Pattern CHARGES = Pattern.compile("(\\d{1,4}) charges?\\b", Pattern.CASE_INSENSITIVE);

	/** Other sceptres that hold charges and say so in the same words. */
	private static final Pattern OTHERS = Pattern.compile("skull|thammaron|accursed|warped|lithic|revenant");

	private Integer heard;
	private boolean confirmed;
	private boolean refuted;
	private Boolean banked;
	/** Whether the banked sceptre held charges; null in saves from before this was kept. */
	private Boolean bankedCharged;

	/** The charges a game message names, or null when it does not speak of the sceptre's charges. */
	public static Integer parse(String message)
	{
		if (message == null)
		{
			return null;
		}
		String text = message.replaceAll("<[^>]*>", "");
		String lower = text.toLowerCase(Locale.ENGLISH);
		if (!lower.contains("sceptre") || OTHERS.matcher(lower).find())
		{
			return null;
		}
		if (lower.contains("no charges") || lower.contains("out of charges") || lower.contains("has run out"))
		{
			return 0;
		}
		Matcher m = CHARGES.matcher(text);
		return m.find() ? Integer.parseInt(m.group(1)) : null;
	}

	/** A game message named this many charges. */
	public void heard(int charges)
	{
		heard = Math.max(0, charges);
	}

	/**
	 * Holds the player variable up against the last message, a tick after it so the variable has
	 * caught up. A match makes the variable believed; a mismatch stops it being believed for good.
	 */
	public void compare(int variable)
	{
		if (heard == null || refuted)
		{
			return;
		}
		if (variable == heard)
		{
			confirmed = true;
		}
		else
		{
			confirmed = false;
			refuted = true;
		}
	}

	/**
	 * @param variable the player variable as it stands now
	 * @return the charges, or -1 when not known
	 */
	public int charges(int variable)
	{
		if (confirmed && !refuted && variable >= 0)
		{
			return variable;
		}
		return heard == null ? -1 : heard;
	}

	/** Whether the live count is in use, rather than the last message's. */
	public boolean isLive()
	{
		return confirmed && !refuted;
	}

	/**
	 * The sceptre in the bank when it was last seen: none, an emptied one or a charged one; null
	 * when the bank has not been seen. A banked sceptre from a save that did not say whether it was
	 * charged counts as charged, as that is what is worth bringing.
	 */
	public Check.SceptreKit getBanked()
	{
		if (banked == null)
		{
			return null;
		}
		if (!banked)
		{
			return Check.SceptreKit.NONE;
		}
		return bankedCharged == null || bankedCharged ? Check.SceptreKit.CHARGED : Check.SceptreKit.UNCHARGED;
	}

	/** @return whether this changes what was known */
	public boolean setBanked(Check.SceptreKit kit)
	{
		Check.SceptreKit before = getBanked();
		banked = kit != Check.SceptreKit.NONE;
		bankedCharged = kit == Check.SceptreKit.CHARGED;
		return before != kit;
	}
}

package com.codex.plunder.core;

/**
 * Tells a Pharaoh's sceptre found from one that only turned up in the counts. The sceptres carried
 * and worn are counted once a tick; a sceptre found is one more of them than the tick before. One
 * moved between hand and pack, or emptied by its last teleport, is the same sceptre under another
 * id and does not count, and nor does the pack arriving after a login or a hop: until it has, the
 * count is unknown, not zero.
 *
 * <p>Finding the sceptre throws the player out of the pyramid, so it can land in the pack a moment
 * after the run ends. Within {@link #GRACE_TICKS} of a run's end a new sceptre is credited to it;
 * a run ended by logging out or hopping was not thrown out by one.</p>
 */
public final class SceptreWatch
{
	/** What a tick's count showed. */
	public enum Seen
	{
		NOTHING,
		/** One more sceptre during a run. */
		FOUND,
		/** One more sceptre just after a run ended. */
		FOUND_AFTER,
		/** One more sceptre away from any run: bought, or taken from the bank. */
		OTHER
	}

	/** About six seconds after a run ends. */
	public static final int GRACE_TICKS = 10;

	private int last = -1;
	private int endedAt = Integer.MIN_VALUE;

	/** The pack is about to be sent afresh (login, hop): forget what it held and any run just ended. */
	public void reset()
	{
		last = -1;
		endedAt = Integer.MIN_VALUE;
	}

	/** A run ended on this tick, by the clock or the sceptre. */
	public void runEnded(int tick)
	{
		endedAt = tick;
	}

	/**
	 * @param count sceptres carried and worn, or -1 while the pack has not arrived
	 * @param inRun a run is under way
	 * @param tick the game tick
	 */
	public Seen tick(int count, boolean inRun, int tick)
	{
		int before = last;
		last = count;
		if (before < 0 || count <= before)
		{
			return Seen.NOTHING;
		}
		if (inRun)
		{
			return Seen.FOUND;
		}
		return endedAt != Integer.MIN_VALUE && tick - endedAt >= 0 && tick - endedAt <= GRACE_TICKS ? Seen.FOUND_AFTER : Seen.OTHER;
	}
}

package com.codex.plunder.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One sitting at the pyramid: the runs played back to back, with no break longer than twenty
 * minutes between one ending and the next starting. It counts what the sitting earned, the rate
 * it ran at with the walk back between runs included, and the sceptre chance its openings carried.
 */
public final class Session
{
	/** A gap longer than this between runs ends a session. */
	static final long BREAK_MS = 20 * 60_000L;
	private static final long TICK_MS = 600;

	private final List<Run> runs;
	private final boolean current;
	private final long xp;
	private final long strength;
	private final long artefacts;
	private final double sceptreChance;
	private final int sceptres;
	private final long startedAt;
	private final long endedAt;

	private Session(List<Run> runs, boolean current)
	{
		this.runs = Collections.unmodifiableList(runs);
		this.current = current;
		long x = 0;
		long s = 0;
		long a = 0;
		double miss = 1;
		int found = 0;
		for (Run r : runs)
		{
			x += r.getThievingXp();
			s += r.getStrengthXp();
			a += r.getArtefacts();
			miss *= 1 - Math.max(0, Math.min(1, r.getSceptreChance()));
			found += r.isSceptre() ? 1 : 0;
		}
		xp = x;
		strength = s;
		artefacts = a;
		sceptreChance = 1 - miss;
		sceptres = found;
		startedAt = runs.isEmpty() ? 0 : runs.get(0).getAt();
		endedAt = runs.isEmpty() ? 0 : end(runs.get(runs.size() - 1));
	}

	/**
	 * The newest session in the runs.
	 *
	 * @param runs every run kept, oldest first
	 * @param now the time now, to tell a session still going from one that has ended
	 */
	public static Session latest(List<Run> runs, long now)
	{
		List<Run> picked = new ArrayList<>();
		if (runs != null)
		{
			for (int i = runs.size() - 1; i >= 0; i--)
			{
				Run r = runs.get(i);
				if (!picked.isEmpty())
				{
					long gap = picked.get(0).getAt() - end(r);
					if (gap > BREAK_MS)
					{
						break;
					}
				}
				picked.add(0, r);
			}
		}
		boolean current = !picked.isEmpty() && now - end(picked.get(picked.size() - 1)) <= BREAK_MS;
		return new Session(picked, current);
	}

	/** Sessions shorter than this many runs are never called the best: one lucky run is not a pace. */
	public static final int BEST_MIN_RUNS = 3;

	/**
	 * Every session in the runs kept, newest first. The oldest may have begun before the first run
	 * still kept, so it can be shorter than it was.
	 *
	 * @param runs every run kept, oldest first
	 * @param now the time now, to tell whether the newest session is still going
	 */
	public static List<Session> history(List<Run> runs, long now)
	{
		List<Session> out = new ArrayList<>();
		if (runs == null || runs.isEmpty())
		{
			return out;
		}
		List<Run> group = new ArrayList<>();
		for (Run r : runs)
		{
			if (!group.isEmpty() && r.getAt() - end(group.get(group.size() - 1)) > BREAK_MS)
			{
				out.add(0, new Session(group, false));
				group = new ArrayList<>();
			}
			group.add(r);
		}
		out.add(0, new Session(group, now - end(group.get(group.size() - 1)) <= BREAK_MS));
		return out;
	}

	/** The session with the best experience an hour of at least {@link #BEST_MIN_RUNS} runs, or null. */
	public static Session best(List<Session> sessions)
	{
		Session best = null;
		for (Session s : sessions)
		{
			if (s.runs.size() >= BEST_MIN_RUNS && (best == null || s.xpPerHour() > best.xpPerHour()))
			{
				best = s;
			}
		}
		return best;
	}

	private static long end(Run r)
	{
		return r.getAt() + r.getTicks() * TICK_MS;
	}

	public boolean isEmpty()
	{
		return runs.isEmpty();
	}

	/** Whether the last run ended recently enough that the session is still going. */
	public boolean isCurrent()
	{
		return current;
	}

	public List<Run> getRuns()
	{
		return runs;
	}

	public long getXp()
	{
		return xp;
	}

	public long getStrengthXp()
	{
		return strength;
	}

	public long getArtefacts()
	{
		return artefacts;
	}

	public long getStartedAt()
	{
		return startedAt;
	}

	public long getEndedAt()
	{
		return endedAt;
	}

	/** The chance the session's chests and sarcophagi together had of a sceptre. */
	public double getSceptreChance()
	{
		return sceptreChance;
	}

	public int getSceptres()
	{
		return sceptres;
	}

	/**
	 * How long the session has taken: from the first run starting to the last ending, plus one
	 * walk back for the last run, so a single run is not counted as all play and no walking.
	 */
	public long spanMs()
	{
		return runs.isEmpty() ? 0 : Math.max(0, endedAt - startedAt) + Planner.RESTART_TICKS * TICK_MS;
	}

	public int xpPerHour()
	{
		return perHour(xp);
	}

	public int artefactsPerHour()
	{
		return perHour(artefacts);
	}

	private int perHour(long amount)
	{
		long span = spanMs();
		return span <= 0 ? 0 : (int) Math.min(Integer.MAX_VALUE, Math.round(amount * 3_600_000.0 / span));
	}

	/** The run that paid the most Thieving experience, or null. */
	public Run best()
	{
		Run best = null;
		for (Run r : runs)
		{
			if (best == null || r.getThievingXp() > best.getThievingXp())
			{
				best = r;
			}
		}
		return best;
	}
}

package com.codex.plunder.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * The bank as another Codex plugin last saw it, read from what that plugin saves in the RuneLite
 * profile. Only read, never written, and absent when neither plugin is installed.
 *
 * <p>Codex Bank Steward's {@code codexbanksteward/bankV1} is preferred: it holds every item with
 * its quantity and when it was seen,
 * {@code {"version":1,"savedAt":1760000000000,"items":{"995":1234567,"26950":1},"truncated":false}}.
 * Codex Gear Roadmap's {@code codexgearroadmap/bank} is the fallback, {@code {"items":[4151],"coins":N}}:
 * only the gear Roadmap knows, with no quantities (each counts as one) and no time.</p>
 */
public final class SharedBank
{
	public static final String STEWARD_GROUP = "codexbanksteward";
	public static final String STEWARD_KEY = "bankV1";
	public static final String ROADMAP_GROUP = "codexgearroadmap";
	public static final String ROADMAP_KEY = "bank";
	private static final int COINS = 995;
	/** Readers accept no more kinds of item than the Steward ever writes. */
	private static final int MAX_ITEMS = 2000;

	/** Where a shared bank came from. */
	public enum Source
	{
		/** Every item and its quantity. */
		BANK_STEWARD,
		/** Only the gear Gear Roadmap tracks, and coins. */
		GEAR_ROADMAP
	}

	private final Source source;
	private final Map<Integer, Long> items;
	private final long savedAt;
	private final boolean complete;

	private SharedBank(Source source, Map<Integer, Long> items, long savedAt, boolean complete)
	{
		this.source = source;
		this.items = Collections.unmodifiableMap(items);
		this.savedAt = savedAt;
		this.complete = complete;
	}

	/**
	 * The best bank on offer: Bank Steward's, else Gear Roadmap's, else null.
	 *
	 * @param steward what {@code codexbanksteward/bankV1} holds for this profile, or null
	 * @param roadmap what {@code codexgearroadmap/bank} holds for this profile, or null
	 */
	public static SharedBank read(Gson gson, String steward, String roadmap)
	{
		SharedBank bank = readSteward(gson, steward);
		return bank != null ? bank : readRoadmap(gson, roadmap);
	}

	static SharedBank readSteward(Gson gson, String json)
	{
		JsonObject root = object(gson, json);
		JsonElement list = root == null ? null : root.get("items");
		if (list == null || !list.isJsonObject())
		{
			return null;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
		{
			Integer id = integer(e.getKey());
			Long qty = number(e.getValue());
			if (id != null && id > 0 && qty != null && qty > 0 && items.size() < MAX_ITEMS)
			{
				// No bank slot holds more than this; a larger count is damage, held to it.
				items.put(id, Math.min(qty, Integer.MAX_VALUE));
			}
		}
		Long savedAt = number(root.get("savedAt"));
		JsonElement truncated = root.get("truncated");
		boolean cut = truncated != null && truncated.isJsonPrimitive() && truncated.getAsJsonPrimitive().isBoolean()
			&& truncated.getAsBoolean();
		return new SharedBank(Source.BANK_STEWARD, items, savedAt == null ? 0 : Math.max(0, savedAt), !cut);
	}

	static SharedBank readRoadmap(Gson gson, String json)
	{
		JsonObject root = object(gson, json);
		JsonElement list = root == null ? null : root.get("items");
		if (list == null || !list.isJsonArray())
		{
			return null;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (JsonElement e : list.getAsJsonArray())
		{
			Long id = number(e);
			if (id != null && id > 0 && id <= Integer.MAX_VALUE && items.size() < MAX_ITEMS)
			{
				items.put(id.intValue(), 1L);
			}
		}
		Long coins = number(root.get("coins"));
		if (coins != null && coins > 0)
		{
			items.put(COINS, coins);
		}
		return new SharedBank(Source.GEAR_ROADMAP, items, 0, false);
	}

	public Source getSource()
	{
		return source;
	}

	/** Item id to quantity; a Gear Roadmap bank counts each item it lists as one. */
	public Map<Integer, Long> getItems()
	{
		return items;
	}

	public Set<Integer> ids()
	{
		return items.keySet();
	}

	public long count(int itemId)
	{
		return items.getOrDefault(itemId, 0L);
	}

	/** When the bank was seen, in epoch milliseconds; 0 when the source does not say. */
	public long getSavedAt()
	{
		return savedAt;
	}

	/**
	 * Whether every item in the bank is here with its true quantity, so a missing item really is
	 * not in the bank. Only Bank Steward's snapshot is.
	 */
	public boolean isComplete()
	{
		return complete;
	}

	private static JsonObject object(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Cut short, not JSON, or garbage nested deeper than Gson reads.
			return null;
		}
	}

	private static Long number(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		try
		{
			return e.getAsLong();
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private static Integer integer(String s)
	{
		try
		{
			return Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.codex.plunder.core;

import java.util.Arrays;
import java.util.List;

/**
 * Room splits, the way a speedrunner keeps them: the moment each room was entered, measured
 * against the run that reached the deepest room fastest, and the quickest the player has ever
 * crossed each room. Only runs for the same goal that reached the same deepest room are
 * compared, since a sceptre run or a run two rooms short spends its clock differently.
 */
public final class Splits
{
	/** Ticks from the start to entering each room in the best run; -1 where not known. */
	private final int[] best;
	/** The quickest each room has been crossed, entry to entry; -1 where not known. */
	private final int[] segments;
	private final Room top;
	private final int compared;

	private Splits(int[] best, int[] segments, Room top, int compared)
	{
		this.best = best;
		this.segments = segments;
		this.top = top;
		this.compared = compared;
	}

	/**
	 * @param runs every run kept, oldest first
	 * @param goal the goal the comparison is for
	 * @param top the deepest room the player's level opens
	 */
	public static Splits of(List<Run> runs, Goal goal, Room top)
	{
		int n = Room.values().length;
		int[] best = new int[n];
		int[] segments = new int[n];
		Arrays.fill(best, -1);
		Arrays.fill(segments, -1);
		int compared = 0;
		int bestAtTop = Integer.MAX_VALUE;
		if (runs != null && top != null)
		{
			for (Run run : runs)
			{
				if (!comparable(run, goal, top))
				{
					continue;
				}
				compared++;
				int atTop = run.splitAt(top);
				if (atTop < bestAtTop)
				{
					bestAtTop = atTop;
					for (Room r : Room.values())
					{
						best[r.ordinal()] = r.ordinal() <= top.ordinal() ? run.splitAt(r) : -1;
					}
				}
				for (int i = 0; i < top.ordinal(); i++)
				{
					int seg = segment(run, Room.values()[i]);
					if (seg >= 0 && (segments[i] < 0 || seg < segments[i]))
					{
						segments[i] = seg;
					}
				}
			}
		}
		return new Splits(best, segments, top, compared);
	}

	/** Whether a run can be measured against the others: same goal, as deep, and its arrival there seen. */
	public static boolean comparable(Run run, Goal goal, Room top)
	{
		return run != null && top != null && run.getGoal() == goal && run.getDeepest() == top.getNumber() && run.splitAt(top) >= 0;
	}

	/** Ticks the run took from entering the room to entering the next, or -1 when either was not seen. */
	public static int segment(Run run, Room room)
	{
		if (room == null || room.ordinal() + 1 >= Room.values().length)
		{
			return -1;
		}
		int from = run.splitAt(room);
		int to = run.splitAt(Room.values()[room.ordinal() + 1]);
		return from < 0 || to < from ? -1 : to - from;
	}

	public Room getTop()
	{
		return top;
	}

	/** Runs the comparison was drawn from. */
	public int getCompared()
	{
		return compared;
	}

	public boolean hasBest()
	{
		return top != null && best[top.ordinal()] >= 0;
	}

	/** Ticks from the start to entering the room in the best run, or -1. */
	public int bestAt(Room room)
	{
		return room == null ? -1 : best[room.ordinal()];
	}

	/** The quickest the room has been crossed, or -1. */
	public int bestSegment(Room room)
	{
		return room == null ? -1 : segments[room.ordinal()];
	}

	/**
	 * Ticks ahead (negative) or behind (positive) the best run on entering the room, or null when
	 * the best run's arrival there is not known.
	 */
	public Integer delta(Room room, int enteredAt)
	{
		int b = bestAt(room);
		return b < 0 || enteredAt < 0 ? null : enteredAt - b;
	}

	/**
	 * The deepest room reached by stringing together the quickest crossing of every room before it,
	 * which no single run has managed yet: what a clean run would do. -1 until every room has one.
	 */
	public int sumOfBest()
	{
		if (top == null)
		{
			return -1;
		}
		int sum = 0;
		for (int i = 0; i < top.ordinal(); i++)
		{
			if (segments[i] < 0)
			{
				return -1;
			}
			sum += segments[i];
		}
		// Room one is entered when the clock starts, so the best run's first split is the start.
		int start = best[0] < 0 ? 0 : best[0];
		return start + sum;
	}

	/** Ticks over its quickest crossing that a run must lose in a room before it is named: three seconds. */
	public static final int SLOW = 5;

	/**
	 * The room this run lost most time in against its quickest crossing before it, or null when
	 * no room ran {@link #SLOW} ticks over.
	 */
	public Room slowest(Run run)
	{
		Room worst = null;
		int most = SLOW - 1;
		if (run == null || top == null)
		{
			return null;
		}
		for (int i = 0; i < top.ordinal(); i++)
		{
			Room r = Room.values()[i];
			int over = overrun(run, r);
			if (over > most)
			{
				most = over;
				worst = r;
			}
		}
		return worst;
	}

	/** Ticks the run took in the room over its quickest crossing before it, or 0 when either is not known. */
	public int overrun(Run run, Room room)
	{
		int seg = segment(run, room);
		int quickest = bestSegment(room);
		return seg < 0 || quickest < 0 ? 0 : Math.max(0, seg - quickest);
	}

	/** Whether this run reached the deepest room faster than every run before it. */
	public boolean isNewBest(Run run, Goal goal)
	{
		return comparable(run, goal, top) && (!hasBest() || run.splitAt(top) < bestAt(top));
	}
}

package com.codex.plunder.core;

import java.util.Collection;
import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;

/**
 * The artefacts waiting in the bank to be sold: as this plugin last saw the bank, or as Codex
 * Bank Steward last saved it when that is newer. Gear Roadmap's saved bank holds only gear, so it
 * never says anything about artefacts and is never used here.
 */
public final class Stash
{
	/**
	 * Bank Steward's bank must be this much newer than this plugin's look to be taken instead: on
	 * the same bank visit both see it, the Steward a moment later, and the look was this plugin's.
	 */
	static final long SAME_VISIT_MS = 60_000L;

	private final Map<Integer, Long> items;
	private final long seenAt;
	private final SharedBank.Source from;

	private Stash(Map<Integer, Long> items, long seenAt, SharedBank.Source from)
	{
		this.items = Collections.unmodifiableMap(items);
		this.seenAt = seenAt;
		this.from = from;
	}

	/**
	 * @param own the artefacts as this plugin last saw the bank, by item id
	 * @param ownAt when that was, 0 for never
	 * @param shared the bank another Codex plugin saved, or null
	 * @param artefacts the item ids that count
	 * @return the newer of the two (the Steward's only when over a minute newer), or null when neither has seen the bank
	 */
	public static Stash pick(Map<Integer, Long> own, long ownAt, SharedBank shared, Collection<Integer> artefacts)
	{
		if (shared != null && shared.isComplete() && shared.getSavedAt() > 0
			&& (ownAt <= 0 || shared.getSavedAt() > ownAt + SAME_VISIT_MS))
		{
			Map<Integer, Long> items = new TreeMap<>();
			for (int id : artefacts)
			{
				long n = shared.count(id);
				if (n > 0)
				{
					items.put(id, n);
				}
			}
			return new Stash(items, shared.getSavedAt(), shared.getSource());
		}
		if (ownAt <= 0)
		{
			return null;
		}
		Map<Integer, Long> items = new TreeMap<>();
		if (own != null)
		{
			for (Map.Entry<Integer, Long> e : own.entrySet())
			{
				if (e.getKey() != null && e.getValue() != null && e.getValue() > 0 && artefacts.contains(e.getKey()))
				{
					items.put(e.getKey(), e.getValue());
				}
			}
		}
		return new Stash(items, ownAt, null);
	}

	/** Artefacts by item id, lowest id first. */
	public Map<Integer, Long> getItems()
	{
		return items;
	}

	public long count()
	{
		long n = 0;
		for (long q : items.values())
		{
			n += q;
		}
		return n;
	}

	/** When the bank was seen. */
	public long getSeenAt()
	{
		return seenAt;
	}

	/** The plugin whose saved bank this is, or null when this plugin saw the bank itself. */
	public SharedBank.Source getFrom()
	{
		return from;
	}
}

package com.codex.plunder.core;

/** The one thing to do next, worked out from the plan and the room as it stands. */
public final class Step
{
	/** What kind of thing it is; the overlay highlights by kind. */
	public enum Kind
	{
		ENTER,
		TRAP,
		URNS,
		CHEST,
		SARCOPHAGUS,
		DOOR,
		LEAVE,
		FINISH,
		/** Something needs dealing with before the plan goes on. */
		DANGER
	}

	/** What could go wrong mid-run, read each tick. */
	public static final class Alarm
	{
		final boolean packFull;
		final boolean lowHp;
		final boolean chased;
		final boolean canProtect;

		/**
		 * @param chased a scarab swarm or mummy is after the player
		 * @param canProtect the player has the Prayer for Protect from Melee
		 */
		public Alarm(boolean packFull, boolean lowHp, boolean chased, boolean canProtect)
		{
			this.packFull = packFull;
			this.lowHp = lowHp;
			this.chased = chased;
			this.canProtect = canProtect;
		}

		public static final Alarm NONE = new Alarm(false, false, false, false);
	}

	private final Kind kind;
	private final String title;
	private final String detail;

	private Step(Kind kind, String title, String detail)
	{
		this.kind = kind;
		this.title = title;
		this.detail = detail;
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getTitle()
	{
		return title;
	}

	public String getDetail()
	{
		return detail;
	}

	/**
	 * @param plan the plan for the rest of the run
	 * @param inRun whether a run is under way; before one, the step is to go in
	 * @param trapActive the room's spear trap is still to be passed
	 * @param doorsTried how many of the room's four tomb doors have been tried
	 */
	public static Step next(Plan plan, boolean inRun, boolean trapActive, int doorsTried)
	{
		return next(plan, inRun, trapActive, doorsTried, Alarm.NONE);
	}

	public static Step next(Plan plan, boolean inRun, boolean trapActive, int doorsTried, Alarm alarm)
	{
		Plan.Stop stop = plan.current();
		if (!inRun || stop == null)
		{
			return new Step(Kind.ENTER, "Enter the pyramid", enterDetail(plan));
		}
		Room room = stop.getRoom();
		if (alarm.chased)
		{
			return new Step(Kind.DANGER, alarm.canProtect ? "Protect from Melee" : "Keep moving",
				alarm.canProtect ? "A swarm or mummy is on you; the prayer stops all of its damage" : "It only chases you; finish the room and take the door");
		}
		if (alarm.lowHp)
		{
			return new Step(Kind.DANGER, "Eat first", "Under " + (Check.LOW_HP + 1) + " hitpoints a snake bite and its poison can hurt");
		}
		boolean looting = stop.getUrns() > 0 || stop.isChest() || stop.isSarcophagus();
		if (alarm.packFull && looting && !trapActive)
		{
			return new Step(Kind.DANGER, "Your pack is full", "Drop the cheapest artefacts, the stone and pottery ones, to keep looting");
		}
		if (trapActive)
		{
			return new Step(Kind.TRAP, "Pass the spear trap", stop.isPassThrough() && !room.equals(plan.getTop())
				? "Nothing in room " + room.getNumber() + " is worth the time: straight through to the door"
				: "Then " + work(stop));
		}
		if (stop.getUrns() > 0)
		{
			return new Step(Kind.URNS, "Search " + stop.getUrns() + (stop.getUrns() == 1 ? " urn" : " urns"),
				urnDetail(stop, plan));
		}
		// Chests and sarcophagi last, so a scarab swarm or a mummy has the least time to chase.
		if (stop.isChest())
		{
			return new Step(Kind.CHEST, "Open the grand gold chest",
				"1 in " + room.getSceptreOneIn() + " for the sceptre here" + (stop.isSarcophagus() ? ", then the sarcophagus" : ""));
		}
		if (stop.isSarcophagus())
		{
			return new Step(Kind.SARCOPHAGUS, "Open the sarcophagus",
				"1 in " + room.getSceptreOneIn() + " for the sceptre, and Strength experience");
		}
		if (room != plan.getTop())
		{
			String tried = doorsTried <= 0 ? "One of the four tomb doors is real" : doorsTried + " of 4 tried, " + (4 - doorsTried) + " left";
			return new Step(Kind.DOOR, "Find the tomb door", tried + ". Room " + (room.getNumber() + 1) + " is next");
		}
		if (plan.spare() < Planner.RESTART_TICKS)
		{
			return new Step(Kind.FINISH, "Time is nearly up", "Too little left for another search; the run ends on its own");
		}
		return new Step(Kind.LEAVE, "Leave and begin a new run", "Everything worth doing here is done; a fresh run pays more than the time left");
	}

	private static String work(Plan.Stop stop)
	{
		StringBuilder text = new StringBuilder();
		if (stop.getUrns() > 0)
		{
			text.append(stop.getUrns()).append(stop.getUrns() == 1 ? " urn" : " urns");
		}
		if (stop.isChest())
		{
			text.append(text.length() > 0 ? ", " : "").append("the chest");
		}
		if (stop.isSarcophagus())
		{
			text.append(text.length() > 0 ? ", " : "").append("the sarcophagus");
		}
		return text.length() == 0 ? "the tomb door" : text.toString();
	}

	private static String urnDetail(Plan.Stop stop, Plan plan)
	{
		int skip = stop.getUrnsLeft() - stop.getUrns();
		String pay = stop.getRoom().getUrnXp() + " xp each";
		if (skip > 0)
		{
			return pay + "; leave the other " + skip + ", " + (stop.getRoom() == plan.getTop() ? "the clock is short" : "deeper rooms pay more");
		}
		return pay + (stop.isChest() ? ", then the chest" : "");
	}

	private static String enterDetail(Plan plan)
	{
		Room top = plan.getTop();
		int looted = 0;
		Room firstLooted = null;
		for (Plan.Stop s : plan.getStops())
		{
			if (s.getUrns() > 0)
			{
				looted++;
				if (firstLooted == null)
				{
					firstLooted = s.getRoom();
				}
			}
		}
		if (firstLooted == null)
		{
			return "Run through to room " + top.getNumber();
		}
		if (firstLooted == top)
		{
			return "Run through to room " + top.getNumber() + " and search its urns";
		}
		if (looted == 1 || firstLooted.getNumber() == 1)
		{
			return "Search urns in rooms " + firstLooted.getNumber() + " to " + top.getNumber();
		}
		String walk = firstLooted.getNumber() == 2 ? "Walk through room 1" : "Walk through rooms 1 to " + (firstLooted.getNumber() - 1);
		return walk + ", search urns from room " + firstLooted.getNumber();
	}
}

package com.codex.plunder.core;

/**
 * A deeper room opening: every eight to ten Thieving levels the pyramid lets the player one room
 * further in, and a run there pays far more. Worth a line in the chat box when it happens, and a
 * heads-up in the run summary when it is only a few runs away.
 */
public final class Unlock
{
	/** The run summary mentions the next room once it is this few runs away. */
	public static final int SOON_RUNS = 3;

	/** A room that has just opened, with what a run paid before and pays now. */
	public static final class Opened
	{
		private final Room room;
		private final int runXpBefore;
		private final int runXpNow;
		private final int rateBefore;
		private final int rateNow;

		Opened(Room room, int runXpBefore, int runXpNow, int rateBefore, int rateNow)
		{
			this.room = room;
			this.runXpBefore = runXpBefore;
			this.runXpNow = runXpNow;
			this.rateBefore = rateBefore;
			this.rateNow = rateNow;
		}

		/** The deepest room now open. */
		public Room getRoom()
		{
			return room;
		}

		public int getRunXpBefore()
		{
			return runXpBefore;
		}

		public int getRunXpNow()
		{
			return runXpNow;
		}

		/** Experience an hour at the old level, the walk back counted. */
		public int getRateBefore()
		{
			return rateBefore;
		}

		public int getRateNow()
		{
			return rateNow;
		}
	}

	private Unlock()
	{
	}

	/**
	 * The room a level rise opened, or null when it opened none. A rise of several levels at once
	 * (a save from long ago) names only the deepest room now open.
	 *
	 * @param before the Thieving level as last seen; 0 when never seen, which opens nothing
	 */
	public static Opened opened(int before, int now, Goal goal, Pace pace)
	{
		if (before <= 0 || now <= before)
		{
			return null;
		}
		Room was = Room.highest(before);
		Room is = Room.highest(now);
		if (is == null || is == was)
		{
			return null;
		}
		int beforeXp = 0;
		int beforeRate = 0;
		if (was != null)
		{
			Plan old = Planner.fresh(before, goal, pace);
			beforeXp = old.getThievingXp();
			beforeRate = old.xpPerHour(Planner.RESTART_TICKS);
		}
		Plan fresh = Planner.fresh(now, goal, pace);
		return new Opened(is, beforeXp, fresh.getThievingXp(), beforeRate, fresh.xpPerHour(Planner.RESTART_TICKS));
	}

	/**
	 * Runs like this one still to go before the next room opens, or 0 when every room is open or
	 * the run paid nothing to go on.
	 */
	public static long runsToNext(int level, long xp, int perRun)
	{
		int next = Room.nextUnlock(level);
		if (next <= 0 || perRun <= 0)
		{
			return 0;
		}
		long left = Math.max(0, Levels.xpFor(next) - xp);
		return Math.max(1, (left + perRun - 1) / perRun);
	}
}

package com.codex.plunder.overlay;

import com.codex.plunder.ui.Sigil;
import com.codex.plunder.ui.Theme;
import com.codex.plunder.ui.Ui;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A slim gilt plaque in the game view during a run: the room, the clock, and the one thing to
 * do next, with a hairline under it that drains with the clock. It draws what the plugin hands it.
 */
public class PilotPlaque extends Overlay
{
	private static final int PAD = 7;

	private volatile Shown shown;

	private static final class Shown
	{
		final String figure;
		final String step;
		final String detail;
		final Color color;
		final double progress;
		final String split;
		final Color splitColor;
		/** The layout, worked out on the first frame this is shown and kept for the rest. */
		String[] lines;
		String stepShown;
		int width;
		int height;
		int chip;
		RoundRectangle2D shape;
		GradientPaint fill;
		Color rim;
		Color chipFill;
		Color chipRim;

		Shown(String figure, String step, String detail, Color color, double progress, String split, Color splitColor)
		{
			this.split = split;
			this.splitColor = splitColor;
			this.figure = figure;
			this.step = step;
			this.detail = detail;
			this.color = color;
			this.progress = progress;
		}
	}

	public PilotPlaque()
	{
		setPosition(OverlayPosition.TOP_LEFT);
	}

	/**
	 * @param figure the big text, such as "R6  3:12", or null to hide the plaque
	 * @param progress the share of the clock left, 0 to 1
	 */
	public void show(String figure, String step, String detail, Color color, double progress)
	{
		show(figure, step, detail, color, progress, null, null);
	}

	/**
	 * @param split the room's split against the best run, such as "-4s", drawn after the figure; or null
	 * @param splitColor green ahead, ember behind
	 */
	public void show(String figure, String step, String detail, Color color, double progress, String split, Color splitColor)
	{
		shown = figure == null ? null : new Shown(figure, step, detail, color, progress, split, splitColor);
	}

	/** The widest a detail line runs before it breaks onto a second. */
	private static final int DETAIL_WIDTH = 260;

	/** The detail in one line, or two broken at a space; the second is cut short if it is still too long. */
	static String[] lines(String text, FontMetrics fm, int width)
	{
		if (fm.stringWidth(text) <= width)
		{
			return new String[]{text};
		}
		int cut = -1;
		for (int i = text.indexOf(' '); i > 0; i = text.indexOf(' ', i + 1))
		{
			if (fm.stringWidth(text.substring(0, i)) > width)
			{
				break;
			}
			cut = i;
		}
		if (cut < 0)
		{
			return new String[]{text};
		}
		return new String[]{text.substring(0, cut), text.substring(cut + 1)};
	}

	/** The widest the step runs: a long one is cut short rather than stretch the plaque across the game. */
	private static final int STEP_WIDTH = 300;
	private static final Color TRACK = Theme.alpha(Theme.INK_DEEP, 220);
	/** The mark, drawn once. */
	private BufferedImage mark;

	/** Works out what is shown once, so a frame draws without measuring or allocating. */
	private static void layout(Shown s, FontMetrics bold, FontMetrics small, int textX)
	{
		// A split sits after the figure as a small framed chip, the way a speedrun timer flashes one.
		s.chip = s.split == null ? 0 : small.stringWidth(s.split) + 8;
		s.stepShown = Ui.clip(s.step == null ? "" : s.step, bold, STEP_WIDTH);
		int line1 = bold.stringWidth(s.figure) + 10 + (s.chip > 0 ? s.chip + 8 : 0) + bold.stringWidth(s.stepShown);
		// A long detail takes a second line rather than being cut off mid-word.
		String[] lines = s.detail == null ? new String[0] : lines(s.detail, small, DETAIL_WIDTH);
		int line2 = 0;
		for (int i = 0; i < lines.length; i++)
		{
			lines[i] = Ui.clip(lines[i], small, Math.max(DETAIL_WIDTH, line1));
			line2 = Math.max(line2, small.stringWidth(lines[i]));
		}
		s.width = textX + Math.max(line1, line2) + PAD;
		s.height = PAD + bold.getHeight() + lines.length * (small.getHeight() + 1) + PAD;
		s.shape = new RoundRectangle2D.Float(0.5f, 0.5f, s.width - 1, s.height - 1, 10, 10);
		s.fill = new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 232), 0, s.height, Theme.alpha(Theme.INK_DEEP, 232));
		s.rim = Theme.alpha(s.color, 170);
		if (s.splitColor != null)
		{
			s.chipFill = Theme.alpha(s.splitColor, 46);
			s.chipRim = Theme.alpha(s.splitColor, 150);
		}
		s.lines = lines;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Shown s = shown;
		if (s == null)
		{
			return null;
		}
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int icon = 16;
		int textX = PAD + icon + 6;
		if (s.lines == null)
		{
			layout(s, bold, small, textX);
		}
		String[] lines = s.lines;
		int width = s.width;
		int height = s.height;
		int chip = s.chip;
		g.setPaint(s.fill);
		g.fill(s.shape);
		g.setColor(s.rim);
		g.draw(s.shape);

		if (mark == null)
		{
			mark = Sigil.icon(icon);
		}
		g.drawImage(mark, PAD, (height - icon) / 2 - 1, null);
		int base = PAD + bold.getAscent();
		g.setFont(Theme.title());
		Ui.shadowed(g, s.figure, textX, base, s.color);
		int stepX = textX + bold.stringWidth(s.figure) + 10;
		if (chip > 0)
		{
			int ch = small.getHeight() + 1;
			int cy = base - bold.getAscent() / 2 - ch / 2 - 1;
			g.setColor(s.chipFill);
			g.fillRoundRect(stepX, cy, chip, ch, 6, 6);
			g.setColor(s.chipRim);
			g.drawRoundRect(stepX, cy, chip, ch, 6, 6);
			g.setFont(Theme.small());
			Ui.shadowed(g, s.split, stepX + 4, cy + (ch + small.getAscent()) / 2 - 1, s.splitColor);
			g.setFont(Theme.title());
			stepX += chip + 8;
		}
		Ui.shadowed(g, s.stepShown, stepX, base, Theme.TEXT);
		g.setFont(Theme.small());
		for (int i = 0; i < lines.length; i++)
		{
			Ui.shadowed(g, lines[i], textX, base + (i + 1) * (small.getHeight() + 1) + 1, Theme.TEXT_MUTED);
		}
		int bar = (int) Math.round((width - 20) * Math.max(0, Math.min(1, s.progress)));
		g.setColor(TRACK);
		g.fillRect(10, height - 3, width - 20, 2);
		g.setColor(s.color);
		g.fillRect(10, height - 3, bar, 2);
		return new Dimension(width, height);
	}
}

package com.codex.plunder.overlay;

import com.codex.plunder.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Rectangle;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.util.Collections;
import java.util.List;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines in the room what the plan says to do next and nothing else: the urns worth searching
 * in gold, the chest and sarcophagus in teal when the sceptre odds make them worth it, the spear
 * trap and the untried tomb doors when it is time to move on. Urns the plan skips stay dark.
 */
public class RoomHighlights extends Overlay
{
	/** One object to outline, and in what colour. */
	public static final class Mark
	{
		final TileObject object;
		final Color color;
		final boolean clickbox;
		final String label;

		public Mark(TileObject object, Color color, boolean clickbox)
		{
			this(object, color, clickbox, null);
		}

		/** @param label a short tag drawn on the object, such as its place in the walking order */
		public Mark(TileObject object, Color color, boolean clickbox, String label)
		{
			this.object = object;
			this.color = color;
			this.clickbox = clickbox;
			this.label = label;
		}
	}

	private volatile List<Mark> marks = Collections.emptyList();

	public RoomHighlights()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	public void show(List<Mark> marks)
	{
		this.marks = marks == null ? Collections.emptyList() : marks;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		List<Mark> list = marks;
		if (list.isEmpty())
		{
			return null;
		}
		g.setStroke(new BasicStroke(1.6f));
		for (Mark m : list)
		{
			Shape shape = m.clickbox ? m.object.getClickbox() : hull(m.object);
			if (shape == null)
			{
				continue;
			}
			g.setColor(Theme.alpha(m.color, 44));
			g.fill(shape);
			g.setColor(Theme.alpha(m.color, 220));
			g.draw(shape);
			if (m.label != null)
			{
				Rectangle box = shape.getBounds();
				seal(g, m.label, (int) box.getCenterX(), (int) box.getCenterY(), m.color);
			}
		}
		return null;
	}

	/** A small gilt seal with the number in it, centred on a point. */
	static void seal(Graphics2D g, String text, int cx, int cy, Color color)
	{
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics fm = g.getFontMetrics();
		int d = Math.max(16, fm.stringWidth(text) + 8);
		int x = cx - d / 2;
		int y = cy - d / 2;
		g.setPaint(new GradientPaint(0, y, Theme.mix(color, Color.WHITE, 0.25), 0, y + d, Theme.mix(color, Theme.INK_DEEP, 0.45)));
		g.fillOval(x, y, d, d);
		g.setColor(Theme.INK_DEEP);
		g.drawOval(x, y, d, d);
		g.drawString(text, cx - fm.stringWidth(text) / 2, cy + fm.getAscent() / 2 - 2);
	}

	private static Shape hull(TileObject object)
	{
		if (object instanceof net.runelite.api.GameObject)
		{
			return ((net.runelite.api.GameObject) object).getConvexHull();
		}
		return object.getClickbox();
	}
}

