/**
 * The Plunder Pilot side panel: the crest with the clock or the deepest room, then three pages.
 * Pilot is the next step and the route room by room, Odds is the sceptre and how dry the
 * player has been, and Runs is the rate, the way to a goal level and every run so far.
 */
public class PilotPanel extends PluginPanel
{
	static final int WIDTH = 200;
	private static final String[] TABS = {"pilot", "odds", "runs"};
	private static final int RECENT = 8;

	private final Actions actions;
	private final Crest crest = new Crest();
	private final Segmented tabs = new Segmented(true, "Pilot", "Odds", "Runs");
	private final Segmented goal = new Segmented(false, Goal.EXPERIENCE.getLabel(), Goal.SCEPTRE.getLabel());
	private final CardLayout cards = new CardLayout();
	private final JPanel content = new JPanel(cards);
	private final JScrollPane pilot = scroller();
	private final JScrollPane odds = scroller();
	private final JScrollPane runs = scroller();

	private View view = View.loggedOut();

	public PilotPanel(Actions actions)
	{
		super(false);
		this.actions = actions;
		setLayout(new BorderLayout());
		setBackground(Theme.INK);

		JPanel north = new JPanel(new BorderLayout());
		north.setOpaque(false);
		north.add(crest, BorderLayout.NORTH);
		JPanel tabHolder = new JPanel(new BorderLayout());
		tabHolder.setOpaque(false);
		tabHolder.setBorder(new EmptyBorder(8, 8, 2, 8));
		tabHolder.add(tabs, BorderLayout.CENTER);
		north.add(tabHolder, BorderLayout.SOUTH);
		add(north, BorderLayout.NORTH);

		content.setOpaque(false);
		content.add(pilot, TABS[0]);
		content.add(odds, TABS[1]);
		content.add(runs, TABS[2]);
		add(content, BorderLayout.CENTER);

		tabs.onChange(this::showTab);
		goal.onChange(i -> actions.goal(Goal.values()[i]));
		refresh(true);
	}

	private static JScrollPane scroller()
	{
		JScrollPane scroll = new JScrollPane();
		scroll.setBorder(null);
		scroll.setOpaque(false);
		scroll.getViewport().setOpaque(false);
		scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		scroll.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
		return scroll;
	}

	/** Called on the Swing thread whenever anything shown changes. */
	public void update(View view)
	{
		this.view = view;
		goal.setSelected(view.goal.ordinal(), false);
		updateCrest();
		rebuild();
	}

	/** Opens one tab, building it if it is out of date. */
	public void showTab(int index)
	{
		tabs.setSelected(index, false);
		cards.show(content, TABS[index]);
		refresh(true);
	}

	private void updateCrest()
	{
		switch (view.state)
		{
			case LOGGED_OUT:
				crest.update("PYRAMID PLUNDER", null, "Runs planned to your level", "Log in to plan your runs",
					Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.45), Theme.GOLD_DIM, -1);
				return;
			case TOO_LOW:
				crest.update("THIEVING " + view.level, "21", "to enter", "The pyramid opens at Thieving 21", Theme.TEXT_MUTED, Theme.GOLD_DIM, -1);
				return;
			default:
				break;
		}
		Plan plan = view.plan;
		if (view.inRun())
		{
			Plan.Stop stop = plan.current();
			int ticks = view.live.ticksLeft;
			Color tint = Theme.clock(ticks);
			crest.update("ROOM " + stop.getRoom().getNumber() + " OF " + plan.getTop().getNumber(), Format.clock(ticks), "left",
				view.step.getTitle(), ticks <= 150 ? tint : Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.45), tint,
				ticks / (double) Planner.RUN_TICKS);
			return;
		}
		Plan fresh = view.fresh;
		crest.update("THIEVING " + view.level + "  -  " + view.goal.getLabel().toUpperCase(Locale.ENGLISH),
			String.valueOf(fresh.getTop().getNumber()), fresh.getTop().getNumber() == 1 ? "room" : "rooms",
			Format.amount(fresh.xpPerHour(Planner.RESTART_TICKS)) + " xp/hr, sceptre " + Format.oneInShort(fresh.getSceptreChance()),
			Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.35), Theme.GOLD, -1);
	}

	private String oddsShown;
	private String runsShown;
	/** The Pilot page shows an older view than the one in hand. */
	private boolean pilotStale = true;

	/**
	 * The Pilot page changes every tick of a run; the other two only when a run is added, the level
	 * or goal changes or a minute passes. While the panel is closed nothing is rebuilt, and while it
	 * is open only the page in view is, and that only when what it shows has changed.
	 */
	private void rebuild()
	{
		pilotStale = true;
		refresh(false);
	}

	@Override
	public void onActivate()
	{
		refresh(true);
	}

	private void refresh(boolean force)
	{
		if (!force && !isShowing())
		{
			return;
		}
		int page = tabs.getSelected();
		if (page == 0)
		{
			if (pilotStale)
			{
				pilotStale = false;
				rebuildPilot();
			}
			return;
		}
		View.Record r = view.record;
		String common = view.state + "|" + view.level + "|" + view.goal + "|" + r.totalRuns + "|" + r.runs.size() + "|" + r.sceptres
			+ "|" + r.paceSamples;
		if (page == 1)
		{
			long opened = 0;
			for (long o : r.opened)
			{
				opened += o;
			}
			String odds = common + "|" + opened + "|" + view.now / 86_400_000L;
			if (!odds.equals(oddsShown))
			{
				oddsShown = odds;
				rebuildOdds();
			}
			return;
		}
		StringBuilder goals = new StringBuilder();
		for (NavigatorGoals.Need n : view.goals)
		{
			goals.append(n.getGoal()).append(n.getLevel()).append(',');
		}
		// The pyramid lights the room of the run in hand.
		int room = view.inRun() ? view.plan.current().getRoom().getNumber() : 0;
		String runsKey = common + "|" + view.xp + "|" + view.targetLevel + "|" + r.recentRate + "|" + view.now / 60_000L + "|" + goals + "|" + room;
		if (!runsKey.equals(runsShown))
		{
			runsShown = runsKey;
			rebuildRuns();
		}
	}

	private boolean waiting(StackPanel stack)
	{
		if (view.state == View.State.LOGGED_OUT)
		{
			stack.add(note("The pyramid is sealed", "Log in and the Pilot plans every Pyramid Plunder run for your Thieving level: which rooms to walk through, which urns, chests and sarcophagi are worth the clock, and your odds of the Pharaoh's sceptre."));
			return true;
		}
		if (view.state == View.State.TOO_LOW)
		{
			int left = Levels.xpFor(Room.ENTRY_LEVEL) - (int) Math.min(Integer.MAX_VALUE, view.xp);
			stack.add(note("Not yet", "Pyramid Plunder needs Thieving 21, and the level cannot be boosted. You are " + Format.amount(Math.max(0, left)) + " experience away."));
			return true;
		}
		return false;
	}

	// The Pilot tab.

	private void rebuildPilot()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(pilot, stack);
			return;
		}
		stack.add(new SectionHeader("Run for", view.inRun() ? "replanned every tick" : null));
		stack.add(goal);

		Card next = new Card(new BorderLayout(0, 4));
		boolean danger = view.step.getKind() == Step.Kind.DANGER;
		next.accent(danger ? Theme.BLOOD : view.inRun() ? Theme.clock(view.live.ticksLeft) : Theme.TEAL).highlighted(view.inRun());
		next.add(Ui.label(danger ? "FIRST" : view.inRun() ? "NEXT" : "BEFORE YOU GO IN", Theme.small(), Theme.TEXT_FAINT), BorderLayout.NORTH);
		JPanel words = new JPanel(new BorderLayout(0, 2));
		words.setOpaque(false);
		words.add(Ui.label(view.step.getTitle(), Theme.title(), danger ? Theme.BLOOD : Theme.GOLD_BRIGHT), BorderLayout.NORTH);
		words.add(Ui.wrapped(view.step.getDetail(), Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		next.add(words, BorderLayout.CENTER);
		stack.add(next);

		if (!view.inRun() && view.ready != null)
		{
			stack.add(new SectionHeader("Ready check"));
			Card ready = new Card(new BorderLayout());
			StackPanel checks = new StackPanel(4, 0);
			for (Check check : view.ready.checks)
			{
				checks.add(new CheckRow(check, WIDTH - 30));
			}
			ready.add(checks, BorderLayout.CENTER);
			stack.add(ready);
			if (view.ready.artefacts > 0)
			{
				stack.add(Ui.wrapped("Carrying " + view.ready.artefacts + (view.ready.artefacts == 1 ? " artefact" : " artefacts") + " worth "
					+ Format.coins(view.ready.artefactValue) + " gp. They sell for about the same at the Grand Exchange.", Theme.small(), Theme.GOLD_DIM, WIDTH - 16));
			}
		}

		Plan plan = view.plan;
		boolean split = view.inRun() && view.live.split != null;
		JPanel tiles = new JPanel(new GridLayout(1, split ? 3 : 2, 6, 0));
		tiles.setOpaque(false);
		if (view.inRun())
		{
			tiles.add(new StatTile("+" + Format.amount(view.live.thievingXp), "This run",
				"+" + Format.amount(plan.getThievingXp()) + (split ? "" : " to come"), Theme.GOLD));
			double chance = 1 - (1 - view.live.sceptreSoFar) * (1 - plan.getSceptreChance());
			tiles.add(new StatTile(Format.oneIn(chance), "Sceptre", view.live.opened + (split ? " opened" : " opened so far"), Theme.TEAL));
			if (split)
			{
				int d = view.live.split;
				Color c = Math.round(d * 0.6) == 0 ? Theme.TEXT_MUTED : d < 0 ? Theme.GREEN : Theme.EMBER;
				tiles.add(new StatTile(Format.split(d), "Split", "vs best", c));
			}
		}
		else
		{
			tiles.add(new StatTile(Format.amount(plan.getThievingXp()), "Per run",
				plan.getStrengthXp() > 0 ? "+" + Format.amount(plan.getStrengthXp()) + " strength" : "thieving xp", Theme.GOLD));
			tiles.add(new StatTile(Format.oneIn(plan.getSceptreChance()), "Sceptre", "a run", Theme.TEAL));
		}
		stack.add(tiles);

		stack.add(new SectionHeader("Route", "room " + plan.current().getRoom().getNumber() + " to " + plan.getTop().getNumber()));
		Card route = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(0, 0);
		for (Plan.Stop stop : plan.getStops())
		{
			rows.add(new RoomRow(stop, view.inRun() && stop == plan.current()));
		}
		for (int i = plan.getTop().ordinal() + 1; i < Room.values().length; i++)
		{
			rows.add(new RoomRow(Room.values()[i]));
		}
		route.add(rows, BorderLayout.CENTER);
		stack.add(route);
		String foot = view.record.paceSamples >= Pace.TRUSTED
			? "Paced from your own searches. Chests and sarcophagi last in each room, so a swarm or mummy has the least time to chase."
			: "Paced at typical speeds until a few of your runs are timed. Chests and sarcophagi last in each room.";
		stack.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		replace(pilot, stack);
	}

	// The Odds tab.

	private void rebuildOdds()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(odds, stack);
			return;
		}
		View.Record r = view.record;
		long opened = 0;
		for (long o : r.opened)
		{
			opened += o;
		}
		double expected = Odds.expected(r.opened);
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(String.format(Locale.ENGLISH, "%,d", opened), "Opened", "chests & sarcs", Theme.GOLD));
		tiles.add(new StatTile(String.format(Locale.ENGLISH, "%.2f", expected), "Expected", r.sceptres + " found so far",
			r.sceptres > 0 ? Theme.TEAL : Theme.TEXT_MUTED));
		stack.add(tiles);

		Card luck = new Card(new BorderLayout(0, 6));
		luck.accent(Theme.TEAL);
		if (opened == 0)
		{
			luck.add(Ui.label("No openings yet", Theme.body(), Theme.GOLD), BorderLayout.NORTH);
			luck.add(Ui.wrapped("Every grand gold chest and sarcophagus you open is counted by room, and your sceptre luck is measured against it.",
				Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		}
		else
		{
			double share = Odds.luck(r.opened, r.sceptres);
			String verdict;
			Color color;
			if (r.sceptres == 0)
			{
				double had = Odds.atLeastOne(r.opened);
				verdict = Format.percent(had) + " would have one by now";
				color = had > 0.5 ? Theme.EMBER : Theme.GOLD;
			}
			else if (share >= 0.5)
			{
				verdict = "Luckier than " + Format.percent(share);
				color = Theme.TEAL;
			}
			else
			{
				verdict = "Drier than " + Format.percent(1 - share);
				color = Theme.EMBER;
			}
			luck.add(Ui.label(verdict, Theme.body(), color), BorderLayout.NORTH);
			luck.add(new Meter("Your luck", Format.percent(share), share, color, 0.5), BorderLayout.CENTER);
		}
		stack.add(luck);

		Plan fresh = view.fresh;
		double perRun = fresh.getSceptreChance();
		stack.add(new SectionHeader("Your runs", view.goal.getLabel()));
		Card forecast = new Card(new BorderLayout(0, 6));
		StackPanel lines = new StackPanel(4, 0);
		lines.add(line("Each run", Format.oneIn(perRun), Theme.TEAL));
		lines.add(line("Even odds", Format.amount(Odds.runsFor(perRun, 0.5)) + " runs", Theme.GOLD));
		lines.add(line("Nine in ten", Format.amount(Odds.runsFor(perRun, 0.9)) + " runs", Theme.GOLD));
		lines.add(line("In an hour", Format.percent(fresh.sceptrePerHour(Planner.RESTART_TICKS)), Theme.GOLD));
		forecast.add(lines, BorderLayout.CENTER);
		Outlook outlook = Outlook.of(r.history, view.now);
		long even = outlook.afterRuns(Odds.runsFor(perRun, 0.5), view.now);
		if (even > 0)
		{
			// The run counts above, turned into days at the pace the player really comes back.
			long nine = outlook.afterRuns(Odds.runsFor(perRun, 0.9), view.now);
			StackPanel dates = new StackPanel(4, 0);
			dates.add(line("Even odds by", Format.shortDay(even), Theme.TEAL));
			dates.add(line("Nine in ten by", nine > 0 ? Format.shortDay(nine) : "years off", Theme.TEAL));
			dates.add(Ui.wrapped("At your pace: " + Format.duration(Math.round(outlook.hoursPerWeek() * 3_600_000L)) + " a week here, over the last four weeks.",
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 30));
			forecast.add(dates, BorderLayout.SOUTH);
		}
		stack.add(forecast);
		if (view.goal == Goal.EXPERIENCE)
		{
			stack.add(Ui.wrapped("Hunting the sceptre opens every chest and the sarcophagi from room 4 on, at some cost in experience. Switch the goal on the Pilot page to compare.",
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}

		stack.add(new SectionHeader("Per opening", "chest or sarc"));
		Card rooms = new Card(new BorderLayout());
		StackPanel rows = new StackPanel(3, 0);
		for (Room room : Room.values())
		{
			boolean open = view.level >= room.getLevel();
			long n = r.opened[room.ordinal()];
			rows.add(line("Room " + room.getNumber() + (n > 0 ? "  -  " + Format.amount(n) + " opened" : ""),
				"1 in " + String.format(Locale.ENGLISH, "%,d", room.getSceptreOneIn()), open ? Theme.TEAL : Theme.TEXT_FAINT));
		}
		rooms.add(rows, BorderLayout.CENTER);
		stack.add(rooms);
		stack.add(Ui.wrapped("Finding the sceptre ejects you from the pyramid at once. Rates are the game's, per the Old School wiki.",
			Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		replace(odds, stack);
	}

	// The Runs tab.

	private void rebuildRuns()
	{
		StackPanel stack = new StackPanel(8, 8);
		if (waiting(stack))
		{
			replace(runs, stack);
			return;
		}
		View.Record r = view.record;
		Plan fresh = view.fresh;
		int forecast = fresh.xpPerHour(Planner.RESTART_TICKS);
		int rate = r.recentRate > 0 ? r.recentRate : forecast;
		JPanel tiles = new JPanel(new GridLayout(1, 2, 6, 0));
		tiles.setOpaque(false);
		tiles.add(new StatTile(Format.amount(rate), "Xp an hour", r.recentRate > 0 ? "your last runs" : "forecast", Theme.GOLD));
		tiles.add(new StatTile(Format.amount(r.totalRuns), "Runs", r.totalRuns == 0 ? "none logged yet" : Format.coins(r.totalArtefacts) + " gp loot", Theme.TEAL));
		stack.add(tiles);
		// The ladder, drawn as the pyramid it climbs, with the player's level and their goals up its side.
		stack.add(new PyramidCard(view.ladder, view.level, view.inRun() ? view.plan.current().getRoom() : null, r.sceptres, view.goals));
		stack.add(cardButton());

		addSession(stack, r.session);
		addHistory(stack, r.history);

		int target = Math.max(view.level + 1, Math.min(99, view.targetLevel));
		if (view.level < 99)
		{
			long goalXp = Levels.xpFor(target);
			long left = Math.max(0, goalXp - view.xp);
			int perRun = Math.max(1, fresh.getThievingXp());
			long runsLeft = (left + perRun - 1) / perRun;
			long start = Levels.xpFor(view.level);
			double share = goalXp <= start ? 1 : (view.xp - start) / (double) (goalXp - start);
			Card goalCard = new Card(new BorderLayout(0, 6));
			goalCard.accent(Theme.GOLD);
			goalCard.add(Ui.label("Thieving " + target, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
			String hours = Format.duration(Math.round(left * 3_600_000.0 / Math.max(1, rate)));
			goalCard.add(new Meter(Format.amount(left) + " xp, " + Format.amount(runsLeft) + (runsLeft == 1 ? " run" : " runs"), hours, share, Theme.GOLD, -1),
				BorderLayout.CENTER);
			Outlook outlook = Outlook.of(r.history, view.now);
			StackPanel south = new StackPanel(4, 0);
			long by = outlook.afterHours(left / (double) Math.max(1, rate), view.now);
			if (by > 0)
			{
				south.add(Ui.label("About " + Format.shortDay(by) + " at your pace", Theme.small(), Theme.TEAL));
			}
			int unlock = Room.nextUnlock(view.level);
			if (unlock > 0 && unlock < target)
			{
				long toUnlock = Math.max(0, Levels.xpFor(unlock) - view.xp);
				south.add(Ui.wrapped("Room " + Room.highest(unlock).getNumber() + " opens at " + unlock + ", " + Format.amount(toUnlock)
					+ " xp away, and every run after pays more.", Theme.small(), Theme.TEXT_MUTED, WIDTH - 30));
			}
			if (south.getComponentCount() > 0)
			{
				goalCard.add(south, BorderLayout.SOUTH);
			}
			stack.add(goalCard);
			addGoals(stack, fresh, rate, outlook);
		}

		addStash(stack, view.stash);


		addSplits(stack, r);
		addLeaks(stack, r.leaks);

		if (!r.runs.isEmpty())
		{
			stack.add(new SectionHeader("Recent runs", Format.amount(r.totalXp) + " xp in all"));
			Card recent = new Card(new BorderLayout());
			StackPanel runRows = new StackPanel(4, 0);
			for (int i = r.runs.size() - 1; i >= 0 && i >= r.runs.size() - RECENT; i--)
			{
				Run run = r.runs.get(i);
				runRows.add(new RunRow(run, view.now));
			}
			recent.add(runRows, BorderLayout.CENTER);
			stack.add(recent);
		}
		replace(runs, stack);
	}

	/** The sitting in hand, or the last one: what it earned, its rate and the sceptre chance it carried. */
	/**
	 * The Thieving levels Codex Navigator's pinned goals need, each with the runs, play time and
	 * date it takes at the Pilot's plan and the player's pace.
	 */
	private void addGoals(StackPanel stack, Plan fresh, int rate, Outlook outlook)
	{
		if (view.goals.isEmpty())
		{
			return;
		}
		stack.add(new SectionHeader("For your goals", "Navigator"));
		Card card = new Card(new BorderLayout());
		card.accent(Theme.TEAL);
		StackPanel rows = new StackPanel(6, 0);
		int perRun = Math.max(1, fresh.getThievingXp());
		for (NavigatorGoals.Need n : view.goals)
		{
			long left = Math.max(0, Levels.xpFor(n.getLevel()) - view.xp);
			long runsLeft = (left + perRun - 1) / perRun;
			double hours = left / (double) Math.max(1, rate);
			long by = outlook.afterHours(hours, view.now);
			JPanel row = new JPanel(new BorderLayout(0, 1));
			row.setOpaque(false);
			JPanel top = new JPanel(new BorderLayout(6, 0));
			top.setOpaque(false);
			JLabel title = Ui.label(n.getGoal(), Theme.body(), n.isFocus() ? Theme.GOLD_BRIGHT : Theme.TEXT);
			title.setToolTipText(n.getGoal() + (n.isFocus() ? ", your Navigator focus" : "") + ", needs Thieving " + n.getLevel());
			top.add(title, BorderLayout.CENTER);
			top.add(Ui.label(String.valueOf(n.getLevel()), Theme.body(), Theme.GOLD), BorderLayout.EAST);
			row.add(top, BorderLayout.NORTH);
			String how = Format.amount(runsLeft) + (runsLeft == 1 ? " run, " : " runs, ")
				+ Format.duration(Math.round(hours * 3_600_000L)) + (by > 0 ? ", " + Format.shortDay(by) : "");
			row.add(Ui.label(how, Theme.small(), Theme.TEXT_MUTED), BorderLayout.SOUTH);
			rows.add(row);
		}
		card.add(rows, BorderLayout.CENTER);
		stack.add(card);
	}

	private void addSession(StackPanel stack, Session s)
	{
		if (s == null || s.isEmpty())
		{
			return;
		}
		int count = s.getRuns().size();
		String title = s.isCurrent() ? "This session" : "Last session";
		String when = s.isCurrent() ? Format.duration(s.spanMs()) : Format.shortDay(s.getStartedAt());
		stack.add(new SectionHeader(title, when));
		Card card = new Card(new BorderLayout(0, 6));
		card.accent(s.isCurrent() ? Theme.GOLD : Theme.GOLD_DIM);
		JPanel figures = new JPanel(new GridLayout(1, 3, 4, 0));
		figures.setOpaque(false);
		figures.add(figure(String.valueOf(count), count == 1 ? "run" : "runs", Theme.GOLD));
		figures.add(figure(Format.amount(s.xpPerHour()), "xp/hr", Theme.GOLD_BRIGHT));
		figures.add(figure(Format.coins(s.artefactsPerHour()), "gp/hr", Theme.GOLD));
		card.add(figures, BorderLayout.NORTH);
		card.add(new SessionBars(s.getRuns()), BorderLayout.CENTER);
		StackPanel lines = new StackPanel(3, 0);
		lines.add(line("Thieving", "+" + Format.amount(s.getXp()) + " xp", Theme.GOLD));
		if (s.getStrengthXp() > 0)
		{
			lines.add(line("Strength", "+" + Format.amount(s.getStrengthXp()) + " xp", Theme.GOLD_DIM));
		}
		if (s.getSceptres() > 0)
		{
			lines.add(line("Sceptre", s.getSceptres() == 1 ? "found!" : s.getSceptres() + " found!", Theme.TEAL));
		}
		else if (s.getSceptreChance() > 0)
		{
			lines.add(line("Sceptre chance", Format.oneIn(s.getSceptreChance()) + " (" + Format.percent(s.getSceptreChance()) + ")", Theme.TEAL));
		}
		Run best = s.best();
		if (best != null && count > 1)
		{
			lines.add(line("Best run", "+" + Format.amount(best.getThievingXp()) + ", room " + best.getDeepest(), Theme.GOLD));
		}
		card.add(lines, BorderLayout.SOUTH);
		stack.add(card);
	}

	/** The most past sessions listed. */
	private static final int PAST_SESSIONS = 8;

	/** Every session kept, newest first, each against the best one's pace. */
	/** Copies a picture of the climb, to paste into a chat. */
	private JComponent cardButton()
	{
		JPanel buttons = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		buttons.setOpaque(false);
		CodexButton copy = new CodexButton("Copy pyramid card", false, null);
		copy.setToolTipText("Copies a picture of your pyramid and what your runs earn, to paste into a chat");
		copy.setAction(() ->
		{
			try
			{
				Toolkit.getDefaultToolkit().getSystemClipboard().setContents(PyramidSheet.transferable(PyramidSheet.render(view)), null);
				copy.flash("Copied: paste it anywhere");
			}
			catch (IllegalStateException e)
			{
				// Another program holds the clipboard.
				copy.flash("Clipboard busy, try again");
			}
		});
		buttons.add(copy);
		return buttons;
	}

	private void addHistory(StackPanel stack, List<Session> history)
	{
		if (history.size() < 2)
		{
			return;
		}
		Session best = Session.best(history);
		int bestRate = 0;
		for (Session s : history)
		{
			bestRate = Math.max(bestRate, s.xpPerHour());
		}
		// The best session is the gilt row below; the heading counts them rather than say its rate again.
		stack.add(new SectionHeader("Past sessions", history.size() + " sessions"));
		Card card = new Card(new BorderLayout(0, 4));
		StackPanel rows = new StackPanel(4, 0);
		for (int i = 0; i < history.size() && i < PAST_SESSIONS; i++)
		{
			Session s = history.get(i);
			rows.add(new SessionRow(s, bestRate, s == best));
		}
		card.add(rows, BorderLayout.CENTER);
		if (history.size() > PAST_SESSIONS)
		{
			card.add(Ui.label(olderNote(history.size() - PAST_SESSIONS), Theme.small(), Theme.TEXT_FAINT), BorderLayout.SOUTH);
		}
		stack.add(card);
		Session latest = history.get(0);
		if (best != null && latest != best && latest.getRuns().size() >= Session.BEST_MIN_RUNS)
		{
			int gap = best.xpPerHour() - latest.xpPerHour();
			stack.add(Ui.wrapped((latest.isCurrent() ? "This session runs " : "Your last session ran ") + Format.amount(Math.abs(gap))
				+ " xp/hr " + (gap > 0 ? "below" : "above") + " your best, on " + Format.shortDay(best.getStartedAt()) + ".",
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
		}
	}

	/** "1 older session not shown", "3 older sessions not shown". */
	static String olderNote(int older)
	{
		return older + (older == 1 ? " older session" : " older sessions") + " not shown";
	}

	/** The artefacts waiting in the bank, with what they fetch at the Grand Exchange. */
	private void addStash(StackPanel stack, View.Stash stash)
	{
		if (stash == null)
		{
			return;
		}
		long count = stash.count();
		stack.add(new SectionHeader("Artefacts banked", count == 0 ? null : Format.coins(stash.value()) + " gp"));
		String seen = "Bank as last seen " + Format.ago(view.now - stash.seenAt) + (stash.from == null ? "" : ", by " + stash.from) + ".";
		if (count == 0)
		{
			stack.add(Ui.wrapped("None in the bank. " + seen, Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
			return;
		}
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		StackPanel rows = new StackPanel(3, 0);
		for (View.Stash.Line l : stash.lines)
		{
			rows.add(line(l.name + " x" + Format.amount(l.count), Format.coins(l.value), Theme.GOLD));
		}
		card.add(rows, BorderLayout.CENTER);
		stack.add(card);
		stack.add(Ui.wrapped(count + (count == 1 ? " artefact" : " artefacts") + " waiting to be sold at the Grand Exchange. " + seen,
			Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
	}

	/** A number over a small word, centred, for the session card. */
	private static JComponent figure(String value, String label, Color color)
	{
		JPanel p = new JPanel(new BorderLayout(0, 0));
		p.setOpaque(false);
		JLabel v = Ui.label(value, Theme.title(), color);
		v.setHorizontalAlignment(JLabel.CENTER);
		JLabel l = Ui.label(label, Theme.small(), Theme.TEXT_FAINT);
		l.setHorizontalAlignment(JLabel.CENTER);
		p.add(v, BorderLayout.CENTER);
		p.add(l, BorderLayout.SOUTH);
		return p;
	}

	/** The last run to the deepest room, room by room, against the best before it. */
	private void addSplits(StackPanel stack, View.Record r)
	{
		Splits best = r.splits;
		Run run = r.splitRun;
		if (best == null || best.getTop() == null)
		{
			return;
		}
		Room top = best.getTop();
		if (top.ordinal() == 0)
		{
			return;
		}
		if (run == null)
		{
			stack.add(new SectionHeader("Splits", "to room " + top.getNumber()));
			stack.add(Ui.wrapped("Reach room " + top.getNumber() + " on a " + view.goal.getLabel().toLowerCase(Locale.ENGLISH)
				+ " run and the Pilot keeps your splits: when you entered each room, against your best run.", Theme.small(), Theme.TEXT_FAINT, WIDTH - 16));
			return;
		}
		boolean compared = best.hasBest();
		Integer gap = compared ? best.delta(top, run.splitAt(top)) : null;
		String trailing = gap == null ? "first run" : gap < 0 ? "new best" : "best " + Format.clock(best.bestAt(top));
		stack.add(new SectionHeader("Splits", trailing));
		Card card = new Card(new BorderLayout(0, 6));
		card.accent(gap != null && gap < 0 ? Theme.GREEN : Theme.GOLD);
		card.add(new SplitTable(run, best), BorderLayout.CENTER);
		String foot;
		int sob = best.sumOfBest();
		if (!compared)
		{
			foot = "Your first timed run to room " + top.getNumber() + ". The next one is measured against it.";
		}
		else if (sob >= 0 && sob < best.bestAt(top))
		{
			foot = "Each bar is how long the room took; its tick is the room's quickest ever. Your quickest rooms together reach room "
				+ top.getNumber() + " at " + Format.clock(sob) + ", " + Format.seconds(best.bestAt(top) - sob) + " under your best.";
		}
		else
		{
			foot = "Each bar is how long the room took; its tick is the room's quickest ever.";
		}
		card.add(Ui.wrapped(foot, Theme.small(), Theme.TEXT_FAINT, WIDTH - 30), BorderLayout.SOUTH);
		stack.add(card);
	}

	/** Where the clock goes: each room's usual crossing against its quickest, priced in experience an hour. */
	private void addLeaks(StackPanel stack, Leaks leaks)
	{
		if (leaks == null || leaks.getTop() == null || leaks.getTop().ordinal() == 0)
		{
			return;
		}
		boolean urns = leaks.getFasterUrnsFrom() != null;
		if (leaks.getRooms().isEmpty() && !urns)
		{
			return;
		}
		Leaks.Leak worst = leaks.biggest();
		int total = leaks.total();
		stack.add(new SectionHeader("Time lost", total >= 100 ? Format.amount(total) + " xp/h" : "none"));
		Card card = new Card(new BorderLayout(0, 6));
		card.accent(worst != null ? Theme.EMBER : Theme.GREEN);
		StackPanel body = new StackPanel(6, 0);
		if (!leaks.getRooms().isEmpty())
		{
			body.add(new LeakTable(leaks));
			String foot;
			if (worst != null)
			{
				foot = "Room " + worst.getRoom().getNumber() + " gives the most away: its trap, walk and door usually take you " + Format.seconds(worst.getTypical())
					+ ", " + Format.seconds(worst.getGap()) + " over your quickest. That fast every run buys searches deeper down worth about "
					+ Format.amount(worst.getXpPerHour()) + " xp an hour.";
			}
			else
			{
				foot = "You get through every room about as fast as you ever have, so the clock is going on searches.";
			}
			body.add(Ui.wrapped(foot + " Searching is not counted. From your last " + leaks.getRuns() + " runs to room " + leaks.getTop().getNumber() + ".",
				Theme.small(), Theme.TEXT_FAINT, WIDTH - 30));
		}
		if (urns)
		{
			int n = leaks.getMovedUrns();
			body.add(Ui.wrapped("Your urns in room " + leaks.getFasterUrnsFrom().getNumber() + " take you longer than in room " + leaks.getFasterUrnsTo().getNumber()
				+ ", so the plan now searches " + n + (n == 1 ? " more urn" : " more urns") + " in room " + leaks.getFasterUrnsTo().getNumber()
				+ " instead: about " + Format.amount(leaks.getUrnGain()) + " xp a run more than timing every room alike.", Theme.small(), Theme.TEAL, WIDTH - 30));
		}
		card.add(body, BorderLayout.CENTER);
		stack.add(card);
	}

	private static JComponent line(String left, String right, Color color)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JLabel l = Ui.label(left, Theme.small(), Theme.TEXT_MUTED);
		row.add(l, BorderLayout.CENTER);
		row.add(Ui.label(right, Theme.small(), color), BorderLayout.EAST);
		return row;
	}

	static Card note(String title, String text)
	{
		Card card = new Card(new BorderLayout(0, 4));
		card.accent(Theme.GOLD_DIM);
		card.add(Ui.label(title, Theme.body(), Theme.GOLD), BorderLayout.NORTH);
		card.add(Ui.wrapped(text, Theme.small(), Theme.TEXT_MUTED, WIDTH - 30), BorderLayout.CENTER);
		return card;
	}

	private static void replace(JScrollPane scroll, JComponent view)
	{
		int position = scroll.getVerticalScrollBar().getValue();
		scroll.setViewportView(view);
		scroll.revalidate();
		SwingUtilities.invokeLater(() -> scroll.getVerticalScrollBar().setValue(position));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		g.setColor(Theme.INK);
		g.fillRect(0, 0, getWidth(), getHeight());
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.NavigatorGoals;
import com.codex.plunder.core.Plan;
import com.codex.plunder.core.Planner;
import com.codex.plunder.core.Room;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JComponent;

/**
 * The pyramid itself: eight tiers, one a room, room 1 at the base and the Pharaoh's room under the
 * capstone, each beside the level that opens it and the experience an hour a run to it pays. The
 * rooms open to the player are sandstone, the rest dark; their own Thieving level and the levels
 * Codex Navigator's goals need are marked up its side, so the climb still ahead can be seen.
 */
class PyramidCard extends JComponent
{
	private static final int PAD = 12;
	private static final int TIER = 18;
	private static final int CAP = 12;
	private static final int TOP = 30;
	private static final int BASE_W = 86;
	/** Room for the level marks to the pyramid's left. */
	private static final int MARGIN = 30;
	private static final int LEVELS = 10;
	private static final int HEIGHT = TOP + CAP + Room.values().length * TIER + 34;

	/** One mark up the pyramid's side: the player's level, or a goal's. */
	static final class Mark
	{
		final int level;
		final String label;
		final boolean you;
		int y;

		Mark(int level, String label, boolean you)
		{
			this.level = level;
			this.label = label;
			this.you = you;
		}
	}

	private final List<Plan> ladder;
	private final int level;
	private final Room current;
	private final int sceptres;
	private final List<Mark> marks = new ArrayList<>();

	/**
	 * @param ladder a fresh run at each room's entry level, room 1 first
	 * @param current the room of the run in hand, or null outside a run
	 * @param goals the Thieving levels Navigator's goals need
	 */
	PyramidCard(List<Plan> ladder, int level, Room current, int sceptres, List<NavigatorGoals.Need> goals)
	{
		this.ladder = ladder;
		this.level = level;
		this.current = current;
		this.sceptres = sceptres;
		StringBuilder tip = new StringBuilder("<html>You: Thieving " + level);
		int[] levels = new int[goals.size()];
		for (int i = 0; i < levels.length; i++)
		{
			NavigatorGoals.Need n = goals.get(i);
			levels[i] = n.getLevel();
			if (n.getLevel() > level && n.getLevel() <= 99)
			{
				tip.append("<br>").append(n.getLevel()).append(": ").append(Ui.escape(n.getGoal()));
			}
		}
		marks.addAll(marks(level, levels));
		spread(marks, top(), base(), 11);
		setToolTipText(tip.append("</html>").toString());
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/** Most goal levels marked, the nearest first, so the marks always fit up the side. */
	static final int MOST_GOALS = 6;

	/**
	 * The marks up the side: the player's level, then each level a goal needs above it, once however
	 * many goals share it, and only the nearest few.
	 */
	static List<Mark> marks(int level, int[] goals)
	{
		List<Mark> out = new ArrayList<>();
		out.add(new Mark(level, String.valueOf(level), true));
		java.util.TreeSet<Integer> above = new java.util.TreeSet<>();
		for (int g : goals)
		{
			if (g > level && g <= 99)
			{
				above.add(g);
			}
		}
		for (int g : above)
		{
			if (out.size() > MOST_GOALS)
			{
				break;
			}
			out.add(new Mark(g, String.valueOf(g), false));
		}
		return out;
	}

	private static int top()
	{
		return TOP + CAP;
	}

	private static int base()
	{
		return TOP + CAP + Room.values().length * TIER;
	}

	/**
	 * Where a Thieving level sits up the pyramid: the base is 21, where the pyramid opens, and each
	 * tier spans the ten levels to the next room, the top one 91 to 99.
	 */
	static int levelY(int level, int top, int base)
	{
		int tiers = Room.values().length;
		double tier = (Math.max(Room.ENTRY_LEVEL, Math.min(99, level)) - Room.ENTRY_LEVEL) / (double) LEVELS;
		if (tier > tiers - 1)
		{
			// The top tier is 91 to 99, eight levels rather than ten.
			tier = tiers - 1 + (tier - (tiers - 1)) * LEVELS / 8.0;
		}
		return (int) Math.round(base - Math.min(tiers, tier) * (base - top) / tiers);
	}

	/**
	 * Places the marks at their levels, then nudges any too close apart so no two labels overlap,
	 * keeping them in level order and inside the pyramid's height.
	 */
	static void spread(List<Mark> marks, int top, int base, int gap)
	{
		marks.sort((a, b) -> Integer.compare(a.level, b.level));
		for (Mark m : marks)
		{
			m.y = levelY(m.level, top, base);
		}
		// Upwards from the lowest: each sits at least a gap above the one below.
		for (int i = 1; i < marks.size(); i++)
		{
			marks.get(i).y = Math.min(marks.get(i).y, marks.get(i - 1).y - gap);
		}
		// Then back down from the top, if that pushed any past it.
		if (!marks.isEmpty() && marks.get(marks.size() - 1).y < top)
		{
			marks.get(marks.size() - 1).y = top;
			for (int i = marks.size() - 2; i >= 0; i--)
			{
				marks.get(i).y = Math.max(marks.get(i).y, marks.get(i + 1).y + gap);
			}
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, HEIGHT - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, HEIGHT, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);

		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Ui.shadowed(g, "The pyramid", PAD, 8 + body.getAscent(), Theme.GOLD);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String head = "xp an hour";
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(head, w - PAD - small.stringWidth(head), 8 + body.getAscent());

		int top = top();
		int base = base();
		float cx = PAD + MARGIN + BASE_W / 2f;
		Room mine = level >= Room.ENTRY_LEVEL ? Room.highest(level) : null;
		Room[] rooms = Room.values();
		int labelX = (int) (cx + BASE_W / 2f) + 10;

		// The capstone: gilt once a sceptre has come out of the pyramid.
		float capHalf = half(top, top - CAP, base);
		Path2D cap = new Path2D.Float();
		cap.moveTo(cx, top - CAP);
		cap.lineTo(cx + capHalf + 3, top - 1);
		cap.lineTo(cx - capHalf - 3, top - 1);
		cap.closePath();
		g.setPaint(sceptres > 0 ? new GradientPaint(cx - 6, top - CAP, Theme.GOLD_BRIGHT, cx + 6, top, Theme.GOLD)
			: new GradientPaint(cx - 6, top - CAP, Theme.STROKE, cx + 6, top, Theme.INK_DEEP));
		g.fill(cap);
		if (sceptres > 0)
		{
			String found = sceptres == 1 ? "1 sceptre" : sceptres + " sceptres";
			Ui.shadowed(g, found, labelX, top - 2, Theme.TEAL);
		}

		for (Room room : rooms)
		{
			int i = room.ordinal();
			int yb = base - i * TIER;
			int yt = yb - TIER + 1;
			float hb = half(yb, top - CAP, base);
			float ht = half(yt, top - CAP, base);
			Path2D tier = new Path2D.Float();
			tier.moveTo(cx - hb, yb);
			tier.lineTo(cx + hb, yb);
			tier.lineTo(cx + ht, yt);
			tier.lineTo(cx - ht, yt);
			tier.closePath();
			boolean open = mine != null && room.ordinal() <= mine.ordinal();
			boolean here = room == current;
			Color face = here ? Theme.TEAL : open ? Theme.mix(Theme.GOLD_DIM, Theme.GOLD, 0.25 + 0.6 * i / rooms.length) : Theme.mix(Theme.INK_DEEP, Theme.STROKE, 0.6);
			// Lit from the left, as the sun falls on the desert.
			g.setPaint(new GradientPaint(cx - hb, 0, Theme.mix(face, Color.WHITE, open || here ? 0.12 : 0), cx + hb, 0, Theme.mix(face, Theme.INK_DEEP, 0.45)));
			g.fill(tier);
			g.setColor(room == mine && !here ? Theme.GOLD_BRIGHT : Theme.alpha(Theme.INK_DEEP, 200));
			g.draw(tier);
			// The room's number on its face.
			String n = String.valueOf(room.getNumber());
			g.setColor(open || here ? Theme.alpha(Theme.INK_DEEP, 220) : Theme.TEXT_FAINT);
			g.drawString(n, Math.round(cx - small.stringWidth(n) / 2f), yb - (TIER - small.getAscent()) / 2 - 1);

			// Beside it: the level that opens it and what a run to it pays.
			int mid = yb - TIER / 2 + small.getAscent() / 2 - 1;
			Plan p = i < ladder.size() ? ladder.get(i) : null;
			String rate = p == null ? "" : Format.amount(p.xpPerHour(Planner.RESTART_TICKS));
			Color c = here ? Theme.TEAL : room == mine ? Theme.GOLD_BRIGHT : open ? Theme.GOLD : Theme.TEXT_FAINT;
			g.setColor(open || here ? Theme.TEXT_MUTED : Theme.TEXT_FAINT);
			g.drawString(String.valueOf(room.getLevel()), labelX, mid);
			Ui.shadowed(g, rate, w - PAD - small.stringWidth(rate), mid, c);
			// A faint course line from the tier to its figures.
			g.setColor(Theme.alpha(c, 40));
			g.drawLine(Math.round(cx + hb) + 3, yb - TIER / 2, labelX - 3, yb - TIER / 2);
		}

		// The player's level and the goals' levels, up the left side.
		for (Mark m : marks)
		{
			int ly = levelY(m.level, top, base);
			float hx = cx - half(ly, top - CAP, base);
			Color c = m.you ? Theme.GOLD_BRIGHT : Theme.TEAL;
			if (!m.you)
			{
				// The goal's level, dashed across the climb still to make.
				g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{2f, 2f}, 0f));
				g.setColor(Theme.alpha(Theme.TEAL, 150));
				g.drawLine(Math.round(hx), ly, Math.round(cx + half(ly, top - CAP, base)), ly);
				g.setStroke(new BasicStroke(1f));
			}
			// A pointer from the label to the slope.
			Path2D tip = new Path2D.Float();
			tip.moveTo(hx - 2, ly);
			tip.lineTo(hx - 7, ly - 3);
			tip.lineTo(hx - 7, ly + 3);
			tip.closePath();
			g.setColor(c);
			g.fill(tip);
			g.setColor(Theme.alpha(c, 110));
			g.drawLine(PAD + small.stringWidth(m.label) + 3, m.y, Math.round(hx) - 7, ly);
			Ui.shadowed(g, m.label, PAD, m.y + small.getAscent() / 2, c);
		}

		g.setColor(Theme.TEXT_FAINT);
		String foot = marks.size() > 1 ? "Gold: you. Teal: Navigator goals." : "Your level is marked in gold.";
		g.drawString(Ui.clip(foot, small, w - PAD * 2), PAD, HEIGHT - 10);
		g.dispose();
	}

	/** Half the pyramid's width at a height, from nothing at the apex to half the base. */
	private static float half(float y, float apex, float base)
	{
		return Math.max(0, (y - apex) / (base - apex)) * BASE_W / 2f;
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Planner;
import com.codex.plunder.core.Room;
import com.codex.plunder.core.Session;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Image;
import java.awt.RadialGradientPaint;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.Transferable;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

/**
 * The pyramid card: the player's climb drawn as the panel's pyramid, beside what their runs earn,
 * in the panel's ink and gold. Made to be pasted into a chat to show a friend how far up the
 * Thieving pyramid they are, so it carries its own heading and needs nothing around it. Nothing on
 * it is an item picture, so it is drawn whole the moment it is asked for.
 */
public final class PyramidSheet
{
	static final int WIDTH = 330;
	private static final int PAD = 14;
	private static final int HEADER = 66;
	/** The pyramid's own width on the card; the figures take the rest. */
	private static final int PYRAMID_W = 196;

	private PyramidSheet()
	{
	}

	/** One figure in the column beside the pyramid. */
	static final class Fact
	{
		final String label;
		final String value;
		final String note;
		final Color color;

		Fact(String label, String value, String note, Color color)
		{
			this.label = label;
			this.value = value;
			this.note = note;
			this.color = color;
		}
	}

	/**
	 * The four figures beside the pyramid, most telling first: the experience an hour, the runs
	 * made, the sceptre, and the best session or, before there is one, the next room to open.
	 * A first look with no runs yet still fills all four, from the forecast.
	 */
	static List<Fact> facts(View view)
	{
		List<Fact> out = new ArrayList<>();
		View.Record r = view.record;
		int forecast = view.fresh.xpPerHour(Planner.RESTART_TICKS);
		boolean measured = r.recentRate > 0;
		out.add(new Fact("Xp an hour", Format.amount(measured ? r.recentRate : forecast), measured ? "your last runs" : "forecast", Theme.GOLD));
		out.add(new Fact("Runs", Format.amount(r.totalRuns), r.totalRuns == 0 ? "none logged yet"
			: Format.amount(r.totalXp) + " xp", Theme.TEAL));
		double chance = view.fresh.getSceptreChance();
		if (r.sceptres > 0)
		{
			out.add(new Fact(r.sceptres == 1 ? "Sceptre" : "Sceptres", String.valueOf(r.sceptres), r.sceptres == 1 ? "found" : "found so far", Theme.TEAL));
		}
		else
		{
			out.add(new Fact("Sceptre", chance > 0 ? Format.oneIn(chance) : "-", "chance a run", Theme.GOLD));
		}
		Session best = Session.best(r.history);
		int unlock = Room.nextUnlock(view.level);
		if (best != null)
		{
			out.add(new Fact("Best session", Format.amount(best.xpPerHour()), "xp an hour, " + Format.shortDay(best.getStartedAt()), Theme.GOLD));
		}
		else if (unlock > 0)
		{
			out.add(new Fact("Next room", "Room " + Room.highest(unlock).getNumber(), "opens at " + unlock, Theme.TEAL));
		}
		else
		{
			out.add(new Fact("Rooms", "All 8", "open to you", Theme.GOLD));
		}
		return out;
	}

	/** The card's heading: whose climb it is, or the plain kicker when names are left off. */
	static String kicker(String player)
	{
		return player == null ? "PYRAMID PLUNDER" : player.toUpperCase(Locale.ENGLISH) + "'S PYRAMID";
	}

	/** Draws the card. */
	public static BufferedImage render(View view)
	{
		List<Fact> facts = facts(view);
		PyramidCard pyramid = new PyramidCard(view.ladder, view.level, null, view.record.sceptres, view.goals);
		int pyramidH = pyramid.getPreferredSize().height;
		int bodyY = HEADER + 12;
		int footY = bodyY + pyramidH + 12;
		int height = footY + 26;
		BufferedImage image = new BufferedImage(WIDTH, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);

		// The parchment-dark ground with a gilt frame.
		RoundRectangle2D frame = new RoundRectangle2D.Float(0.5f, 0.5f, WIDTH - 1, height - 1, 14, 14);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, height, Theme.INK_DEEP));
		g.fill(frame);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.3), 0, HEADER, Theme.alpha(Theme.INK, 0)));
		g.fill(new RoundRectangle2D.Float(1, 1, WIDTH - 2, HEADER, 13, 13));
		g.setStroke(new BasicStroke(1.5f));
		g.setPaint(new GradientPaint(0, 0, Theme.GOLD, 0, height, Theme.GOLD_DIM));
		g.draw(new RoundRectangle2D.Float(1, 1, WIDTH - 2.5f, height - 2.5f, 13, 13));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 40));
		g.draw(new RoundRectangle2D.Float(4.5f, 4.5f, WIDTH - 9, height - 9, 10, 10));

		header(g, view.nameOnCard ? view.player : null, view.level);
		rule(g, HEADER + 2);

		// The pyramid, as the Runs page draws it.
		pyramid.setSize(PYRAMID_W, pyramidH);
		Graphics2D pg = (Graphics2D) g.create(PAD, bodyY, PYRAMID_W, pyramidH);
		pyramid.paint(pg);
		pg.dispose();

		// The figures beside it.
		int fx = PAD + PYRAMID_W + 12;
		int fw = WIDTH - fx - PAD;
		int each = pyramidH / facts.size();
		int fy = bodyY + 2;
		for (Fact f : facts)
		{
			fact(g, f, fx, fy, fw, each);
			fy += each;
		}

		// The foot: where it came from and when.
		rule(g, footY);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String left = view.goal.getLabel() + " runs";
		String right = "Codex Plunder Pilot  -  " + Format.shortDay(view.now);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(left, small, WIDTH - PAD * 2 - small.stringWidth(right) - 10), PAD, footY + 16);
		g.setColor(Theme.GOLD_DIM);
		g.drawString(right, WIDTH - PAD - small.stringWidth(right), footY + 16);
		g.dispose();
		return image;
	}

	private static void header(Graphics2D g, String player, int level)
	{
		int md = 46;
		int mx = PAD;
		int my = (HEADER - md) / 2 + 3;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 10, my + 10, md - 20);

		int tx = mx + md + 12;
		int room = WIDTH - tx - PAD;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(kicker(player), small, room), tx, my + 12);
		Crest.paintLarge(g, "THIEVING " + level, tx, my + 18, Theme.GOLD);
	}

	private static void fact(Graphics2D g, Fact f, int x, int y, int w, int h)
	{
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(f.label.toUpperCase(Locale.ENGLISH), small, w), x, y + small.getAscent());
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(f.value, bold, w), x, y + small.getHeight() + bold.getAscent() + 1, f.color);
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(f.note, small, w), x, y + small.getHeight() + bold.getHeight() + small.getAscent() + 1);
		// A hairline under each figure, fading out, to keep the column in step with the tiers.
		int ly = y + h - 6;
		g.setPaint(new GradientPaint(x, 0, Theme.alpha(Theme.GOLD, 70), x + w, 0, Theme.alpha(Theme.GOLD, 0)));
		g.drawLine(x, ly, x + w, ly);
	}

	private static void rule(Graphics2D g, int y)
	{
		g.setPaint(new GradientPaint(PAD, 0, Theme.alpha(Theme.GOLD, 0), WIDTH / 2f, 0, Theme.alpha(Theme.GOLD, 140), true));
		g.drawLine(PAD, y, WIDTH - PAD, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(WIDTH / 2f, y - 3);
		diamond.lineTo(WIDTH / 2f + 3, y);
		diamond.lineTo(WIDTH / 2f, y + 3);
		diamond.lineTo(WIDTH / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
	}

	/** The card as something the system clipboard can hold. */
	public static Transferable transferable(Image image)
	{
		return new Transferable()
		{
			@Override
			public DataFlavor[] getTransferDataFlavors()
			{
				return new DataFlavor[]{DataFlavor.imageFlavor};
			}

			@Override
			public boolean isDataFlavorSupported(DataFlavor flavor)
			{
				return DataFlavor.imageFlavor.equals(flavor);
			}

			@Override
			public Object getTransferData(DataFlavor flavor) throws UnsupportedFlavorException
			{
				if (!isDataFlavorSupported(flavor))
				{
					throw new UnsupportedFlavorException(flavor);
				}
				return image;
			}
		};
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Plan;
import com.codex.plunder.core.Room;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import javax.swing.JComponent;

/**
 * One room of the route: a numbered seal, the room's level, and what to do there. The room the
 * player stands in is ringed in teal; rooms walked straight through sit quietly; rooms the level
 * does not open yet are faded, with the level that opens them.
 */
class RoomRow extends JComponent
{
	private static final int HEIGHT = 34;

	private final Room room;
	private final Plan.Stop stop;
	private final boolean here;
	private final int locked;

	/** A room on the route. */
	RoomRow(Plan.Stop stop, boolean here)
	{
		this.room = stop.getRoom();
		this.stop = stop;
		this.here = here;
		this.locked = 0;
		init();
	}

	/** A room not open yet. */
	RoomRow(Room room)
	{
		this.room = room;
		this.stop = null;
		this.here = false;
		this.locked = room.getLevel();
		init();
	}

	private void init()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setToolTipText("Room " + room.getNumber() + ": urns " + room.getUrnXp() + " xp, chest " + room.getChestXp()
			+ " xp, sceptre 1 in " + room.getSceptreOneIn());
	}

	static String work(Plan.Stop stop)
	{
		if (stop.isPassThrough())
		{
			return "Pass through";
		}
		StringBuilder text = new StringBuilder();
		if (stop.getUrns() > 0)
		{
			text.append(stop.getUrns()).append(stop.getUrns() == 1 ? " urn" : " urns");
		}
		if (stop.isChest())
		{
			text.append(text.length() > 0 ? " + " : "").append("chest");
		}
		if (stop.isSarcophagus())
		{
			text.append(text.length() > 0 ? " + " : "").append("sarc");
		}
		return text.toString();
	}

	private int xp()
	{
		return stop.getUrns() * room.getUrnXp() + (stop.isChest() ? room.getChestXp() : 0);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		boolean pass = stop != null && stop.isPassThrough();
		Color seal = locked > 0 ? Theme.STROKE : pass ? Theme.GOLD_DIM : Theme.GOLD;

		if (here)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 26));
			g.fillRoundRect(0, 1, w, h - 2, 8, 8);
		}

		// The seal: a gilt disc with the room's number.
		int d = 22;
		int sx = 4;
		int sy = (h - d) / 2;
		g.setPaint(new GradientPaint(0, sy, locked > 0 ? Theme.CARD_TOP : Theme.mix(seal, Color.WHITE, 0.2), 0, sy + d, locked > 0 ? Theme.CARD : Theme.mix(seal, Theme.INK_DEEP, 0.4)));
		g.fill(new Ellipse2D.Float(sx, sy, d, d));
		g.setStroke(new BasicStroke(here ? 1.6f : 1f));
		g.setColor(here ? Theme.TEAL : Theme.INK_DEEP);
		g.draw(new Ellipse2D.Float(sx + 0.5f, sy + 0.5f, d - 1, d - 1));
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		String n = String.valueOf(room.getNumber());
		g.setColor(locked > 0 ? Theme.TEXT_FAINT : Theme.INK_DEEP);
		g.drawString(n, sx + (d - bold.stringWidth(n)) / 2, sy + (d + bold.getAscent()) / 2 - 2);

		int tx = sx + d + 8;
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int top = h / 2 - 2;
		int bottom = h / 2 + small.getAscent() + 1;

		String right = locked > 0 ? "Opens at " + locked : pass ? "" : "+" + Format.amount(xp());
		int rw = small.stringWidth(right);
		g.setFont(Theme.body());
		String name = (locked > 0 ? "Room " + room.getNumber() : stop == null ? "" : work(stop));
		Color nameColor = locked > 0 ? Theme.TEXT_FAINT : pass ? Theme.TEXT_MUTED : Theme.TEXT;
		if (body.stringWidth(name) > w - tx - rw - 12)
		{
			// "13 urns + chest + sarc" beside its experience steps down a size before it is cut.
			g.setFont(Theme.small());
			Ui.shadowed(g, Ui.clip(name, small, w - tx - rw - 12), tx, top, nameColor);
		}
		else
		{
			Ui.shadowed(g, name, tx, top, nameColor);
		}
		g.setFont(Theme.small());
		boolean opening = stop != null && (stop.isSarcophagus() || stop.isChest());
		String odds = opening ? "1/" + room.getSceptreOneIn() : "";
		int oddsW = opening ? small.stringWidth(odds) + 8 : 0;
		String sub = locked > 0 ? room.getUrnXp() + " xp an urn" : here
			? (stop.getUrnsLeft() < room.getUrns() ? "Here, " + (room.getUrns() - stop.getUrnsLeft()) + " searched" : "You are here")
			: "Level " + room.getLevel();
		g.setColor(here ? Theme.TEAL : Theme.TEXT_FAINT);
		g.drawString(Ui.clip(sub, small, w - tx - oddsW - 6), tx, bottom);
		if (!right.isEmpty())
		{
			g.setColor(locked > 0 ? Theme.TEXT_FAINT : Theme.GOLD);
			g.drawString(right, w - rw - 6, top);
		}
		if (opening)
		{
			g.setColor(Theme.alpha(Theme.TEAL, 200));
			g.drawString(odds, w - small.stringWidth(odds) - 6, bottom);
		}
		g.dispose();
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Run;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/** One past run: how deep, what it paid, and when; a sceptre run is marked in teal. */
class RunRow extends JComponent
{
	private final Run run;
	private final long now;

	RunRow(Run run, long now)
	{
		this.run = run;
		this.now = now;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 32));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		int top = h / 2 - 2;
		int bottom = h / 2 + small.getAscent() + 1;
		int x = 0;
		if (run.isSceptre())
		{
			Sigil.paint(g, 0, (h - 16) / 2f, 16);
			x = 20;
		}
		String title = "+" + Format.amount(run.getThievingXp()) + " xp";
		Ui.shadowed(g, title, x, top, run.isSceptre() ? Theme.TEAL : Theme.GOLD);
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_MUTED);
		g.drawString("to room " + run.getDeepest(), x + body.stringWidth(title) + 6, top);
		String when = Format.ago(now - run.getAt());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(when, w - small.stringWidth(when), top);

		StringBuilder sub = new StringBuilder();
		sub.append(run.getUrns()).append(run.getUrns() == 1 ? " urn" : " urns");
		if (run.getChests() > 0)
		{
			sub.append(", ").append(run.getChests()).append(run.getChests() == 1 ? " chest" : " chests");
		}
		if (run.getSarcophagi() > 0)
		{
			sub.append(", ").append(run.getSarcophagi()).append(" sarc");
		}
		if (run.getArtefacts() > 0)
		{
			sub.append(", ").append(Format.coins(run.getArtefacts())).append(" gp");
		}
		if (run.isSceptre())
		{
			sub.insert(0, "Sceptre!  ");
		}
		g.setColor(run.isSceptre() ? Theme.TEAL : Theme.TEXT_FAINT);
		g.drawString(Ui.clip(sub.toString(), small, w - x - 40), x, bottom);
		String clock = Format.clock(run.getTicks());
		g.drawString(clock, w - small.stringWidth(clock), bottom);
		g.dispose();
	}
}

package com.codex.plunder.ui;

import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import javax.swing.JComponent;

/** A small-caps heading with a gold diamond and a line that fades into the dark. */
public class SectionHeader extends JComponent
{
	private final String text;
	private final String trailing;

	public SectionHeader(String text)
	{
		this(text, null);
	}

	public SectionHeader(String text, String trailing)
	{
		this.text = text.toUpperCase();
		this.trailing = trailing;
		setFont(Theme.small());
		setPreferredSize(new Dimension(10, 20));
		setMinimumSize(new Dimension(10, 20));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(getFont());
		paint(g, text, trailing, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a heading in a box; the card uses the same drawing. The font must already be set. */
	static void paint(Graphics2D g, String text, String trailing, int x, int y, int w, int h)
	{
		int mid = y + h / 2 + 2;
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(x + 4, mid - 4);
		diamond.lineTo(x + 8, mid);
		diamond.lineTo(x + 4, mid + 4);
		diamond.lineTo(x, mid);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);

		FontMetrics fm = g.getFontMetrics();
		int textX = x + 13;
		int baseline = mid + fm.getAscent() / 2 - 1;
		g.setColor(Theme.GOLD);
		g.drawString(text, textX, baseline);

		int lineStart = textX + fm.stringWidth(text) + 6;
		int lineEnd = x + w;
		if (trailing != null && !trailing.isEmpty())
		{
			int tw = fm.stringWidth(trailing);
			lineEnd = x + w - tw - 6;
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(trailing, x + w - tw, baseline);
		}
		if (lineEnd > lineStart)
		{
			g.setPaint(new GradientPaint(lineStart, 0, Theme.alpha(Theme.GOLD, 110), lineEnd, 0, Theme.alpha(Theme.GOLD, 0)));
			g.drawLine(lineStart, mid, lineEnd, mid);
		}
	}
}

package com.codex.plunder.ui;

import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.util.function.IntConsumer;
import javax.swing.JComponent;

/**
 * Tabs drawn as one engraved strip: the chosen segment is lit from below by a
 * gold glow, the rest sit quietly in the ink.
 */
public class Segmented extends JComponent
{
	private final String[] labels;
	private final boolean large;
	private final Animator slide = new Animator(this);
	private int selected;
	private int hover = -1;
	private IntConsumer listener;

	public Segmented(boolean large, String... labels)
	{
		this.labels = labels;
		this.large = large;
		setFont(large ? Theme.title() : Theme.small());
		int h = large ? 28 : 22;
		setPreferredSize(new Dimension(10, h));
		setMinimumSize(new Dimension(10, h));
		setMaximumSize(new Dimension(Integer.MAX_VALUE, h));
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter mouse = new MouseAdapter()
		{
			@Override
			public void mouseMoved(MouseEvent e)
			{
				int index = indexAt(e.getX());
				if (index != hover)
				{
					hover = index;
					repaint();
				}
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = -1;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				setSelected(indexAt(e.getX()), true);
			}
		};
		addMouseListener(mouse);
		addMouseMotionListener(mouse);
	}

	public void onChange(IntConsumer listener)
	{
		this.listener = listener;
	}

	public int getSelected()
	{
		return selected;
	}

	public void setSelected(int index, boolean notify)
	{
		if (index < 0 || index >= labels.length)
		{
			return;
		}
		boolean changed = index != selected;
		selected = index;
		slide.set(index, true);
		repaint();
		if (changed && notify && listener != null)
		{
			listener.accept(index);
		}
	}

	private int indexAt(int x)
	{
		int w = Math.max(1, getWidth());
		return Math.max(0, Math.min(labels.length - 1, x * labels.length / w));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		float seg = w / (float) labels.length;

		RoundRectangle2D strip = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setColor(Theme.INK_DEEP);
		g.fill(strip);

		float x = (float) (slide.get() * seg);
		RoundRectangle2D lit = new RoundRectangle2D.Float(x + 2, 2, seg - 4, h - 4, 6, 6);
		g.setPaint(new GradientPaint(0, 2, Theme.CARD_TOP, 0, h, Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35)));
		g.fill(lit);
		g.setColor(Theme.alpha(Theme.GOLD, 120));
		g.draw(lit);
		g.setColor(Theme.GOLD_BRIGHT);
		g.fillRect(Math.round(x + seg * 0.3f), h - 4, Math.round(seg * 0.4f), 1);

		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < labels.length; i++)
		{
			int tx = Math.round(i * seg + (seg - fm.stringWidth(labels[i])) / 2);
			int ty = (h + fm.getAscent()) / 2 - (large ? 2 : 1);
			java.awt.Color color = i == selected ? Theme.GOLD_BRIGHT : i == hover ? Theme.TEXT : Theme.TEXT_MUTED;
			Ui.shadowed(g, labels[i], tx, ty, color);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(strip);
		g.dispose();
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Run;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.util.List;
import javax.swing.JComponent;

/**
 * The session's runs as a row of gilt bars, oldest on the left, each as tall as the experience
 * it paid. The best run is lit brightest and a sceptre run stands in teal.
 */
class SessionBars extends JComponent
{
	/** The most bars drawn; a longer session shows its newest runs. */
	private static final int MOST = 30;

	private final List<Run> runs;

	SessionBars(List<Run> runs)
	{
		this.runs = runs.size() > MOST ? runs.subList(runs.size() - MOST, runs.size()) : runs;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 34));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setColor(Theme.alpha(Theme.GOLD, 40));
		g.fillRect(0, h - 1, w, 1);
		if (runs.isEmpty())
		{
			g.dispose();
			return;
		}
		int most = 1;
		Run best = null;
		for (Run r : runs)
		{
			if (best == null || r.getThievingXp() > best.getThievingXp())
			{
				best = r;
			}
			most = Math.max(most, r.getThievingXp());
		}
		int gap = 2;
		int slot = Math.max(3, Math.min(14, (w + gap) / runs.size() - gap));
		int x = 0;
		for (Run r : runs)
		{
			int bh = Math.max(2, (int) Math.round((h - 3) * r.getThievingXp() / (double) most));
			Color c = r.isSceptre() ? Theme.TEAL : r == best ? Theme.GOLD_BRIGHT : Theme.GOLD_DIM;
			g.setPaint(new GradientPaint(0, h - bh, c, 0, h, Theme.mix(c, Theme.INK, 0.55)));
			g.fillRoundRect(x, h - 1 - bh, slot, bh, 3, 3);
			x += slot + gap;
		}
		g.dispose();
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Session;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/**
 * One past session: when, how many runs and how long, its experience an hour, and a gauge of that
 * rate against the best session's. The best session is lit and marked with a diamond.
 */
class SessionRow extends JComponent
{
	private final Session session;
	private final int bestRate;
	private final boolean best;

	SessionRow(Session session, int bestRate, boolean best)
	{
		this.session = session;
		this.bestRate = bestRate;
		this.best = best;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 34));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int top = small.getAscent() + 2;
		int x = 0;
		if (best)
		{
			SplitTable.diamond(g, 3, top - 4, Theme.GOLD_BRIGHT);
			x = 10;
		}
		String when = session.isCurrent() ? "Now" : Format.shortDay(session.getStartedAt());
		Ui.shadowed(g, when, x, top, best ? Theme.GOLD_BRIGHT : Theme.GOLD);
		int runs = session.getRuns().size();
		String what = runs + (runs == 1 ? " run, " : " runs, ") + Format.duration(session.spanMs());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(what, small, w - x - small.stringWidth(when) - 70), x + small.stringWidth(when) + 6, top);
		String rate = Format.amount(session.xpPerHour()) + " xp/hr";
		Ui.shadowed(g, rate, w - small.stringWidth(rate), top, best ? Theme.GOLD_BRIGHT : Theme.GOLD);

		// The rate against the best session's, with a teal tick for a sceptre found.
		int barY = top + 7;
		int barW = w;
		g.setColor(Theme.alpha(Theme.GOLD, 30));
		g.fillRect(0, barY, barW, 4);
		double share = bestRate <= 0 ? 0 : Math.min(1, session.xpPerHour() / (double) bestRate);
		Color fill = best ? Theme.GOLD_BRIGHT : session.isCurrent() ? Theme.GOLD : Theme.GOLD_DIM;
		g.setColor(fill);
		g.fillRect(0, barY, (int) Math.round(barW * share), 4);
		if (session.getSceptres() > 0)
		{
			g.setColor(Theme.TEAL);
			String found = session.getSceptres() == 1 ? "sceptre" : session.getSceptres() + " sceptres";
			g.drawString(found, w - small.stringWidth(found), barY + 4 + small.getAscent() + 1);
		}
		g.dispose();
	}
}

package com.codex.plunder.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;

/**
 * The Pilot's mark: a stepped gilt pyramid under a desert sky, with the Pharaoh's sceptre
 * standing before it, its teal jewel catching the light.
 */
public final class Sigil
{
	private Sigil()
	{
	}

	public static BufferedImage icon(int size)
	{
		BufferedImage image = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		Theme.smooth(g);
		paint(g, 0, 0, size);
		g.dispose();
		return image;
	}

	/** Draws the mark in a size by size box. */
	public static void paint(Graphics2D g, float x, float y, float size)
	{
		float s = size / 16f;
		float stroke = Math.max(0.6f, 0.55f * s);

		// The pyramid: a lit face and a shadowed face meeting at the ridge.
		float apexX = x + 7.4f * s;
		float apexY = y + 1.6f * s;
		float baseY = y + 14.2f * s;
		float left = x + 0.6f * s;
		float right = x + 14.2f * s;
		float ridgeX = x + 8.8f * s;
		Path2D lit = new Path2D.Float();
		lit.moveTo(apexX, apexY);
		lit.lineTo(ridgeX, baseY);
		lit.lineTo(left, baseY);
		lit.closePath();
		Path2D shade = new Path2D.Float();
		shade.moveTo(apexX, apexY);
		shade.lineTo(right, baseY);
		shade.lineTo(ridgeX, baseY);
		shade.closePath();
		g.setPaint(new GradientPaint(x, apexY, Theme.GOLD_BRIGHT, x, baseY, Theme.GOLD));
		g.fill(lit);
		g.setPaint(new GradientPaint(x, apexY, Theme.mix(Theme.GOLD, Theme.GOLD_DIM, 0.4f), x, baseY, Theme.mix(Theme.GOLD_DIM, Theme.INK_DEEP, 0.45f)));
		g.fill(shade);

		// Courses of stone across both faces.
		g.setStroke(new BasicStroke(Math.max(0.5f, 0.4f * s)));
		g.setColor(Theme.alpha(Theme.INK_DEEP, 120));
		for (int i = 1; i <= 3; i++)
		{
			float t = i / 4f;
			float cy = apexY + (baseY - apexY) * t;
			float lx = apexX + (left - apexX) * t;
			float rx = apexX + (right - apexX) * t;
			g.drawLine(Math.round(lx), Math.round(cy), Math.round(rx), Math.round(cy));
		}
		// The doorway at the foot of the lit face.
		g.setColor(Theme.alpha(Theme.INK_DEEP, 200));
		g.fillRect(Math.round(x + 4.8f * s), Math.round(y + 11.2f * s), Math.max(1, Math.round(1.6f * s)), Math.round(3f * s));

		Path2D outline = new Path2D.Float();
		outline.moveTo(apexX, apexY);
		outline.lineTo(right, baseY);
		outline.lineTo(left, baseY);
		outline.closePath();
		g.setStroke(new BasicStroke(stroke));
		g.setColor(Theme.INK_DEEP);
		g.draw(outline);

		// The sceptre: a gilt staff with a teal jewel, standing in front of the shadowed face.
		float sx = x + 12.2f * s;
		float top = y + 5.6f * s;
		g.setStroke(new BasicStroke(Math.max(1.8f, 2.0f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.INK_DEEP);
		g.drawLine(Math.round(sx), Math.round(top + 2f * s), Math.round(sx), Math.round(y + 15.4f * s));
		g.setStroke(new BasicStroke(Math.max(0.9f, 0.9f * s), BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setPaint(new GradientPaint(sx, top, Theme.GOLD_BRIGHT, sx, y + 15 * s, Theme.GOLD_DIM));
		g.drawLine(Math.round(sx), Math.round(top + 2f * s), Math.round(sx), Math.round(y + 15f * s));
		float r = 2.1f * s;
		Ellipse2D jewel = new Ellipse2D.Float(sx - r, top - r, r * 2, r * 2);
		g.setColor(Theme.INK_DEEP);
		g.setStroke(new BasicStroke(Math.max(1.2f, 1.2f * s)));
		g.draw(jewel);
		g.setPaint(new GradientPaint(sx, top - r, Theme.mix(Theme.TEAL, Theme.TEXT, 0.4f), sx, top + r, Theme.mix(Theme.TEAL, Theme.INK_DEEP, 0.3f)));
		g.fill(jewel);
		g.setColor(new Color(255, 255, 255, 160));
		g.fill(new Ellipse2D.Float(sx - r * 0.55f, top - r * 0.6f, r * 0.6f, r * 0.6f));
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Room;
import com.codex.plunder.core.Run;
import com.codex.plunder.core.Splits;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/**
 * The last run to the deepest room, room by room, against the best before it: when each room
 * was entered, how far ahead or behind that was, and how long the room took against its quickest
 * crossing ever. A room crossed as fast as it has ever been gets a gold diamond.
 */
class SplitTable extends JComponent
{
	private static final int ROW = 17;

	private final Run run;
	private final Splits best;

	/**
	 * @param run the run to show, which reached the deepest room
	 * @param best the splits from the runs before it
	 */
	SplitTable(Run run, Splits best)
	{
		this.run = run;
		this.best = best;
		setOpaque(false);
		setPreferredSize(new Dimension(10, ROW * (best.getTop().ordinal() + 1)));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int w = getWidth();
		Room top = best.getTop();

		// Column edges: room, time entered, the gap to the best, then the room's own bar.
		int timeRight = fm.stringWidth("Room 8") + 8 + fm.stringWidth("0:00");
		int deltaRight = timeRight + 6 + fm.stringWidth("+0:00");
		int barX = deltaRight + 8;
		int barW = Math.max(20, w - barX - 2);

		int longest = 1;
		for (int i = 0; i < top.ordinal(); i++)
		{
			Room r = Room.values()[i];
			longest = Math.max(longest, Math.max(Splits.segment(run, r), best.bestSegment(r)));
		}

		for (int i = 0; i <= top.ordinal(); i++)
		{
			Room room = Room.values()[i];
			int y = i * ROW;
			int base = y + (ROW + fm.getAscent()) / 2 - 1;
			boolean last = room == top;
			if (last)
			{
				g.setColor(Theme.alpha(Theme.GOLD, 26));
				g.fill(new RoundRectangle2D.Float(-4, y, w + 8, ROW, 6, 6));
			}
			g.setColor(last ? Theme.GOLD : Theme.TEXT_MUTED);
			g.drawString("Room " + room.getNumber(), 0, base);

			int at = run.splitAt(room);
			String time = at < 0 ? "-" : Format.clock(at);
			g.setColor(last ? Theme.GOLD_BRIGHT : Theme.TEXT);
			g.drawString(time, timeRight - fm.stringWidth(time), base);

			Integer delta = i == 0 ? null : best.delta(room, at);
			if (delta != null)
			{
				String d = Format.split(delta);
				Color c = Math.round(delta * 0.6) == 0 ? Theme.TEXT_MUTED : delta < 0 ? Theme.GREEN : Theme.EMBER;
				Ui.shadowed(g, d, deltaRight - fm.stringWidth(d), base, c);
			}

			if (!last)
			{
				int seg = Splits.segment(run, room);
				int quickest = best.bestSegment(room);
				int mid = y + ROW / 2;
				g.setColor(Theme.INK_DEEP);
				g.fillRoundRect(barX, mid - 2, barW, 5, 5, 5);
				if (seg >= 0)
				{
					boolean gold = quickest < 0 || seg <= quickest;
					int fill = Math.max(2, (int) Math.round(barW * seg / (double) longest));
					g.setColor(gold ? Theme.GOLD : Theme.mix(Theme.GOLD_DIM, Theme.EMBER, quickest > 0 ? Math.min(1, (seg - quickest) / (double) quickest) : 0));
					g.fillRoundRect(barX, mid - 2, fill, 5, 5, 5);
					if (gold && quickest >= 0)
					{
						diamond(g, barX + fill + 4, mid, Theme.GOLD_BRIGHT);
					}
				}
				if (quickest >= 0)
				{
					int mx = barX + (int) Math.round(barW * quickest / (double) longest);
					g.setColor(Theme.TEXT);
					g.fillRect(Math.min(barX + barW - 1, mx), mid - 4, 1, 9);
				}
			}
		}
		g.dispose();
	}

	static void diamond(Graphics2D g, int x, int y, Color c)
	{
		Path2D d = new Path2D.Float();
		d.moveTo(x, y - 3);
		d.lineTo(x + 3, y);
		d.lineTo(x, y + 3);
		d.lineTo(x - 3, y);
		d.closePath();
		g.setColor(c);
		g.fill(d);
	}
}

package com.codex.plunder.ui;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.Insets;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;
import javax.swing.border.EmptyBorder;

/**
 * A vertical stack where every child spans the full width at its preferred height.
 * It tracks the viewport width so nothing ever scrolls sideways in the side panel.
 */
public class StackPanel extends JPanel implements Scrollable
{
	public StackPanel(int gap, int pad)
	{
		super(new StackLayout(gap));
		setOpaque(false);
		setBorder(new EmptyBorder(pad, pad, pad, pad));
	}

	public StackPanel space(int height)
	{
		JPanel spacer = new JPanel();
		spacer.setOpaque(false);
		spacer.setPreferredSize(new Dimension(1, height));
		add(spacer);
		return this;
	}

	@Override
	public Dimension getPreferredScrollableViewportSize()
	{
		return getPreferredSize();
	}

	@Override
	public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return 16;
	}

	@Override
	public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
	{
		return Math.max(16, visibleRect.height - 32);
	}

	@Override
	public boolean getScrollableTracksViewportWidth()
	{
		return true;
	}

	@Override
	public boolean getScrollableTracksViewportHeight()
	{
		return false;
	}

	static final class StackLayout implements LayoutManager
	{
		private final int gap;

		StackLayout(int gap)
		{
			this.gap = gap;
		}

		@Override
		public void addLayoutComponent(String name, Component comp)
		{
		}

		@Override
		public void removeLayoutComponent(Component comp)
		{
		}

		@Override
		public Dimension preferredLayoutSize(Container parent)
		{
			Insets in = parent.getInsets();
			int width = 0;
			int height = 0;
			int visible = 0;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				Dimension d = c.getPreferredSize();
				width = Math.max(width, d.width);
				height += d.height;
				visible++;
			}
			height += Math.max(0, visible - 1) * gap;
			return new Dimension(width + in.left + in.right, height + in.top + in.bottom);
		}

		@Override
		public Dimension minimumLayoutSize(Container parent)
		{
			return preferredLayoutSize(parent);
		}

		@Override
		public void layoutContainer(Container parent)
		{
			Insets in = parent.getInsets();
			int width = parent.getWidth() - in.left - in.right;
			int y = in.top;
			for (Component c : parent.getComponents())
			{
				if (!c.isVisible())
				{
					continue;
				}
				int h = c.getPreferredSize().height;
				c.setBounds(in.left, y, width, h);
				y += h + gap;
			}
		}
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A small engraved tablet: a big number, its label, and a quiet line of context. */
class StatTile extends JComponent
{
	private final String value;
	private final String label;
	private final String note;
	private final Color color;

	StatTile(String value, String label, String note, Color color)
	{
		this.value = value;
		this.label = label;
		this.note = note;
		this.color = color;
		setPreferredSize(new Dimension(10, 54));
		setOpaque(false);
		setToolTipText(note == null || note.isEmpty() ? label : label + ": " + note);
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		paint(g, value, label, note, color, 0, 0, getWidth(), getHeight());
		g.dispose();
	}

	/** Draws a tablet in a box; the card uses the same drawing. */
	static void paint(Graphics2D g, String value, String label, String note, Color color, int x, int y, int w, int h)
	{
		RoundRectangle2D shape = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(x, y, Theme.CARD_TOP, x, y + h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);
		g.setColor(Theme.alpha(color, 160));
		g.fillRect(x + Theme.RADIUS, y + 1, w - Theme.RADIUS * 2, 1);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label.toUpperCase(), x + 8, y + 6 + small.getAscent());

		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		Ui.shadowed(g, Ui.clip(value, bold, w - 16), x + 8, y + 8 + small.getHeight() + bold.getAscent(), color);
		if (note != null && !note.isEmpty())
		{
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip(note, small, w - 16), x + 8, y + h - 6);
		}
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;

/**
 * The Codex look: warm ink, aged gold and a single arcane teal, drawn with the
 * game's own fonts so the panel reads as part of Gielinor rather than a web page.
 * The Pilot keeps gold for what is worth doing, teal for the sceptre and its odds, and turns
 * ember then blood as the clock runs down, so the colour says how urgent a thing is before it is read.
 */
public final class Theme
{
	public static final Color INK = new Color(23, 20, 16);
	public static final Color INK_DEEP = new Color(16, 14, 11);
	public static final Color CARD = new Color(34, 30, 24);
	public static final Color CARD_TOP = new Color(42, 37, 29);
	public static final Color CARD_HOVER = new Color(48, 42, 33);
	public static final Color STROKE = new Color(66, 56, 42);
	public static final Color STROKE_SOFT = new Color(48, 41, 32);

	public static final Color GOLD = new Color(214, 178, 106);
	public static final Color GOLD_BRIGHT = new Color(246, 214, 144);
	public static final Color GOLD_DIM = new Color(132, 108, 66);
	public static final Color TEAL = new Color(96, 184, 170);
	public static final Color GREEN = new Color(130, 196, 108);
	public static final Color EMBER = new Color(222, 134, 86);
	public static final Color BLOCKED = new Color(176, 92, 84);
	public static final Color BLOOD = new Color(204, 70, 60);
	public static final Color BLOOD_DEEP = new Color(120, 32, 28);
	public static final Color VIOLET = new Color(176, 132, 222);

	public static final Color TEXT = new Color(234, 224, 202);
	public static final Color TEXT_MUTED = new Color(160, 148, 126);
	public static final Color TEXT_FAINT = new Color(110, 100, 84);

	public static final int RADIUS = 10;
	public static final int GUTTER = 8;

	private Theme()
	{
	}

	public static Font title()
	{
		return FontManager.getRunescapeBoldFont();
	}

	public static Font body()
	{
		return FontManager.getRunescapeFont();
	}

	public static Font small()
	{
		return FontManager.getRunescapeSmallFont();
	}

	public static Color alpha(Color c, int alpha)
	{
		return new Color(c.getRed(), c.getGreen(), c.getBlue(), alpha);
	}

	public static Color mix(Color a, Color b, double t)
	{
		t = Math.max(0, Math.min(1, t));
		return new Color(
			(int) Math.round(a.getRed() + (b.getRed() - a.getRed()) * t),
			(int) Math.round(a.getGreen() + (b.getGreen() - a.getGreen()) * t),
			(int) Math.round(a.getBlue() + (b.getBlue() - a.getBlue()) * t),
			(int) Math.round(a.getAlpha() + (b.getAlpha() - a.getAlpha()) * t));
	}

	/** Progress colour: ember when just begun, gold through the middle, green when nearly there. */
	public static Color progressColor(double progress)
	{
		if (progress >= 1)
		{
			return GREEN;
		}
		if (progress < 0.5)
		{
			return mix(EMBER, GOLD, progress * 2);
		}
		return mix(GOLD, TEAL, (progress - 0.5) * 2);
	}

	/** The clock as a colour: gold with time in hand, ember under ninety seconds, blood under thirty. */
	public static Color clock(int ticksLeft)
	{
		if (ticksLeft <= 50)
		{
			return BLOOD;
		}
		if (ticksLeft <= 150)
		{
			return EMBER;
		}
		return GOLD;
	}

	/** Smooth shapes, but the pixel fonts stay crisp. */
	public static void smooth(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, RenderingHints.VALUE_STROKE_PURE);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
	}
}

package com.codex.plunder.ui;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import javax.swing.JLabel;

/** Small helpers shared by the panel's components. */
public final class Ui
{
	private Ui()
	{
	}

	public static JLabel label(String text, Font font, Color color)
	{
		JLabel label = new JLabel(text);
		label.setFont(font);
		label.setForeground(color);
		return label;
	}

	/**
	 * A label that wraps inside the side panel's narrow width. Swing's HTML renderer
	 * treats CSS pixels as points, so the width is converted to keep it in screen pixels.
	 */
	public static JLabel wrapped(String text, Font font, Color color, int width)
	{
		int css = Math.round(width * 0.75f);
		return label("<html><div style='width:" + css + "px'>" + escape(text) + "</div></html>", font, color);
	}

	public static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lets a clickable card keep its hover and click while the pointer is over its children. */
	static void forwardMouse(Container root, MouseAdapter adapter)
	{
		for (Component child : root.getComponents())
		{
			child.addMouseListener(adapter);
			if (child instanceof Container)
			{
				forwardMouse((Container) child, adapter);
			}
		}
	}

	/** Text with the one pixel black shadow the game puts under its own lettering. */
	public static void shadowed(Graphics2D g, String text, int x, int y, Color color)
	{
		g.setColor(Color.BLACK);
		g.drawString(text, x + 1, y + 1);
		g.setColor(color);
		g.drawString(text, x, y);
	}

	/** Cuts text to fit a width, ending it with an ellipsis. */
	public static String clip(String text, java.awt.FontMetrics fm, int width)
	{
		if (text == null)
		{
			return "";
		}
		if (fm.stringWidth(text) <= width)
		{
			return text;
		}
		int end = text.length();
		while (end > 0 && fm.stringWidth(text.substring(0, end) + "...") > width)
		{
			end--;
		}
		return text.substring(0, end) + "...";
	}
}

package com.codex.plunder.ui;

import com.codex.plunder.core.Check;
import com.codex.plunder.core.Goal;
