import java.util.Collections;
import java.util.List;

/** Everything the panel shows, worked out on the client thread and handed over whole. */
public final class View
{
	/** What the panel has to show. */
	public enum State
	{
		LOGGED_OUT,
		TOO_LOW,
		READY
	}

	/** Totals for the account, kept apart from the run in hand. */
	public static final class Record
	{
		final List<Run> runs;
		final long[] opened;
		final int sceptres;
		final long totalRuns;
		final long totalXp;
		final long totalArtefacts;
		final int recentRate;
		final int paceSamples;
		/** The best splits as they stood before the newest run that reached the deepest room, or null. */
		Splits splits;
		/** The newest run that reached the deepest room for this goal, or null. */
		Run splitRun;
		Session session;
		/** Where the clock goes on the way to the deepest room, or null. */
		Leaks leaks;
		/** Every session in the runs kept, newest first. */
		List<Session> history = Collections.emptyList();

		public Record(List<Run> runs, long[] opened, int sceptres, long totalRuns, long totalXp, long totalArtefacts, int recentRate, int paceSamples)
		{
			this.runs = runs == null ? Collections.emptyList() : runs;
			this.opened = opened == null ? new long[Room.values().length] : opened;
			this.sceptres = sceptres;
			this.totalRuns = totalRuns;
			this.totalXp = totalXp;
			this.totalArtefacts = totalArtefacts;
			this.recentRate = recentRate;
			this.paceSamples = paceSamples;
		}

		/**
		 * @param prior the splits from the runs before {@code last}
		 * @param last the newest run that reached the deepest room, or null
		 */
		public Record leaks(Leaks leaks)
		{
			this.leaks = leaks;
			return this;
		}

		public Record splits(Splits prior, Run last)
		{
			this.splits = prior;
			this.splitRun = last;
			return this;
		}

		public Record session(Session session)
		{
			this.session = session;
			return this;
		}

		public Record history(List<Session> history)
		{
			this.history = history == null ? Collections.emptyList() : history;
			return this;
		}

		static Record empty()
		{
			return new Record(null, null, 0, 0, 0, 0, 0, 0);
		}
	}

	/** The run in hand. */
	public static final class Live
	{
		final int ticksLeft;
		final int thievingXp;
		final long artefacts;
		final int opened;
		final double sceptreSoFar;
		/** Ticks ahead (negative) or behind the best run on entering this room, or null with nothing to compare. */
		final Integer split;

		public Live(int ticksLeft, int thievingXp, long artefacts, int opened, double sceptreSoFar)
		{
			this(ticksLeft, thievingXp, artefacts, opened, sceptreSoFar, null);
		}

		public Live(int ticksLeft, int thievingXp, long artefacts, int opened, double sceptreSoFar, Integer split)
		{
			this.split = split;
			this.ticksLeft = ticksLeft;
			this.thievingXp = thievingXp;
			this.artefacts = artefacts;
			this.opened = opened;
			this.sceptreSoFar = sceptreSoFar;
		}
	}

	/** The ready check and what the pack holds, while logged in. */
	public static final class Ready
	{
		final List<Check> checks;
		final int artefacts;
		final long artefactValue;

		public Ready(List<Check> checks, int artefacts, long artefactValue)
		{
			this.checks = checks == null ? Collections.emptyList() : checks;
			this.artefacts = artefacts;
			this.artefactValue = artefactValue;
		}
	}

	/** The artefacts waiting in the bank to be sold. */
	public static final class Stash
	{
		/** One kind of artefact. */
		public static final class Line
		{
			public final int itemId;
			public final String name;
			public final long count;
			public final long value;

			public Line(int itemId, String name, long count, long value)
			{
				this.itemId = itemId;
				this.name = name;
				this.count = count;
				this.value = value;
			}
		}

		final List<Line> lines;
		final long seenAt;
		/** The plugin whose saved bank this is, or null when this plugin saw the bank. */
		final String from;

		public Stash(List<Line> lines, long seenAt, String from)
		{
			this.lines = lines == null ? Collections.emptyList() : lines;
			this.seenAt = seenAt;
			this.from = from;
		}

		long count()
		{
			long n = 0;
			for (Line l : lines)
			{
				n += l.count;
			}
			return n;
		}

		long value()
		{
			long n = 0;
			for (Line l : lines)
			{
				n += l.value;
			}
			return n;
		}
	}

	final State state;
	final String player;
	final int level;
	final long xp;
	final int targetLevel;
	final Goal goal;
	/** The rest of the run in hand, or a fresh run's plan outside the pyramid. */
	final Plan plan;
	/** A whole fresh run at this level and goal, for per-run figures. */
	final Plan fresh;
	/** A fresh run at each room's entry level, for the ladder. */
	final List<Plan> ladder;
	final Step step;
	final Live live;
	final Record record;
	final long now;
	Ready ready;
	Stash stash;
	/** The Thieving levels Codex Navigator's pinned goals still need; empty without Navigator. */
	List<NavigatorGoals.Need> goals = Collections.emptyList();
	/** Whether the pyramid card names the player; off to share it without the name. */
	boolean nameOnCard = true;

	public View(State state, String player, int level, long xp, int targetLevel, Goal goal, Plan plan, Plan fresh,
		List<Plan> ladder, Step step, Live live, Record record, long now)
	{
		this.state = state;
		this.player = player;
		this.level = level;
		this.xp = xp;
		this.targetLevel = targetLevel;
		this.goal = goal == null ? Goal.EXPERIENCE : goal;
		this.plan = plan;
		this.fresh = fresh;
		this.ladder = ladder == null ? Collections.emptyList() : ladder;
		this.step = step;
		this.live = live;
		this.record = record == null ? Record.empty() : record;
		this.now = now;
	}

	public View ready(Ready ready)
	{
		this.ready = ready;
		return this;
	}

	public View stash(Stash stash)
	{
		this.stash = stash;
		return this;
	}

	public View goals(List<NavigatorGoals.Need> goals)
	{
		this.goals = goals == null ? Collections.emptyList() : goals;
		return this;
	}

	public View nameOnCard(boolean value)
	{
		nameOnCard = value;
		return this;
	}

	public static View loggedOut()
	{
		return new View(State.LOGGED_OUT, null, 0, 0, 99, Goal.EXPERIENCE, null, null, null, null, null, null, System.currentTimeMillis());
	}

	boolean inRun()
	{
		return live != null;
	}
}

package com.codex.plunder;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/**
 * Every setting reads well in RuneLite's config panel: a short name, one plain sentence saying
 * what it does, a section it belongs in, and its own place in that section's order.
 */
public class SettingsTest
{
	@Test
	public void everySettingIsNamedAndExplainedInOneSentence()
	{
		Set<String> sections = new HashSet<>();
		for (Field f : CodexPlunderPilotConfig.class.getDeclaredFields())
		{
			ConfigSection s = f.getAnnotation(ConfigSection.class);
			if (s != null)
			{
				sections.add(f.getName());
				assertTrue(s.description().length() > 0);
			}
		}
		Set<String> keys = new HashSet<>();
		Set<String> names = new HashSet<>();
		Map<String, Set<Integer>> places = new HashMap<>();
		int items = 0;
		for (Method m : CodexPlunderPilotConfig.class.getDeclaredMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			items++;
			String where = item.keyName() + ": ";
			assertTrue(where + "key used once", keys.add(item.keyName()));
			assertTrue(where + "name used once", names.add(item.name()));
			assertTrue(where + "a short name", item.name().length() > 0 && item.name().length() <= 28);
			String d = item.description();
			assertTrue(where + "described", d.length() >= 20);
			assertTrue(where + "one sentence, no full stop: " + d, !d.endsWith(".") && !d.matches(".*[.!?] [A-Z].*"));
			assertTrue(where + "starts with a capital", Character.isUpperCase(d.charAt(0)));
			assertFalse(where + "in a section", item.section().isEmpty());
			assertTrue(where + "a known section", sections.contains(item.section()) || sectionValue(item.section()));
			assertTrue(where + "its own place in its section",
				places.computeIfAbsent(item.section(), k -> new HashSet<>()).add(item.position()));
		}
		assertTrue(items > 0);
		assertNotNull(sections);
	}

	/** A section is named by the value of its field, which may differ from the field's name. */
	private static boolean sectionValue(String value)
	{
		for (Field f : CodexPlunderPilotConfig.class.getDeclaredFields())
		{
			try
			{
				if (f.getAnnotation(ConfigSection.class) != null && value.equals(f.get(null)))
				{
					return true;
				}
			}
			catch (IllegalAccessException e)
			{
				return false;
			}
		}
		return false;
	}

	@Test
	public void choicesReadAsWords()
	{
		for (Method m : CodexPlunderPilotConfig.class.getDeclaredMethods())
		{
			if (m.getAnnotation(ConfigItem.class) != null && m.getReturnType().isEnum())
			{
				for (Object choice : m.getReturnType().getEnumConstants())
				{
					String shown = choice.toString();
					// "AT_THE_BANK" or "ALWAYS" is the code's name for a choice, not words a player reads.
					assertFalse(m.getName() + " shows " + shown, shown.length() > 1 && shown.equals(shown.toUpperCase()));
					assertEquals(m.getName() + " shows " + shown, shown.trim(), shown);
				}
			}
		}
	}

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player who changed it.
		// Every key on main and every one added since is pinned.
		Set<String> keys = new HashSet<>();
		for (Method m : CodexPlunderPilotConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : new String[]{"chaseWarning", "goalLevel", "highlights", "nameOnCard", "packWarning", "plaque", "readyPlaque", "roomOpens", "summary"})
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.plunder.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

/**
 * Damaged forms of a good saved value, for proving a reader survives what a profile can really
 * hold: nothing, a value cut short, the wrong type, numbers too big or below zero, a newer
 * version, and plain garbage. Each form is tried on its own, so a failure names the one at fault.
 */
final class Damaged
{
	/** Stand-ins for one number: too big for any type, below zero, a fraction, and the wrong type. */
	private static final String[] NUMBERS = {
		"9223372036854775807", "-9223372036854775808", "99999999999999999999999", "-1", "0", "1e308", "2.5",
		"\"7\"", "null", "true", "[]", "{}"
	};
	/** Stand-ins for one string. */
	private static final String[] STRINGS = {"\"\"", "123", "-5", "null", "{}", "[]", "\"\\u0000\""};
	/** Stand-ins for a map key that names a number, as item ids do. */
	private static final String[] KEYS = {"\"x\"", "\"-1\"", "\"0\"", "\"99999999999\"", "\"\""};
	/** Most single-token forms tried per kind, so a large value still runs quickly. */
	private static final int MOST = 150;

	private Damaged()
	{
	}

	/** Damage that has nothing to do with any particular value. */
	static List<String> anyValue()
	{
		return new ArrayList<>(Arrays.asList(null, "", "   ", "null", "[]", "{}", "[{}]", "[null]", "\"text\"", "0", "-1",
			"true", "{{{", "}", "{\"", "<html>", "\u0000\u00ff", "{\"version\":99}", "{\"version\":-1}",
			repeat("[", 20_000), repeat("{\"a\":", 10_000), "[" + repeat("1,", 200_000) + "1]",
			"\"" + repeat("x", 1_000_000) + "\""));
	}

	/** Every damaged form of {@code good} worth trying, the general ones first. */
	static List<String> of(String good)
	{
		Set<String> out = new LinkedHashSet<>();
		for (int i = 1; i < 24; i++)
		{
			out.add(good.substring(0, good.length() * i / 24));
		}
		out.add(good + "garbage");
		out.add(good + good);
		out.add(good.replace("\"version\":1", "\"version\":2"));
		out.add(good.replace("\"version\":1", "\"version\":99"));
		List<int[]> numbers = new ArrayList<>();
		List<int[]> strings = new ArrayList<>();
		List<int[]> keys = new ArrayList<>();
		tokens(good, numbers, strings, keys);
		for (String n : NUMBERS)
		{
			out.add(replaceAll(good, numbers, n));
		}
		for (int[] t : first(numbers))
		{
			for (String n : NUMBERS)
			{
				out.add(good.substring(0, t[0]) + n + good.substring(t[1]));
			}
		}
		for (int[] t : first(strings))
		{
			for (String s : STRINGS)
			{
				out.add(good.substring(0, t[0]) + s + good.substring(t[1]));
			}
		}
		for (int[] t : first(keys))
		{
			for (String k : KEYS)
			{
				out.add(good.substring(0, t[0]) + k + good.substring(t[1]));
			}
		}
		// A list where a map belongs, or a map where a list does: a value kept in an older shape.
		for (int[] t : first(containers(good)))
		{
			String with = good.charAt(t[0]) == '[' ? "{\"0\":1}" : "[1,2]";
			out.add(good.substring(0, t[0]) + with + good.substring(t[1]));
		}
		List<String> all = anyValue();
		all.addAll(out);
		return all;
	}

	/** The [start, end) spans of every list or map that is a field's value, outside strings. */
	private static List<int[]> containers(String s)
	{
		List<int[]> out = new ArrayList<>();
		for (int i = 1; i < s.length(); i++)
		{
			char c = s.charAt(i);
			if ((c == '[' || c == '{') && s.charAt(i - 1) == ':' && !inString(s, i))
			{
				int depth = 0;
				boolean quoted = false;
				for (int j = i; j < s.length(); j++)
				{
					char d = s.charAt(j);
					if (quoted)
					{
						if (d == '\\')
						{
							j++;
						}
						else if (d == '"')
						{
							quoted = false;
						}
						continue;
					}
					if (d == '"')
					{
						quoted = true;
					}
					else if (d == '[' || d == '{')
					{
						depth++;
					}
					else if ((d == ']' || d == '}') && --depth == 0)
					{
						out.add(new int[]{i, j + 1});
						break;
					}
				}
			}
		}
		return out;
	}

	private static boolean inString(String s, int at)
	{
		boolean quoted = false;
		for (int i = 0; i < at; i++)
		{
			char c = s.charAt(i);
			if (quoted && c == '\\')
			{
				i++;
			}
			else if (c == '"')
			{
				quoted = !quoted;
			}
		}
		return quoted;
	}

	private static List<int[]> first(List<int[]> tokens)
	{
		return tokens.subList(0, Math.min(MOST, tokens.size()));
	}

	private static String replaceAll(String s, List<int[]> tokens, String with)
	{
		StringBuilder b = new StringBuilder();
		int at = 0;
		for (int[] t : tokens)
		{
			b.append(s, at, t[0]).append(with);
			at = t[1];
		}
		return b.append(s.substring(at)).toString();
	}

	/** Finds the numbers, string values and numeric keys of a JSON text, as [start, end) spans. */
	private static void tokens(String s, List<int[]> numbers, List<int[]> strings, List<int[]> keys)
	{
		int i = 0;
		while (i < s.length())
		{
			char c = s.charAt(i);
			if (c == '"')
			{
				int end = i + 1;
				while (end < s.length() && s.charAt(end) != '"')
				{
					end += s.charAt(end) == '\\' ? 2 : 1;
				}
				end = Math.min(end + 1, s.length());
				int next = end;
				while (next < s.length() && Character.isWhitespace(s.charAt(next)))
				{
					next++;
				}
				boolean key = next < s.length() && s.charAt(next) == ':';
				if (!key)
				{
					strings.add(new int[]{i, end});
				}
				else if (s.substring(i + 1, end - 1).matches("-?\\d+"))
				{
					keys.add(new int[]{i, end});
				}
				i = end;
			}
			else if (c == '-' || Character.isDigit(c))
			{
				int end = i + 1;
				while (end < s.length() && "0123456789.eE+-".indexOf(s.charAt(end)) >= 0)
				{
					end++;
				}
				numbers.add(new int[]{i, end});
				i = end;
			}
			else
			{
				i++;
			}
		}
	}

	static String repeat(String s, int n)
	{
		StringBuilder b = new StringBuilder(s.length() * n);
		for (int i = 0; i < n; i++)
		{
			b.append(s);
		}
		return b.toString();
	}

	/** A short, printable form of a damaged value for a failure message. */
	static String show(String s)
	{
		if (s == null)
		{
			return "null";
		}
		return s.length() <= 120 ? s : s.substring(0, 60) + "..." + s.substring(s.length() - 40) + " (" + s.length() + " chars)";
	}
}

