package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class OutlookTest
{
	private static final long MIN = 60_000L;
	private static final long DAY = 24 * 60 * MIN;

	/** Ten five-minute runs a minute apart, starting on the given day. */
	private static void sitting(List<Run> runs, long day)
	{
		for (int i = 0; i < 10; i++)
		{
			runs.add(new Run(day * DAY + i * 6 * MIN, 500, 8, 30_000, 0, 20, 2, 0, 1000, 2, 0.01, false, Goal.EXPERIENCE));
		}
	}

	@Test
	public void twoSittingsAWeekPutAHundredRunsFiveWeeksAway()
	{
		List<Run> runs = new ArrayList<>();
		for (long day : new long[]{100, 103, 107, 110})
		{
			sitting(runs, day);
		}
		long now = 114 * DAY;
		Outlook o = Outlook.of(Session.history(runs, now), now);
		assertTrue(o.isKnown());
		// A hundred runs is ten sittings like these; at two a week that is five weeks.
		assertEquals(now + 35 * DAY, o.afterRuns(100, now), 60_000);
		assertEquals(2 * 59.6 / 60, o.hoursPerWeek(), 1e-9);
	}

	@Test
	public void oneSittingOrAnOldOneSaysNothing()
	{
		List<Run> runs = new ArrayList<>();
		sitting(runs, 100);
		assertFalse(Outlook.of(Session.history(runs, 101 * DAY), 101 * DAY).isKnown());
		sitting(runs, 101);
		// Both sittings are over four weeks old by now.
		long later = 140 * DAY;
		Outlook old = Outlook.of(Session.history(runs, later), later);
		assertFalse(old.isKnown());
		assertEquals(-1, old.afterRuns(10, later));
	}

	@Test
	public void aFirstBusyWeekendIsSpreadOverAWeek()
	{
		List<Run> runs = new ArrayList<>();
		sitting(runs, 100);
		sitting(runs, 101);
		long now = 102 * DAY;
		Outlook o = Outlook.of(Session.history(runs, now), now);
		// Two sittings in two days read as two a week, not one a day.
		assertEquals(2 * 59.6 / 60, o.hoursPerWeek(), 1e-9);
		assertEquals(-1, o.afterRuns(1_000_000, now));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PlannerTest
{
	private final Pace pace = new Pace();

	@Test
	public void roomsOpenEveryTenLevels()
	{
		assertNull(Room.highest(20));
		assertEquals(Room.ONE, Room.highest(21));
		assertEquals(Room.FOUR, Room.highest(60));
		assertEquals(Room.EIGHT, Room.highest(99));
		assertEquals(61, Room.nextUnlock(55));
		assertEquals(0, Room.nextUnlock(91));
	}

	@Test
	public void deepRoomsGetTheUrnsAndShallowRoomsArePassed()
	{
		Plan plan = Planner.fresh(91, Goal.EXPERIENCE, pace);
		assertEquals(Room.EIGHT, plan.getTop());
		assertEquals(8, plan.getStops().size());
		assertEquals(13, plan.stop(Room.EIGHT).getUrns());
		assertEquals(13, plan.stop(Room.SEVEN).getUrns());
		assertTrue(plan.stop(Room.ONE).isPassThrough());
		assertTrue(plan.stop(Room.TWO).isPassThrough());
		// Chests from room four on are cheap and always taken.
		for (Room r : new Room[]{Room.FOUR, Room.FIVE, Room.SIX, Room.SEVEN, Room.EIGHT})
		{
			assertTrue(r.name(), plan.stop(r).isChest());
		}
		assertFalse(plan.stop(Room.EIGHT).isSarcophagus());
		assertTrue(plan.getTicksNeeded() <= Planner.RUN_TICKS);
		// Roughly the quarter million an hour the wiki gives for 91.
		int rate = plan.xpPerHour(Planner.RESTART_TICKS);
		assertTrue("rate " + rate, rate > 200_000 && rate < 320_000);
	}

	@Test
	public void lowLevelsLootEverythingAndLeaveEarly()
	{
		Plan plan = Planner.fresh(25, Goal.EXPERIENCE, pace);
		assertEquals(1, plan.getStops().size());
		Plan.Stop only = plan.current();
		assertEquals(13, only.getUrns());
		assertTrue(only.isChest());
		assertTrue(plan.spare() > 100);
	}

	@Test
	public void sceptreHuntersOpenChestsAndSarcophagiFirst()
	{
		Plan plan = Planner.fresh(91, Goal.SCEPTRE, pace);
		for (Room r : Room.values())
		{
			assertTrue(r.name(), plan.stop(r).isChest());
			assertEquals(r.name(), r.getNumber() >= 4, plan.stop(r).isSarcophagus());
		}
		Plan xp = Planner.fresh(91, Goal.EXPERIENCE, pace);
		assertTrue(plan.getSceptreChance() > xp.getSceptreChance());
		// The wiki's figure for every chest and the deep sarcophagi at 91 is about 1 in 69.
		assertEquals(1 / 69.0, plan.getSceptreChance(), 0.002);
	}

	@Test
	public void aSlowRunShortensWhatFollows()
	{
		Here inSeven = new Here(Room.SEVEN, 13, false, false, true);
		Plan plenty = Planner.plan(91, Goal.EXPERIENCE, pace, inSeven, 300);
		Plan short_ = Planner.plan(91, Goal.EXPERIENCE, pace, inSeven, 120);
		assertEquals(13, plenty.stop(Room.EIGHT).getUrns());
		int urns = short_.stop(Room.SEVEN).getUrns() + short_.stop(Room.EIGHT).getUrns();
		assertTrue(urns < 13);
		// Room eight's urns pay more, so they are kept over room seven's.
		assertTrue(short_.stop(Room.EIGHT).getUrns() >= short_.stop(Room.SEVEN).getUrns());
		assertTrue(short_.getTicksNeeded() <= 120);
	}

	@Test
	public void searchedUrnsAreNotPlannedAgain()
	{
		Here half = new Here(Room.EIGHT, 5, true, false, true);
		Plan plan = Planner.plan(95, Goal.EXPERIENCE, pace, half, 400);
		assertEquals(5, plan.current().getUrns());
		assertFalse(plan.current().isChest());
		assertTrue(plan.current().isChestOpen());
	}

	@Test
	public void oddsAddUpAcrossRooms()
	{
		long[] opened = new long[8];
		opened[7] = 650;
		assertEquals(1.0, Odds.expected(opened), 1e-9);
		assertEquals(1 - Math.pow(1 - 1 / 650.0, 650), Odds.atLeastOne(opened), 1e-9);
		assertEquals(Math.exp(-1) / 2, Odds.luck(opened, 0), 1e-9);
		assertTrue(Odds.luck(opened, 2) > 0.8);
		assertEquals(451, Odds.runsFor(1 / 650.0, 0.5));
	}

	@Test
	public void paceLearnsFromRuns()
	{
		Pace p = new Pace();
		for (int i = 0; i < Pace.TRUSTED; i++)
		{
			p.urnTook(7);
		}
		assertEquals(7, p.urn(), 1e-9);
		p.urnTook(500);
		assertEquals(7, p.urn(), 1e-9);
	}

	@Test
	public void aRunIsFollowedRoomByRoom()
	{
		Pace p = new Pace();
		RunTracker t = new RunTracker();
		t.begin(0, 0, Goal.EXPERIENCE);
		t.room(Room.SEVEN, 0, p);
		t.urnSearched(10, p);
		t.urnSearched(18, p);
		t.chestOpened(25);
		t.thieving(675 * 2 + 450);
		t.room(Room.EIGHT, 45, p);
		t.sarcophagusOpened(60);
		t.strength(275);
		Run run = t.finish(100);
		assertEquals(8, run.getDeepest());
		assertEquals(2, run.getUrns());
		assertEquals(1, run.getChests());
		assertEquals(1, run.getSarcophagi());
		assertEquals(1 - (1 - 1 / 650.0) * (1 - 1 / 650.0), run.getSceptreChance(), 1e-9);
		assertEquals(1, p.getUrnSamples());
		assertEquals(1, p.getPassSamples());

		Logbook book = new Logbook();
		book.record(run, t.getOpened());
		assertEquals(2, book.openedTotal());
		assertEquals(1, book.getTotalRuns());
	}

	@Test
	public void theExperienceTableMatchesTheGame()
	{
		assertEquals(0, Levels.xpFor(1));
		assertEquals(83, Levels.xpFor(2));
		assertEquals(13_034_431, Levels.xpFor(99));
		assertEquals(91, Levels.levelFor(5_902_831));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class ReadyTest
{
	@Test
	public void theRouteWalksTheRoomOnceWithoutCrossingBack()
	{
		// Two rows of urns; nearest-first alone would zigzag between them.
		int[] xs = {0, 4, 8, 12, 0, 4, 8, 12};
		int[] ys = {0, 0, 0, 0, 6, 6, 6, 6};
		List<Integer> path = Route.order(0, 3, xs, ys, 8);
		assertEquals(8, path.size());
		assertEquals(8, path.stream().distinct().count());
		// One row there and the other back is 12 + 6 + 12 = 30 steps plus the 3 to reach the first.
		assertTrue("length " + Route.length(0, 3, xs, ys, path), Route.length(0, 3, xs, ys, path) <= 33);
	}

	@Test
	public void aShortPlanTakesTheNearestUrns()
	{
		int[] xs = {1, 2, 30, 31};
		int[] ys = {0, 0, 0, 0};
		List<Integer> path = Route.order(0, 0, xs, ys, 2);
		assertEquals(Arrays.asList(0, 1), path);
	}

	@Test
	public void theReadyCheckWarnsOfAFullPackAndLowHitpoints()
	{
		Plan plan = Planner.fresh(40, Goal.EXPERIENCE, new Pace());
		List<Check> checks = Check.ready(new Check.Kit(40, 10, 8, 2, false, false), plan, 6);
		assertEquals(Check.State.WARN, checks.get(0).getState());
		assertTrue(checks.stream().anyMatch(c -> c.getTitle().equals("Low hitpoints")));
		assertTrue(checks.stream().anyMatch(c -> c.getTitle().equals("Bring a snake charm")));
		assertTrue(checks.stream().anyMatch(c -> c.getTitle().equals("Bring a lockpick")));

		Plan high = Planner.fresh(91, Goal.EXPERIENCE, new Pace());
		List<Check> late = Check.ready(new Check.Kit(91, 70, 99, 20, true, true), high, 8);
		assertEquals(Check.State.GOOD, late.get(0).getState());
		assertTrue(late.stream().anyMatch(c -> c.getTitle().equals("Leave the snake charm")));
		assertTrue(late.stream().anyMatch(c -> c.getTitle().equals("Leave the lockpick")));
		assertTrue(late.stream().anyMatch(c -> c.getTitle().equals("Protect from Melee")));
	}

	@Test
	public void thePlaqueRaisesAWarningBeforeATipAndNothingWhenAllIsWell()
	{
		Plan plan = Planner.fresh(40, Goal.EXPERIENCE, new Pace());
		// Full pack, low hitpoints and no snake charm: the pack leads, a warning before any tip.
		Check urgent = Check.mostUrgent(Check.ready(new Check.Kit(40, 10, 8, 2, false, false), plan, 6));
		assertEquals(Check.State.WARN, urgent.getState());
		assertEquals("2 free slots", urgent.getTitle());
		// Room to spare and healthy, but no charm: the tip is raised.
		Check tip = Check.mostUrgent(Check.ready(new Check.Kit(40, 10, 40, 20, false, true), plan, 6));
		assertEquals("Bring a snake charm", tip.getTitle());
		// At 91 with the pack empty, no charm or lockpick and the Prayer for it, nothing is worth a plaque.
		Plan high = Planner.fresh(91, Goal.EXPERIENCE, new Pace());
		assertNull(Check.mostUrgent(Check.ready(new Check.Kit(91, 70, 99, 20, false, false), high, 8)));
	}

	@Test
	public void dangerComesBeforeThePlan()
	{
		Plan plan = Planner.plan(91, Goal.EXPERIENCE, new Pace(), new Here(Room.EIGHT, 13, false, false, true), 300);
		assertEquals(Step.Kind.URNS, Step.next(plan, true, false, 0).getKind());
		Step chased = Step.next(plan, true, false, 0, new Step.Alarm(false, false, true, true));
		assertEquals("Protect from Melee", chased.getTitle());
		assertEquals(Step.Kind.DANGER, Step.next(plan, true, false, 0, new Step.Alarm(true, false, false, false)).getKind());
		assertEquals("Eat first", Step.next(plan, true, false, 0, new Step.Alarm(true, true, false, false)).getTitle());
	}

	@Test
	public void slotsComeFromRecentRunsOnceThereAreThree()
	{
		Logbook book = new Logbook();
		Plan plan = Planner.fresh(91, Goal.EXPERIENCE, new Pace());
		assertTrue(book.slotsNeeded(plan, 10) > 0);
		for (int i = 0; i < 3; i++)
		{
			RunTracker t = new RunTracker();
			t.begin(0, 0, Goal.EXPERIENCE);
			t.room(Room.EIGHT, 0, null);
			t.urnSearched(5, null);
			t.artefacts(4 + i, 1000);
			book.record(t.finish(100), t.getOpened());
		}
		assertEquals(6, book.slotsNeeded(plan, 10));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** A damaged field costs only that field, whatever shape the damage takes. */
public class SalvageTest
{
	private static final Gson GSON = new Gson();

	static final class Saved
	{
		int kept;
		List<String> names;
		Map<String, Integer> counts;
	}

	@Test
	public void aListWhereAMapBelongsCostsOnlyThatField()
	{
		// A map where the list belongs once emptied every field, as "{}" does not read as a list.
		Saved s = Salvage.read(GSON, "{\"kept\":5,\"names\":{\"x\":1},\"counts\":{\"a\":1}}", Saved.class);
		assertEquals(5, s.kept);
		assertNull(s.names);
		assertEquals(1, (int) s.counts.get("a"));
		s = Salvage.read(GSON, "{\"kept\":5,\"names\":[\"a\"],\"counts\":[1,2]}", Saved.class);
		assertEquals(5, s.kept);
		assertEquals("a", s.names.get(0));
		// Gson reads a map from a list of pairs, so this one comes back empty rather than missing.
		assertTrue(s.counts == null || s.counts.isEmpty());
	}

	@Test
	public void badEntriesCostOnlyThemselves()
	{
		Saved s = Salvage.read(GSON, "{\"kept\":\"five\",\"names\":[\"a\",{},\"b\"],\"counts\":{\"a\":1,\"b\":\"x\"}}", Saved.class);
		assertEquals(0, s.kept);
		assertEquals(2, s.names.size());
		assertEquals(1, s.counts.size());
		assertTrue(Salvage.read(GSON, "[1]", Saved.class) == null);
	}

	@Test
	public void aSaveThisVersionKeepsWholeLosesNothing()
	{
		String own = "{\"kept\":5,\"names\":[\"a\"],\"counts\":{\"a\":1}}";
		assertFalse(Salvage.wouldLose(GSON, own, Salvage.read(GSON, own, Saved.class)));
		// An older save that lacks a field, or nothing saved at all, loses nothing either.
		String older = "{\"kept\":5}";
		assertFalse(Salvage.wouldLose(GSON, older, Salvage.read(GSON, older, Saved.class)));
		assertFalse(Salvage.wouldLose(GSON, null, null));
		assertFalse(Salvage.wouldLose(GSON, "", null));
	}

	@Test
	public void aNewerOrDamagedSaveWouldLoseWhatItHolds()
	{
		// A field a newer version added, a value of a shape this one cannot read, and garbage.
		String newer = "{\"kept\":5,\"names\":[\"a\"],\"added\":{\"x\":1}}";
		assertTrue(Salvage.wouldLose(GSON, newer, Salvage.read(GSON, newer, Saved.class)));
		String damaged = "{\"kept\":\"five\",\"names\":[\"a\",{},\"b\"]}";
		assertTrue(Salvage.wouldLose(GSON, damaged, Salvage.read(GSON, damaged, Saved.class)));
		assertTrue(Salvage.wouldLose(GSON, "{\"kept\":5", null));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class SceptreTest
{
	@Test
	public void messagesAboutThePharaohsSceptreAreRead()
	{
		assertEquals(Integer.valueOf(23), Sceptre.parse("Your Pharaoh's sceptre has 23 charges left."));
		assertEquals(Integer.valueOf(1), Sceptre.parse("<col=ff0000>Your sceptre has 1 charge left.</col>"));
		assertEquals(Integer.valueOf(0), Sceptre.parse("Your sceptre has no charges left."));
		assertNull(Sceptre.parse("Your Skull sceptre has 4 charges left."));
		assertNull(Sceptre.parse("Your Thammaron's sceptre has 500 charges left."));
		assertNull(Sceptre.parse("You have 3 charges left."));
	}

	@Test
	public void theVariableIsOnlyBelievedOnceAMessageAgreesWithIt()
	{
		Sceptre s = new Sceptre();
		assertEquals(-1, s.charges(40));
		s.heard(12);
		assertEquals(12, s.charges(40));
		s.compare(12);
		assertTrue(s.isLive());
		assertEquals(11, s.charges(11));
	}

	@Test
	public void aVariableThatDisagreesIsNeverBelievedAgain()
	{
		Sceptre s = new Sceptre();
		s.heard(12);
		s.compare(3);
		assertFalse(s.isLive());
		assertEquals(12, s.charges(3));
		s.heard(11);
		s.compare(11);
		assertFalse(s.isLive());
		assertEquals(11, s.charges(99));
	}

	@Test
	public void theReadyCheckSpeaksOfTheSceptre()
	{
		Plan plan = Planner.fresh(91, Goal.EXPERIENCE, new Pace());
		List<Check> empty = Check.ready(new Check.Kit(91, 70, 90, 20, false, false).sceptre(Check.SceptreKit.UNCHARGED, 0, false, Check.SceptreKit.NONE), plan, 6);
		assertTrue(empty.stream().anyMatch(c -> c.getState() == Check.State.WARN && c.getTitle().equals("Sceptre has no charges")));
		List<Check> low = Check.ready(new Check.Kit(91, 70, 90, 20, false, false).sceptre(Check.SceptreKit.CHARGED, 2, true, Check.SceptreKit.NONE), plan, 6);
		assertTrue(low.stream().anyMatch(c -> c.getTitle().equals("Sceptre: 2 charges")));
		List<Check> banked = Check.ready(new Check.Kit(91, 70, 90, 20, false, false).sceptre(Check.SceptreKit.NONE, -1, false, Check.SceptreKit.CHARGED), plan, 6);
		assertTrue(banked.stream().anyMatch(c -> c.getTitle().equals("Bring your sceptre")));
		List<Check> none = Check.ready(new Check.Kit(91, 70, 90, 20, false, false), plan, 6);
		assertFalse(none.stream().anyMatch(c -> c.getTitle().contains("ceptre")));
	}

	private static Check sceptreCheck(Check.SceptreKit carried, int charges, boolean live, Check.SceptreKit banked)
	{
		return Check.sceptre(new Check.Kit(91, 70, 90, 20, false, false).sceptre(carried, charges, live, banked));
	}

	@Test
	public void aChargedSceptreIsNeverCalledEmptyByAStaleCount()
	{
		// The last message said none left, then the sceptre was recharged with no message read:
		// the item is the charged one, so the count of none is out of date, not a reason to warn.
		Check c = sceptreCheck(Check.SceptreKit.CHARGED, 0, false, Check.SceptreKit.NONE);
		assertEquals(Check.State.GOOD, c.getState());
		assertEquals("Pharaoh's sceptre", c.getTitle());
	}

	@Test
	public void aCountKeptFromTheLastCheckSaysSo()
	{
		assertTrue(sceptreCheck(Check.SceptreKit.CHARGED, 8, false, Check.SceptreKit.NONE).getDetail().startsWith("At its last check"));
		assertFalse(sceptreCheck(Check.SceptreKit.CHARGED, 8, true, Check.SceptreKit.NONE).getDetail().contains("last check"));
	}

	@Test
	public void anEmptySceptreInTheBankIsToBeRechargedNotBrought()
	{
		Check c = sceptreCheck(Check.SceptreKit.NONE, -1, false, Check.SceptreKit.UNCHARGED);
		assertEquals("Recharge your sceptre", c.getTitle());
		assertNull(sceptreCheck(Check.SceptreKit.NONE, -1, false, Check.SceptreKit.NONE));
	}

	@Test
	public void theBankIsRememberedWithItsCharge()
	{
		Sceptre s = new Sceptre();
		assertNull(s.getBanked());
		assertTrue(s.setBanked(Check.SceptreKit.UNCHARGED));
		assertEquals(Check.SceptreKit.UNCHARGED, s.getBanked());
		assertFalse(s.setBanked(Check.SceptreKit.UNCHARGED));
		assertTrue(s.setBanked(Check.SceptreKit.CHARGED));
		assertTrue(s.setBanked(Check.SceptreKit.NONE));
		assertEquals(Check.SceptreKit.NONE, s.getBanked());
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class SceptreWatchTest
{
	@Test
	public void aSceptreFoundInARunCounts()
	{
		SceptreWatch w = new SceptreWatch();
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(0, true, 100));
		assertEquals(SceptreWatch.Seen.FOUND, w.tick(1, true, 101));
		// Moved from the pack to the hand: still one.
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(1, false, 102));
	}

	@Test
	public void theOneThatLandsAsTheRunEndsCountsForIt()
	{
		SceptreWatch w = new SceptreWatch();
		w.tick(0, true, 100);
		w.runEnded(101);
		assertEquals(SceptreWatch.Seen.FOUND_AFTER, w.tick(1, false, 103));
	}

	@Test
	public void thePackArrivingAfterALoginIsNoFind()
	{
		SceptreWatch w = new SceptreWatch();
		w.tick(0, true, 100);
		// The run ends because the player logs out; the client's tick count starts again on login.
		w.runEnded(5000);
		w.reset();
		// The first ticks after login: the pack has not arrived, then it holds a sceptre from the bank.
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(-1, false, 1));
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(1, false, 2));
	}

	@Test
	public void withoutAResetAStalePackStillIsNotAFind()
	{
		SceptreWatch w = new SceptreWatch();
		w.tick(0, false, 10);
		// The pack goes unknown for a tick (a hop) and comes back with the sceptre it had all along.
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(-1, false, 11));
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(1, false, 12));
	}

	@Test
	public void longAfterARunASceptreIsSomethingElse()
	{
		SceptreWatch w = new SceptreWatch();
		w.tick(0, true, 100);
		w.runEnded(101);
		assertEquals(SceptreWatch.Seen.NOTHING, w.tick(0, false, 102));
		assertEquals(SceptreWatch.Seen.OTHER, w.tick(1, false, 101 + SceptreWatch.GRACE_TICKS + 1));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class SessionTest
{
	private static final long MIN = 60_000L;

	/** A five minute run starting at the given minute. */
	private static Run run(long startMinute, int xp, double sceptre, boolean found)
	{
		return new Run(startMinute * MIN, 500, 8, xp, 0, 20, 2, 0, 1000, 2, sceptre, found, Goal.EXPERIENCE);
	}

	@Test
	public void aBreakEndsTheSession()
	{
		Session s = Session.latest(Arrays.asList(run(0, 30_000, 0, false), run(60, 40_000, 0.01, false), run(66, 42_000, 0.01, false)),
			72 * MIN);
		assertEquals(2, s.getRuns().size());
		assertEquals(82_000, s.getXp());
		assertTrue(s.isCurrent());
	}

	@Test
	public void theRateCountsTheWalkBackBetweenRuns()
	{
		// Two runs six minutes apart: 5 + 1 + 5 minutes of play, plus one walk back (36s) after the last.
		Session s = Session.latest(Arrays.asList(run(0, 50_000, 0, false), run(6, 50_000, 0, false)), 12 * MIN);
		long span = 11 * MIN + 36_000;
		assertEquals(span, s.spanMs());
		assertEquals(Math.round(100_000 * 3_600_000.0 / span), s.xpPerHour());
	}

	@Test
	public void theSceptreChanceCompoundsAcrossRuns()
	{
		Session s = Session.latest(Arrays.asList(run(0, 1, 0.01, false), run(6, 1, 0.02, false)), 12 * MIN);
		assertEquals(1 - 0.99 * 0.98, s.getSceptreChance(), 1e-9);
		assertEquals(0, s.getSceptres());
	}

	@Test
	public void anOldSessionIsShownAsTheLastOne()
	{
		Session s = Session.latest(Arrays.asList(run(0, 1, 0, false), run(6, 9, 0, true)), 600 * MIN);
		assertFalse(s.isCurrent());
		assertEquals(1, s.getSceptres());
		assertEquals(9, s.best().getThievingXp());
		assertTrue(Session.latest(Collections.emptyList(), 0).isEmpty());
	}

	@Test
	public void historySplitsEveryRunIntoSessionsNewestFirst()
	{
		// Three sittings: two runs at minute 0, three around minute 100, one at minute 300 still going.
		java.util.List<Run> runs = Arrays.asList(run(0, 10_000, 0, false), run(6, 10_000, 0, false),
			run(100, 30_000, 0, false), run(106, 30_000, 0, false), run(112, 30_000, 0, false),
			run(300, 90_000, 0, false));
		java.util.List<Session> all = Session.history(runs, 306 * MIN);
		assertEquals(3, all.size());
		assertEquals(1, all.get(0).getRuns().size());
		assertTrue(all.get(0).isCurrent());
		assertEquals(3, all.get(1).getRuns().size());
		assertFalse(all.get(1).isCurrent());
		assertEquals(2, all.get(2).getRuns().size());
		// The newest agrees with latest().
		assertEquals(Session.latest(runs, 306 * MIN).getXp(), all.get(0).getXp());
		// The lone 90k run is quicker, but too short to be called the best session.
		assertTrue(all.get(0).xpPerHour() > all.get(1).xpPerHour());
		assertEquals(all.get(1), Session.best(all));
		assertTrue(Session.history(Collections.emptyList(), 0).isEmpty());
		assertEquals(null, Session.best(Session.history(runs.subList(0, 2), 0)));
	}

	@Test
	public void aRunJustOverTheBreakStartsANewSession()
	{
		// A five minute run ending at minute 5; the next starts exactly 20 minutes later, then just after.
		assertEquals(1, Session.history(Arrays.asList(run(0, 1, 0, false), run(25, 1, 0, false)), 30 * MIN).size());
		assertEquals(2, Session.history(Arrays.asList(run(0, 1, 0, false), new Run(25 * MIN + 1, 500, 8, 1, 0, 20, 2, 0, 1000, 2, 0, false,
			Goal.EXPERIENCE)), 30 * MIN).size());
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

/**
 * Reads exactly what the other Codex plugins save. {@code bank-steward-bankV1.json} is a copy of
 * the fixture Bank Steward's own BankSnapshotTest proves its writer produces;
 * {@code gear-roadmap-bank.json} was written by Gear Roadmap's own {@code Bank} class with Gson.
 */
public class SharedBankContractTest
{
	private static final Gson GSON = new Gson();

	static String fixture(String name) throws Exception
	{
		try (InputStream in = SharedBankContractTest.class.getResourceAsStream(name))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[4096];
			for (int n; (n = in.read(buf)) > 0; )
			{
				out.write(buf, 0, n);
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8).trim();
		}
	}

	@Test
	public void groupsAndKeysMatchTheWriters()
	{
		// CodexBankStewardConfig.GROUP and BankSnapshot.KEY; CodexGearRoadmapConfig.GROUP and BANK_KEY.
		assertEquals("codexbanksteward", SharedBank.STEWARD_GROUP);
		assertEquals("bankV1", SharedBank.STEWARD_KEY);
		assertEquals("codexgearroadmap", SharedBank.ROADMAP_GROUP);
		assertEquals("bank", SharedBank.ROADMAP_KEY);
	}

	@Test
	public void bankStewardSnapshotHoldsEveryItemWithItsCount() throws Exception
	{
		SharedBank bank = SharedBank.read(GSON, fixture("bank-steward-bankV1.json"), null);
		assertSame(SharedBank.Source.BANK_STEWARD, bank.getSource());
		assertTrue(bank.isComplete());
		assertEquals(1_760_000_000_000L, bank.getSavedAt());
		assertEquals(1, bank.count(26950));
		assertEquals(1, bank.count(11666));
		assertEquals(240, bank.count(385));
		assertEquals(1_234_567, bank.count(995));
		assertEquals(0, bank.count(4151));
	}

	@Test
	public void gearRoadmapBankIsTheFallbackAndOnlyHalfTheStory() throws Exception
	{
		String roadmap = fixture("gear-roadmap-bank.json");
		SharedBank bank = SharedBank.read(GSON, null, roadmap);
		assertSame(SharedBank.Source.GEAR_ROADMAP, bank.getSource());
		assertFalse(bank.isComplete());
		assertEquals(0, bank.getSavedAt());
		assertEquals(1, bank.count(26948));
		assertEquals(1, bank.count(8839));
		assertEquals(1_234_567, bank.count(995));
		assertEquals("it never saves a fresh sceptre", 0, bank.count(26950));

		// Bank Steward's wins when both are there, and an unreadable one falls through.
		assertSame(SharedBank.Source.BANK_STEWARD, SharedBank.read(GSON, fixture("bank-steward-bankV1.json"), roadmap).getSource());
		assertSame(SharedBank.Source.GEAR_ROADMAP, SharedBank.read(GSON, "{\"version\":1}", roadmap).getSource());
		assertSame(SharedBank.Source.GEAR_ROADMAP, SharedBank.read(GSON, "not json {", roadmap).getSource());
	}

	@Test
	public void nothingSavedIsNoBank()
	{
		assertNull(SharedBank.read(GSON, null, null));
		assertNull(SharedBank.read(GSON, "", "  "));
		assertNull(SharedBank.read(GSON, "[1,2]", "{\"coins\":5}"));
		// Odd values inside a readable snapshot are skipped, not fatal.
		SharedBank odd = SharedBank.read(GSON, "{\"items\":{\"x\":1,\"995\":\"many\",\"385\":-2,\"391\":3},\"truncated\":true}", null);
		assertEquals(1, odd.getItems().size());
		assertEquals(3, odd.count(391));
		assertFalse("a truncated snapshot may miss items", odd.isComplete());
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class SplitsTest
{
	/** A run to the given room, entering each room at the given ticks. */
	private static Run run(Goal goal, int... entered)
	{
		RunTracker t = new RunTracker();
		t.begin(0, 0, goal);
		for (int i = 0; i < entered.length; i++)
		{
			t.room(Room.values()[i], entered[i], null);
		}
		t.thieving(100);
		return t.finish(entered[entered.length - 1] + 50);
	}

	@Test
	public void theBestIsTheFastestToTheDeepestRoomAndEachRoomKeepsItsQuickestCrossing()
	{
		List<Run> runs = Arrays.asList(
			run(Goal.EXPERIENCE, 0, 20, 40, 70, 100),
			run(Goal.EXPERIENCE, 0, 18, 45, 75, 98),
			run(Goal.EXPERIENCE, 0, 25, 41, 66, 104));
		Splits s = Splits.of(runs, Goal.EXPERIENCE, Room.FIVE);
		assertEquals(3, s.getCompared());
		assertEquals(98, s.bestAt(Room.FIVE));
		assertEquals(45, s.bestAt(Room.THREE));
		// Room 1 quickest 18, room 2 16, room 3 25, room 4 23.
		assertEquals(18, s.bestSegment(Room.ONE));
		assertEquals(16, s.bestSegment(Room.TWO));
		assertEquals(25, s.bestSegment(Room.THREE));
		assertEquals(23, s.bestSegment(Room.FOUR));
		assertEquals(82, s.sumOfBest());
		assertEquals(Integer.valueOf(-3), s.delta(Room.THREE, 42));
	}

	@Test
	public void otherGoalsAndShorterRunsAreNotCompared()
	{
		List<Run> runs = Arrays.asList(
			run(Goal.SCEPTRE, 0, 10, 20, 30, 40),
			run(Goal.EXPERIENCE, 0, 10, 20, 30));
		Splits s = Splits.of(runs, Goal.EXPERIENCE, Room.FIVE);
		assertFalse(s.hasBest());
		assertEquals(0, s.getCompared());
		assertNull(s.delta(Room.FIVE, 90));
		assertEquals(-1, s.sumOfBest());
	}

	@Test
	public void aRunJoinedMidwayNeverSetsAFalseBest()
	{
		// The plugin started in room 3: rooms 1 and 2 were never seen, room 3 only when first seen.
		RunTracker t = new RunTracker();
		t.begin(0, 0, Goal.EXPERIENCE);
		t.room(Room.THREE, 60, null);
		t.room(Room.FOUR, 90, null);
		t.room(Room.FIVE, 120, null);
		t.thieving(10);
		Run late = t.finish(200);
		assertEquals(-1, late.splitAt(Room.ONE));
		assertEquals(-1, Splits.segment(late, Room.TWO));
		Splits s = Splits.of(Arrays.asList(run(Goal.EXPERIENCE, 0, 20, 40, 70, 100)), Goal.EXPERIENCE, Room.FIVE);
		assertFalse(s.isNewBest(late, Goal.EXPERIENCE));
	}

	@Test
	public void aNewBestIsOnlyANewBestAgainstTheRunsBefore()
	{
		List<Run> before = new ArrayList<>(Arrays.asList(run(Goal.EXPERIENCE, 0, 20, 40, 70, 100)));
		Run faster = run(Goal.EXPERIENCE, 0, 19, 38, 66, 95);
		Run slower = run(Goal.EXPERIENCE, 0, 21, 44, 72, 101);
		Splits s = Splits.of(before, Goal.EXPERIENCE, Room.FIVE);
		assertTrue(s.isNewBest(faster, Goal.EXPERIENCE));
		assertFalse(s.isNewBest(slower, Goal.EXPERIENCE));
	}

	@Test
	public void oldSavesWithoutSplitsAreSkipped()
	{
		Run old = new Run(0, 400, 5, 9000, 0, 10, 1, 0, 0, 0, 0.001, false, Goal.EXPERIENCE);
		assertEquals(-1, old.splitAt(Room.FIVE));
		assertFalse(Splits.comparable(old, Goal.EXPERIENCE, Room.FIVE));
		assertEquals(0, Splits.of(Arrays.asList(old), Goal.EXPERIENCE, Room.FIVE).getCompared());
	}

	@Test
	public void theSlowestRoomIsTheOneMostOverItsQuickest()
	{
		List<Run> runs = Arrays.asList(
			run(Goal.EXPERIENCE, 0, 20, 40, 70, 100),
			run(Goal.EXPERIENCE, 0, 18, 45, 75, 98));
		Splits s = Splits.of(runs, Goal.EXPERIENCE, Room.FIVE);
		// Quickest: 18, 20, 30, 23. This run: 19, 21, 42, 24.
		Run run = run(Goal.EXPERIENCE, 0, 19, 40, 82, 106);
		assertEquals(Room.THREE, s.slowest(run));
		assertEquals(12, s.overrun(run, Room.THREE));
		// Within three seconds everywhere names nothing.
		assertNull(s.slowest(run(Goal.EXPERIENCE, 0, 19, 40, 72, 96)));
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;

public class StashTest
{
	private static final List<Integer> ARTEFACTS = Arrays.asList(ItemID.NTK_IVORY_COMB, ItemID.NTK_STATUETTE_GOLD);
	private static final String STEWARD = "{\"version\":1,\"savedAt\":500000,\"items\":{\"995\":100,\""
		+ ItemID.NTK_STATUETTE_GOLD + "\":7},\"truncated\":false}";

	@Test
	public void theNewerLookAtTheBankWins()
	{
		SharedBank steward = SharedBank.read(new Gson(), STEWARD, null);
		Map<Integer, Long> own = new HashMap<>();
		own.put(ItemID.NTK_IVORY_COMB, 3L);
		Stash older = Stash.pick(own, 400_000, steward, ARTEFACTS);
		assertEquals(SharedBank.Source.BANK_STEWARD, older.getFrom());
		assertEquals(Collections.singletonMap(ItemID.NTK_STATUETTE_GOLD, 7L), older.getItems());
		Stash newer = Stash.pick(own, 600_000, steward, ARTEFACTS);
		assertNull(newer.getFrom());
		assertEquals(3, newer.count());
		assertEquals(600_000, newer.getSeenAt());
	}

	@Test
	public void gearRoadmapsBankSaysNothingAboutArtefacts()
	{
		SharedBank roadmap = SharedBank.read(new Gson(), null, "{\"items\":[" + ItemID.NTK_STATUETTE_GOLD + "],\"coins\":5}");
		assertNull(Stash.pick(Collections.emptyMap(), 0, roadmap, ARTEFACTS));
		assertNull(Stash.pick(null, 0, null, ARTEFACTS));
		// An empty bank seen here is still a look: none banked.
		assertEquals(0, Stash.pick(Collections.emptyMap(), 10, roadmap, ARTEFACTS).count());
	}

	@Test
	public void theLogbookKeepsTheBankedArtefactsThroughASave()
	{
		Logbook book = new Logbook();
		Map<Integer, Long> seen = new HashMap<>();
		seen.put(ItemID.NTK_IVORY_COMB, 2L);
		assertEquals(true, book.setBanked(seen, 100));
		assertEquals(false, book.setBanked(seen, 100));
		// The same artefacts seen later still need saving: the look's time is what the Steward's is weighed against.
		assertEquals(true, book.setBanked(seen, 200));
		assertEquals(200, book.getBankedAt());
		Logbook back = new Gson().fromJson(new Gson().toJson(book), Logbook.class).repair();
		assertEquals(Long.valueOf(2), back.getBanked().get(ItemID.NTK_IVORY_COMB));
		assertEquals(200, back.getBankedAt());
		assertEquals(0, new Gson().fromJson("{}", Logbook.class).repair().getBanked().size());
	}

	@Test
	public void theSameBankVisitIsCreditedToThisPlugin()
	{
		// Both plugins saw the bank on the same visit, Bank Steward a few ticks later.
		SharedBank steward = SharedBank.read(new Gson(), STEWARD, null);
		Stash same = Stash.pick(Collections.singletonMap(ItemID.NTK_STATUETTE_GOLD, 7L), 500_000 - 1200, steward, ARTEFACTS);
		assertNull(same.getFrom());
		assertEquals(500_000 - 1200, same.getSeenAt());
	}

	@Test
	public void anUnchangedBankVisitIsStillThisPluginsAfterARestart()
	{
		Gson gson = new Gson();
		Logbook book = new Logbook();
		Map<Integer, Long> seen = new HashMap<>();
		seen.put(ItemID.NTK_STATUETTE_GOLD, 7L);
		book.setBanked(seen, 100_000);
		String saved = gson.toJson(book);
		// Back at the bank much later, nothing changed. Bank Steward saves the same visit a moment after.
		if (book.setBanked(seen, 480_000))
		{
			saved = gson.toJson(book);
		}
		Logbook restarted = gson.fromJson(saved, Logbook.class).repair();
		SharedBank steward = SharedBank.read(gson, STEWARD, null);
		Stash stash = Stash.pick(restarted.getBanked(), restarted.getBankedAt(), steward, ARTEFACTS);
		assertNull(stash.getFrom());
		assertEquals(480_000, stash.getSeenAt());
	}
}

package com.codex.plunder.core;

import static org.junit.Assert.assertEquals;
